window.__Q=window.__Q||{};window.__Q["tcm/2/A2"]=[{"q":"患者，男，45岁。素有肝疾，常有右胁部刺痛感，夜间加重，舌紫边有瘀斑。其脉象可见","o":["代脉","散脉","革脉","牢脉","涩脉"],"a":4,"e":"涩脉主气滞、血瘀、精血亏虚与痰食内停，脉来艰涩不畅。右胁刺痛夜甚、舌紫有瘀斑为瘀血内阻之象，血行不畅故脉涩。"},{"q":"患者，男，60岁。患者平素有尿血病史，西医诊断为泌尿系感染，观察其面部淡白，心悸失眠，少气懒言，舌淡白，脉弱。辨证为","o":["气血两虚证","气虚血瘀证","气不摄血证","气随血脱证","气滞血瘀证"],"a":2,"e":"气不摄血证以气虚见症兼出血为特点，因脾气虚弱、统摄无权而血溢脉外。久病尿血伴少气懒言、面淡白、舌淡脉弱，正是气虚无以摄血。"},{"q":"口气臭秽难闻，牙龈腐烂者，多为","o":["胃热","食积胃肠","龋齿","牙疳","消化不良"],"a":3,"e":"口气臭秽难闻兼牙龈腐烂者为牙疳，多因胃经热毒上攻或疫毒熏蒸牙龈所致。单纯口气臭秽多属胃热、食积，牙龈并无腐溃。"},{"q":"患者，男，55岁。高血压病史10年，常感头目眩晕不适，曾服中、西药治疗但无显效，近1个月来症状加重。症见头目眩晕如坐舟船，耳鸣时轻时重，面红目赤，急燥易怒，腰膝酸软，头重脚轻，步履不稳，失眠多梦，舌质红，脉弦细数。其病证机理多属","o":["肝阳上亢","气血两亏","痰湿内阻","肾精亏虚","肝火上炎"],"a":0,"e":"眩晕如坐舟船、耳鸣、面红目赤、急躁易怒，兼腰膝酸软、头重脚轻、步履不稳，为肝阳上亢、上盛下虚之候，舌红脉弦细数示阴亏阳亢。"},{"q":"患者精神沮丧，意志消沉，面色惨淡，神疲乏力，宜诊断为","o":["喜伤证","悲伤证","思伤证","惊伤证","恐伤证"],"a":1,"e":"悲忧伤肺，悲则气消，肺主气而朝百脉，气消则神失所养，故精神沮丧、意志消沉、面色惨淡、神疲乏力。"},{"q":"患者，男，60岁。面色黄而虚浮，辨证为","o":["气血亏虚","气滞血瘀","脾胃虚寒","肾阳亏虚","脾虚湿蕴"],"a":4,"e":"面色黄而虚浮即黄胖，为脾虚失运、水湿内停所致。脾虚则气血不足而色黄，湿蕴则面部虚浮不泽。"},{"q":"患者，女，18岁。近半个月因复习考试，每日入睡较晚且夜寐多梦，心烦，口渴，便秘溲黄，舌尖部有烧灼感，可见红刺，苔黄，脉数。其病证机理为","o":["心火亢盛","肝胆火旺","痰火内扰","热陷心包","胃火亢盛"],"a":0,"e":"心烦失眠、口渴便秘溲黄、舌尖红赤生红刺、苔黄、脉数，为心火亢盛、火性炎上。舌为心之苗，舌尖属心，故火盛先现于舌尖。"},{"q":"患者，男，23岁。3天来恶寒发热，鼻塞流浊涕，头痛咽痛，咳嗽，口干，稍有汗出，舌尖红，苔薄黄，脉浮数。属于","o":["风热表证","风热犯肺","痰湿阻肺","痰热壅肺","阴虚肺燥"],"a":0,"e":"恶寒发热、鼻塞流浊涕、头痛咽痛、口干汗出、舌尖红苔薄黄、脉浮数，为风热之邪袭表、卫表失和。病位在表而未成肺之里热，故属风热表证。"},{"q":"患者自觉胸闷善太息，胁肋胃脘胀满，嗳气，吞酸嘈杂，情志抑郁，舌苔薄白，脉弦略数。宜诊断为","o":["肝气郁结证","胃热证","食滞胃脘证","肝脾不调证","肝胃不和证"],"a":4,"e":"情志抑郁而胸闷善太息、胁肋胃脘胀满、嗳气吞酸嘈杂、脉弦，为肝气郁结、横逆犯胃、胃失和降。病位在肝胃两脏，故属肝胃不和证。"},{"q":"患者，女，32岁。3年前于产后出现畏寒肢冷，秋冬尤甚，得温可缓。现症见畏寒肢冷，腰膝酸冷，乏力自汗，食少腹胀，大便溏薄，夜尿频多，舌淡胖有齿痕，苔白滑，脉沉迟无力。其汗出的病机是","o":["血虚","气陷","气脱","津液不足","阳气亏虚"],"a":4,"e":"畏寒肢冷、腰膝酸冷、夜尿频多、食少腹胀便溏、舌淡胖有齿痕、脉沉迟无力，为脾肾阳气亏虚。阳虚不能固表、腠理不密，故自汗，其机在阳气亏虚。"},{"q":"咳嗽阵作，痰黄黏稠，面红目赤，躁热易怒，舌红苔黄，脉数。应诊断为","o":["痰热蕴肺证","肺热炽盛证","肝火犯肺证","肺燥津亏证","风热犯肺证"],"a":2,"e":"咳嗽阵作、痰黄黏稠，兼面红目赤、躁热易怒，为肝火循经上逆犯肺、木火刑金之候。单纯痰热蕴肺无面红易怒之肝火征象。"},{"q":"患者，女，64岁。诉皮肤干燥，口唇干，不渴，平时经常用化妆品敷脸，但是仍然不解，舌红少津，脉细，辨证为","o":["阴虚火旺证","津液亏虚证","血热证","血脱证","血寒证"],"a":1,"e":"皮肤干燥、口唇干而不渴、舌红少津、脉细，为津液亏少、肌肤失于濡润。尚无五心烦热、颧红等虚火之象，故属津液亏虚而未至阴虚火旺。"},{"q":"患者，男，49岁。自诉数日前与人争吵后出现耳鸣，逐渐加重，现听力下降，伴有头痛而胀，烦躁易怒，失眠多梦，大便秘结，小便短黄，舌红苔黄，脉弦数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","寒滞肝脉证"],"a":1,"e":"恼怒后耳鸣耳聋、头痛而胀、烦躁易怒、便秘溲黄、舌红苔黄、脉弦数，为肝火上炎、循经上扰清窍。病性属实火，无腰膝酸软之下虚见症。"},{"q":"患者，男，32岁。发热，微恶风寒，少汗，口鼻干燥，咽喉干痛，干咳少痰，舌红，苔薄白而干，脉浮数，其临床意义是","o":["风热犯卫","燥热犯肺","湿热犯卫","热扰胸膈","热邪壅肺"],"a":1,"e":"发热微恶风寒、口鼻干燥、咽喉干痛、干咳少痰、苔薄白而干，为燥热之邪犯肺伤津、肺失濡润。燥胜则干，故燥象突出而寒热较轻。"},{"q":"胸胁胀痛，胸闷喜太息，纳少，腹胀便溏，肠鸣矢气。宜诊断为","o":["肝气郁结证","脾胃气虚证","肝脾不和证","肝胃不和证","肝胆湿热证"],"a":2,"e":"胸胁胀痛、胸闷喜太息为肝气郁滞，纳少、腹胀便溏、肠鸣矢气为脾失健运，两者并见属肝脾不和。肝木乘脾、气机不畅，故胀痛与便溏同现。"},{"q":"郭某，男，5岁。家长叙述，患儿鼻塞流清涕3天，微有发热，精神尚可，饮食如常，未予重视。今日从幼儿园回家，精神不振，体温升高，口渴喜饮，不欲进食咀嚼，左腮部漫肿压痛。该患儿最应重点询问的内容是","o":["是否受风着凉","是否饮食积滞","预防接种史","传染病接触史","是否受惊吓"],"a":3,"e":"患儿腮部漫肿压痛，伴发热、咀嚼不便，高度提示痄腮，属温毒所致的呼吸道传染病。询问传染病接触史可判断流行性与潜伏期，故为问诊重点。"},{"q":"患者，男，12岁。左侧腮部以耳垂为中心肿起，边缘不清，皮色不红，疼痛，按之有触痛者，最可能的诊断是","o":["抱头火丹","大头瘟","痄腮","发颐","面肿"],"a":2,"e":"以耳垂为中心漫肿、边缘不清、皮色不红、按之疼痛，为痄腮的典型表现，由温毒侵袭少阳经脉、气血壅滞而成。发颐多红肿热痛明显且有脓。"},{"q":"病人发热1天，伴汗出，恶风，脉浮，其证属","o":["太阳中风证","太阳伤寒证","太阳蓄水证","太阳蓄血证","少阳病证"],"a":0,"e":"发热汗出、恶风、脉浮，为风邪袭表、营卫不和、腠理疏松之太阳中风证。太阳伤寒则寒邪束表，无汗而脉浮紧。"},{"q":"患儿，男，9岁。昨晚食冰水后出现腹痛，食少，便溏，泛恶欲吐，小便短少，舌淡胖苔白腻，脉濡缓。诊为","o":["脾阳虚证","寒湿困脾证","肠燥津亏证","寒滞胃脘证","食滞胃脘证"],"a":1,"e":"贪凉饮冷后腹痛便溏、泛恶欲吐、小便短少、舌淡胖苔白腻、脉濡缓，为寒湿内盛、困阻脾阳、运化失职。起病急、苔腻脉濡，属实证而非脾阳虚。"},{"q":"患者，男，50岁。心悸反复发作2个月，伴心烦，眠浅多梦，时有盗汗，平素形体较瘦，口燥咽干，自觉午后低热，颧红，舌红少苔，脉细数。此属下列何证","o":["心阴虚证","肝阴虚证","心肾不交证","心血虚证","心火上炎证"],"a":0,"e":"心悸心烦、失眠多梦、盗汗、口燥咽干、午后低热颧红、舌红少苔、脉细数，为心阴亏虚、虚热内扰、心神失养。无腰膝酸软耳鸣，故不属心肾不交。"},{"q":"患者，男。腹部胀大如鼓，按之如囊裹水者，多为","o":["气臌","实满","水鼓","虚满","虫臌"],"a":2,"e":"腹部胀大如鼓、按之如囊裹水，为水鼓，因水湿内停、气化不利、水积腹中所致。气臌按之空空然、抬手即起，与水鼓之囊裹水感不同。"},{"q":"患者神思恍惚，食少纳呆，腹胀脘痞，面色萎黄，失眠消瘦，宜诊断为","o":["喜伤证","忧伤证","思伤证","悲伤证","恐伤证"],"a":2,"e":"思虑过度伤脾，气机郁结、运化失职，故神思恍惚、食少纳呆、腹胀脘痞、面色萎黄、失眠消瘦。思伤证以脾气郁结、脾虚不运为主。"},{"q":"患者，女，68岁。望诊面色黧黑，肌肤甲错，辨证为","o":["肾虚","水饮","寒盛","气滞","血瘀"],"a":4,"e":"面色黧黑兼肌肤甲错，为瘀血内阻、气血不能上荣外养之征。瘀血日久，肌肤失于濡润，故粗糙如鳞甲交错。"},{"q":"干咳痰少，声音嘶哑，颧红潮热，遗精，脉细数，宜诊断为","o":["肺肾阴虚证","肺燥伤津证","阴虚火旺证","肾阴亏虚证","肺阴亏虚证"],"a":0,"e":"干咳痰少、声音嘶哑为肺阴不足、肺失濡润；遗精、颧红潮热、脉细数为肾阴亏虚。金水相生，肺病及肾，两脏同病故为肺肾阴虚证。"},{"q":"石某，男，38岁。近3日出现纳呆食少，烦躁，呕恶腹胀，脘痞身重，小便发黄，其舌象可见","o":["舌质淡白，苔润滑","舌质绛红，苔黄燥","舌质红，苔黄腻","舌质黯，苔薄白","舌质淡红，苔白腻"],"a":2,"e":"纳呆呕恶、烦躁、脘痞身重、小便发黄，为湿热中阻、熏蒸脾胃之候。湿盛则苔腻，热盛则舌红苔黄，故舌质红、苔黄腻。"},{"q":"患者近期急躁易怒，胸胁走窜疼痛，甚至刺痛，舌质紫黯，脉弦。属于","o":["气虚血瘀证","气滞血瘀证","气血两虚证","气不摄血证","气随血脱证"],"a":1,"e":"胸胁走窜疼痛属气滞，痛处固定、舌质紫黯属血瘀，舌紫脉弦为气滞血瘀之征。气为血帅，气滞日久则血行瘀阻。"},{"q":"患者牙齿松动，牙根宣露，齿龈溃烂萎缩，溃烂边缘微红肿。宜诊断为","o":["胃火亢盛","肾阴亏损","气血不足","心脾积热","肝胆火旺"],"a":1,"e":"牙齿松动、牙根宣露、齿龈溃烂萎缩而边缘微红肿，为肾阴亏虚、虚火上炎、齿失所养。胃火亢盛者齿龈红肿疼痛明显，无萎缩宣露。"},{"q":"患者，女，35岁。自述秋季面色微白，入冬之后面色渐黑，此现象称为","o":["主色","客色","善色","病色","恶色"],"a":1,"e":"随四时气候更迭而相应变化的面色称客色，属生理性面色变化。秋应白、冬应黑，随季而移，正合五行四时之序。"},{"q":"患者与人争执后，情绪低落，胸胁胀满疼痛，或走窜疼痛，食少，脉弦，多属","o":["气虚证","气闭证","气逆证","气滞证","气陷证"],"a":3,"e":"情志不遂致气机郁滞，见胸胁胀满疼痛、走窜不定、脉弦，为气滞证。气滞以胀、闷、痛而部位不定为特点，食少为气滞犯脾之兼症。"},{"q":"患者鼻中出血，点滴而出，色鲜红，量不多。兼见咳嗽痰少，发热口干，舌边红，舌苔薄白而干，脉浮数。多辨证为","o":["肺经风热","胃热炽盛","肝火上逆","肺肾阴虚","脾不统血"],"a":0,"e":"鼻衄点滴色鲜、量不多，兼咳嗽痰少、发热口干、舌边红、苔薄白而干、脉浮数，为风热犯肺、肺热上蒸鼻窍、迫血妄行。病位在肺卫，故属肺经风热。"},{"q":"患者中府穴有明显压痛，应考虑为","o":["心病","肝病","脾病","肺病","肾病"],"a":3,"e":"中府为肺之募穴，位于胸前壁外上方、锁骨下窝外侧，肺脏病变时该穴常有明显压痛。募穴压痛可反映相应脏腑的病位。"},{"q":"嗳气频作响亮，常因情志变化而增减者，证属","o":["食滞胃脘","寒邪客胃","胃肠实热","肝气犯胃","胃虚气逆"],"a":3,"e":"嗳气频作响亮、随情志变化而增减，为肝气郁结、横逆犯胃、胃气上逆。食滞者嗳气酸腐，寒邪客胃者嗳声低沉而兼冷痛。"},{"q":"患者症见突然昏倒，口吐涎沫，四肢抽搐，口中发出猪羊叫声，醒后如常，其诊断是","o":["狂证","癫证","痫证","中暑","中风"],"a":2,"e":"突然昏倒、口吐涎沫、四肢抽搐、口中发出猪羊叫声、醒后如常，为痫证发作的典型表现，因痰浊蒙蔽清窍、肝风内动、气机逆乱。"},{"q":"患者表情淡漠，面色苍白，冷汗淋漓、汗质稀淡，四肢厥冷，呼吸微弱，舌白脉微。证属","o":["表寒证","里热证","亡阳证","亡阴证","阴阳两虚证"],"a":2,"e":"冷汗淋漓、汗质稀淡、四肢厥冷、面色苍白、呼吸微弱、脉微，为阳气暴脱、失于温煦固摄之亡阳证。亡阴则汗热而黏、脉细数躁疾。"},{"q":"患者干咳无痰，咳声清脆，咽干，舌淡红，脉浮者，多属","o":["寒饮内停","燥热伤肺","肺气不宣","肾水不足","痰浊蕴肺"],"a":1,"e":"干咳无痰、咳声清脆、咽干、舌淡红、脉浮，为燥热之邪伤肺耗津、肺失清润。咳声清脆示燥胜，痰浊蕴肺者咳声重浊有痰。"},{"q":"患者近日因外感出现咳嗽痰黄稠，鼻塞流浊涕，咽痛，发热微恶寒，口干微渴，舌尖红，苔薄黄，考虑最可能的脉象是","o":["浮紧脉","浮缓脉","浮滑脉","浮数脉","沉紧脉"],"a":3,"e":"咳嗽痰黄稠、咽痛、发热微恶寒、口干微渴、舌尖红苔薄黄，为风热袭表犯肺。邪在肌表故脉浮，热邪亢盛故脉数，浮数相合为风热表证之脉。"},{"q":"患者，女，45岁。久病面色苍白，却时而泛红如妆、游移不定，辨证为","o":["心火上炎","阳明热盛","肝胆湿热","虚阳外越","阴虚火旺"],"a":3,"e":"久病面色苍白而时而泛红如妆、游移不定，为虚阳浮越于上的戴阳证，属真寒假热。阴寒内盛、格阳于外，故赤色浮而游移。"},{"q":"患者多年来小便清长，淋漓不尽，肢冷蜷卧，近日突见小便闭塞不通，腹胀痛，急躁不安，证属","o":["虚实夹杂","虚证转实","实证转虚","寒证化热","寒热错杂"],"a":1,"e":"久病小便清长、淋漓不尽、肢冷蜷卧属阳气虚衰之虚寒，近日骤然尿闭、腹胀痛、烦躁不安，为虚证转为实证。病性由虚转实，属虚实转化。"},{"q":"患者，男，35岁。时有突然昏蒙，甚则昏仆反复发作已历2年。近2年来常无明显诱因突然一过性昏蒙，随即清醒；重则昏倒仆地，人事不省，口吐涎沫，喉有痰鸣，持续数十秒才能逐渐清醒。平素面色晦暗，胸闷，呕恶，舌苔白腻，脉滑。此属下列哪个证候","o":["肝阳化风证","痰火扰神证","心火亢盛证","胆郁痰扰证","痰蒙心神证"],"a":4,"e":"昏仆不省、口吐涎沫、喉有痰鸣、面色晦暗、胸闷呕恶、苔白腻、脉滑，为痰浊蒙蔽心神、神机失用。苔白腻脉滑而无火热之象，故非痰火扰神。"},{"q":"患者，男，45岁。失眠反复发作2个月，自觉眠浅多梦，夜间盗汗，伴心烦心悸。平素形体较瘦，口干饮水较多，大便干结，小便黄，舌尖红绛少苔，脉细数。此属下列何种证候","o":["心阴虚证","心火上炎证","心血虚证","心肾不交证","肝阴虚证"],"a":0,"e":"失眠多梦、盗汗、心烦心悸、口干便结、小便黄、舌尖红绛少苔、脉细数，为心阴不足、虚热内扰。无腰膝酸软、耳鸣，故不属心肾不交。"},{"q":"患者头痛，眩晕，自觉气从少腹上冲于胸咽，随即咯血，苔白，脉弦。为","o":["气滞证","气逆证","气闭证","气脱证","血瘀证"],"a":1,"e":"气从少腹上冲胸咽、头痛眩晕、随即咯血，为气机升降失常、逆而上冲之气逆证。肝胃之气上逆，血随气升，故见咯血。"},{"q":"患者，男，40岁。自述右胁胀痛1个月，腹胀，厌食油腻，舌红苔黄腻，其胁痛的病机是","o":["肝脾不调","肝胆湿热","肝郁气滞","肝经瘀血","肝胃不和"],"a":1,"e":"右胁胀痛、腹胀、厌食油腻、舌红苔黄腻，为湿热蕴结肝胆、疏泄失职、胆汁不循常道。苔黄腻是湿热内蕴之明证，非单纯气滞或瘀血。"},{"q":"患者，女，20岁。近1个月来神情抑郁，淡漠痴呆，有时喃喃独语，见人则止，舌苔白腻，脉滑。此属下列何证","o":["痰蒙心神证","心气虚证","痰火扰心证","瘀阻脑络证","胆郁痰扰证"],"a":0,"e":"神情抑郁、淡漠痴呆、喃喃独语、见人则止、苔白腻、脉滑，为痰浊蒙蔽心神、神明失用。苔白腻示痰湿为患而非痰火，故属痰蒙心神证。"},{"q":"患者下肢肿胀，皮肤粗厚如象皮，多为感染","o":["蛔虫","绦虫","钩虫","血吸虫","丝虫"],"a":4,"e":"丝虫寄生于淋巴系统，反复感染致淋巴管阻塞、淋巴液回流受阻，下肢肿胀而皮肤粗厚如象皮，称象皮肿。血吸虫则致肝脾肿大与腹水。"},{"q":"患者，男，60岁。心悸胸闷反复发作半年。平素自觉气短难续，倦怠肢沉，容易疲惫，活动后更加明显。刻下：面色淡白，舌质淡，脉虚。此属下列何证","o":["心阳虚证","心气虚证","心肾不交证","心血虚证","心脾气虚两虚证"],"a":1,"e":"心悸胸闷、气短难续、倦怠肢沉、动则加重、面色淡白、舌淡脉虚，为心气不足、鼓动无力、心神失养。无肢冷畏寒，故未至心阳虚。"},{"q":"患者，女，26岁，已婚。胃脘隐痛，饥不欲食，口燥咽干，大便干结，舌红少津，脉细数。其病机是","o":["脾阴不足","胃阴不足","胃燥津亏","胃热炽盛","肝胃不和"],"a":1,"e":"胃脘隐痛、饥不欲食、口燥咽干、大便干结、舌红少津、脉细数，为胃阴亏虚、胃失濡润、受纳腐熟失职。饥不欲食是胃阴虚的特征性表现。"},{"q":"患者，男，68岁。半小时前突然昏仆，不省人事，口吐涎沫，喉有痰声，并见面色晦暗，胸闷欲呕，舌苔白腻，脉滑。此属下列何证","o":["心阳虚证","痰火扰心证","瘀阻脑络证","胆郁痰扰证","痰蒙心神证"],"a":4,"e":"突然昏仆、不省人事、口吐涎沫、喉有痰声、面色晦暗、胸闷欲呕、苔白腻、脉滑，为痰浊蒙蔽心神、清窍不利。苔白腻脉滑是痰湿内盛之据。"},{"q":"患者，女，50岁。经常头晕心悸，失眠健忘，面色淡白，气短懒言，舌淡脉细，其头晕的病机是","o":["痰湿内阻","阳气不足","阳气暴脱","肾精亏虚","气血亏虚"],"a":4,"e":"头晕心悸、失眠健忘、面色淡白、气短懒言、舌淡脉细，为气血两虚、清窍失养。气虚则清阳不升，血虚则脑髓失充，故头晕由气血亏虚所致。"},{"q":"患者，男，34岁。素嗜辛辣香燥之品，半年来时有胃脘隐隐疼痛，干呕呃逆，饥不欲食，口燥咽干，伴见形体消瘦，大便干结，舌红少津，脉细而数。其病证机理为","o":["胃火炽盛","脾胃气虚","胃阴不足","胃强脾弱","食积化热"],"a":2,"e":"久嗜辛辣香燥，耗伤胃阴，见胃脘隐痛、干呕呃逆、饥不欲食、口燥咽干、消瘦便结、舌红少津、脉细数。虚火不著，故属胃阴不足。"},{"q":"咳喘，心悸，咯痰清稀，声低气喘，面白神疲，舌淡紫，宜诊断为","o":["心肺气虚证","饮停胸胁证","肺气虚证","心脉瘀阻证","寒痰阻肺证"],"a":0,"e":"咳喘、咯痰清稀、声低气喘为肺气亏虚，心悸为心气不足，面白神疲、舌淡紫为气虚血行不畅。心肺同居上焦，气虚并见故为心肺气虚证。"},{"q":"患者，女。经期出现腹痛，痛处拒按，固定不移，月经色紫黯，有血块，舌紫黯有瘀斑，最可能的脉象是","o":["弦滑脉","滑数脉","沉迟脉","细涩脉","沉实脉"],"a":3,"e":"经行腹痛拒按、痛处固定、经色紫黯有块、舌紫黯有瘀斑，为瘀阻胞宫、不通则痛。瘀阻脉道故脉涩，血行不畅故脉细，合为细涩脉。"},{"q":"疔的诊断要点，应除外下列哪一项","o":["形如粟如米","根脚坚硬较深","顶白而痛","易化脓，脓溃易愈","麻木或发痒"],"a":3,"e":"疔形小根深、形如粟米、根脚坚硬较深、顶白而痛，或麻木发痒，其要害在于易走黄内陷。疔不具易化脓、脓溃易愈之性，故此项应除外。"},{"q":"患者素体痰盛，近来又感受外邪者，其最可能的脉象为","o":["滑数脉","浮滑脉","浮数脉","浮紧脉","浮缓脉"],"a":1,"e":"素体痰盛则脉道内有痰浊，脉来滑利；复感外邪则邪在肌表，脉气鼓动于外而浮。浮主表、滑主痰，相合即为浮滑脉。"},{"q":"患者鼻中出血，量多，血色鲜红，鼻干，口干口臭，烦渴引饮，大便干燥，小便短赤，舌红，苔黄厚干，脉洪大而数。最宜辨证为","o":["肺经风热","胃热炽盛","肝火上逆","肺肾阴虚","脾不统血"],"a":1,"e":"鼻衄量多色鲜红，兼鼻干口臭、烦渴引饮、便干溲赤、舌红苔黄厚干、脉洪大而数，为胃热炽盛、迫血妄行。热在阳明气分，故脉洪大。"},{"q":"患者神疲乏力，少气懒言，头昏眼花，常自汗出，面白舌淡，证属","o":["痰湿内阻证","肾精不足证","气虚证","气陷证","肝郁脾虚证"],"a":2,"e":"神疲乏力、少气懒言、自汗、面白舌淡，为元气不足、脏腑功能减退之气虚证。头昏眼花由气虚清阳不升所致，尚无脏器下垂之陷象。"},{"q":"患者自觉烦热，颧赤如妆，口干但不多饮，欲加衣被，小便清长，脉沉迟无力，证属","o":["表里实寒证","表寒里热证","表热里寒证","真寒假热证","真热假寒证"],"a":3,"e":"自觉烦热、颧赤如妆而欲加衣被，兼口干不多饮、小便清长、脉沉迟无力，为阴寒内盛、虚阳浮越之真寒假热证。身热欲近衣、溲清脉迟是辨假热之要。"},{"q":"患者发热，其额上热甚于手心，多为","o":["表热","里热","实热","虚热","郁热"],"a":0,"e":"额上热甚于手心者多为表热，因阳热之邪郁于肌表，热势偏于上部而外浮。手心热甚于额上者则多属里热。"},{"q":"陈某，女，62岁。平素嗜食肥甘酒酿，反复脘腹痞闷3个月余，伴纳呆呕恶，便溏尿黄，肢体困重，舌红苔黄腻，脉濡数。诊为","o":["食滞胃脘证","寒滞胃脘证","肠燥津亏证","热盛伤津证","湿热蕴脾证"],"a":4,"e":"嗜食肥甘酒酿致湿热内生，脘腹痞闷、纳呆呕恶、便溏尿黄、肢体困重、舌红苔黄腻、脉濡数，为湿热蕴结脾胃、运化失职。"},{"q":"患者皮肤发赤，伴有口干，面红，小便短黄，舌红，苔黄，脉数，其病机不可能是","o":["寒湿困脾","心火偏旺，风热乘袭","肾火内蕴，湿热下注","热毒内结","丹毒流火"],"a":0,"e":"皮肤发赤伴口干、面红、小便短黄、舌红苔黄、脉数，皆属热邪为患，病机当为火热、热毒或湿热。寒湿困脾属阴寒之证，不可能出现此类热象。"},{"q":"病人小腹急结，小便自利，身体发黄，脉沉结，其证属","o":["太阳中风证","太阳伤寒证","太阳蓄水证","太阳蓄血证","少阳病证"],"a":3,"e":"小腹急结而小便自利，为瘀热结于下焦血分而非膀胱气化不利，故属太阳蓄血证。身发黄、脉沉结亦为瘀热内结之征。"},{"q":"患者久病，颈项软弱，头垂不抬，眼窝深陷，多属","o":["心血瘀阻","热极生风","精气衰竭","风寒侵袭","水气凌心"],"a":2,"e":"久病颈项软弱、头垂不抬、眼窝深陷，为脏腑精气衰竭、不能上荣充养之候，属病危之象。头倾项软是精气衰败的典型表现。"},{"q":"患者，男，47岁，农民。自述5年前因过食生冷而腹痛，温熨热敷可缓解，未系统治疗。1周前不慎着凉腹痛加重。现症见腹痛，喜温喜按，腹胀纳少，食后胀甚，大便溏薄，四肢不温，舌淡胖苔白，脉沉迟无力。其腹痛的病机是","o":["脾胃气虚","脾胃虚寒","寒湿困脾","气滞湿阻","肝郁脾虚"],"a":1,"e":"腹痛喜温喜按、得温则缓、腹胀纳少、便溏、四肢不温、舌淡胖苔白、脉沉迟无力，为脾胃阳气虚衰、失于温运。病程久而得温可缓，属虚寒而非寒湿实证。"},{"q":"皮肤、面目、爪甲发黄，黄色鲜明如橘子色，伴有汗、尿色深黄，口渴，舌苔黄腻者，主要病机是","o":["外感风热","脾胃或肝胆湿热","寒湿所困","下焦湿热","水湿浸淫"],"a":1,"e":"皮肤、面目、爪甲发黄而黄色鲜明如橘，伴汗尿色深黄、口渴、苔黄腻，为湿热蕴结脾胃或肝胆、熏蒸肌肤之阳黄。黄色鲜明示热重于湿。"},{"q":"头晕心悸，目眩，视物模糊，失眠，月经量少、色淡，面白，舌淡脉细。宜诊断为","o":["心脾两虚证","心肝血虚证","肝血虚证","气血两虚证","肝阳上亢证"],"a":1,"e":"心悸失眠为心血不足、心神失养，头晕目眩、视物模糊、月经量少色淡为肝血亏虚、目窍及冲任失充，面白舌淡脉细皆血虚之征。心肝同病，故为心肝血虚证。"},{"q":"神识清楚而言语时有错乱，语后自知言错，称为","o":["独语","错语","谵语","郑声","狂言"],"a":1,"e":"神识清楚而言语时有错乱、语后自知言错者为错语，多因心气不足或痰浊蒙蔽清窍。谵语则神昏而语无伦次，郑声为神衰而语声重复。"},{"q":"患者发热恶热，面红目赤，渴喜冷饮，尿短便秘，舌红苔黄燥，脉洪数有力，宜诊断为","o":["风淫证","暑淫证","燥淫证","火淫证","湿淫证"],"a":3,"e":"发热恶热、面红目赤、渴喜冷饮、尿短便秘、舌红苔黄燥、脉洪数有力，为火热炽盛、充斥内外之火淫证。热势高而燥象显，与暑淫之兼湿不同。"},{"q":"患者耳内流脓，脓液清稀而量多，或牵丝如胶，多为","o":["肝胆火热上蒸","脾虚有湿","肾虚","湿热熏蒸","肝经火旺"],"a":1,"e":"耳内流脓、脓液清稀量多或牵丝如胶，为脾虚运化失职、湿浊上泛耳窍。脓黄稠而臭秽者多属肝胆湿热上蒸，与稀脓不同。"},{"q":"患者恶风发热，汗出，鼻塞流涕，喷嚏，咽痒咳嗽，舌淡苔薄白，脉浮，宜诊断为","o":["风淫证","寒淫证","暑淫证","燥淫证","火淫证"],"a":0,"e":"恶风发热、汗出、鼻塞流涕、喷嚏、咽痒咳嗽、舌淡苔薄白、脉浮，为风邪袭表、卫表失和之风淫证。风性轻扬开泄，故汗出而脉浮。"},{"q":"患者，女，48岁。主诉眩晕，两目干涩，胁肋隐痛，伴有咽干口燥，五心烦热，潮热盗汗，舌红少苔，脉弦细数。辨证属","o":["肝阴虚证","肝火炽盛证","肝血虚证","肝风内动证","寒滞肝脉证"],"a":0,"e":"眩晕、两目干涩、胁肋隐痛，伴咽干口燥、五心烦热、潮热盗汗、舌红少苔、脉弦细数，为肝阴不足、虚热内扰、目窍筋脉失养。"},{"q":"不属于疮疡一类外科疾患的是","o":["痈","疽","疔","疖","疹"],"a":4,"e":"疮疡一类外科疾患包括痈、疽、疔、疖，皆有形之疮肿，各有其形态与辨证要点。疹仅为皮肤上的斑丘疹，属皮肤病表现，不属疮疡范畴。"},{"q":"患者，女，22岁。发热，微恶风寒，咳嗽，头痛，口渴，鼻塞，舌边尖红，脉浮数，其临床意义是","o":["邪热壅肺证","湿热阻肺证","邪犯肺卫证","邪陷心包证","湿蒙心包证"],"a":2,"e":"发热微恶风寒、咳嗽头痛、口渴鼻塞、舌边尖红、脉浮数，为温邪初袭肺卫、卫失宣降、表气不和。病位在肺卫之表，尚未内传入里。"},{"q":"患者胸闷，心悸怔忡，健忘，面色淡黄无华，舌淡，脉细无力，诊断为","o":["血虚证","气虚证","血瘀证","阴虚证","气陷证"],"a":0,"e":"面色淡黄无华、舌淡、脉细无力，兼心悸怔忡、胸闷健忘，为血液亏虚、心神失养之血虚证。血虚不能上荣头面，故面舌俱淡。"},{"q":"患者反复口舌生疮，此起彼伏，缠绵难愈，伴口干咽燥，腰膝酸软，舌红，少苔，脉细数。此病最宜诊断为","o":["心脾积热","阴虚火旺","气血不足","湿热秽浊上蒸","肺胃热盛"],"a":1,"e":"口舌生疮反复发作、此起彼伏、缠绵难愈，兼口干咽燥、腰膝酸软、舌红少苔、脉细数，为肾阴亏虚、虚火上炎。腰膝酸软是定位在肾的关键。"},{"q":"患者脘腹绞痛剧烈，时作时止，继而波及右上腹部，面目身俱黄，呕吐黄绿色苦水，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":1,"e":"脘腹绞痛剧烈、时作时止，继而波及右上腹、身目俱黄、呕吐黄绿苦水，为蛔虫窜入胆道、胆气不通、胆汁外溢。病位在胆道而非肠道。"},{"q":"患者，女，68岁。患冠状动脉粥样硬化性心脏病10年余。今突然心痛剧作，面色青灰，冷汗淋漓，四肢厥冷，呼吸微弱，舌淡苔白润，脉微欲绝。其证候是","o":["心脉痹阻证","心阳暴脱证","心阳虚证","亡阴证","亡阳证"],"a":1,"e":"心病日久突发心痛、面色青灰、冷汗淋漓、四肢厥冷、呼吸微弱、脉微欲绝，为心阳骤然暴脱、失于温煦推动。病位在心，较一般亡阳更突出心脉之变。"},{"q":"患者，女，33岁。面目肌肤发黄10天，色泽鲜明，皮肤瘙痒，脘腹胀闷，纳呆呕恶，便溏尿黄，舌红苔黄腻，脉濡数。诊为","o":["湿热蕴脾证","肝胆湿热证","大肠湿热证","寒湿困脾证","胃热炽盛证"],"a":0,"e":"身目发黄、色泽鲜明、皮肤瘙痒、脘腹胀闷、纳呆呕恶、便溏尿黄、舌红苔黄腻、脉濡数，为湿热蕴结脾胃、熏蒸肝胆、泛溢肌肤。病位重心在脾之运化。"},{"q":"患者口内唇边，舌面部位生数个黄豆大小黄白色溃烂点，周围黏膜鲜红，微肿，有灼痛感，说话进食困难，兼见发热，口渴，口臭，大便秘结，舌红苔黄，脉数。上述症状宜诊断为","o":["湿热秽浊上蒸","痰湿凝聚","阴虚火旺","肺胃热盛","心脾积热"],"a":4,"e":"口舌生疮、周围黏膜鲜红微肿灼痛，兼发热口渴口臭、便秘、舌红苔黄、脉数，为心脾积热、火热上炎。舌为心之苗、口为脾之窍，病位在心脾。"},{"q":"“白㾦”产生的主要病机是","o":["湿邪中阻","湿郁肺卫","上焦湿热","湿热内郁，汗出不彻","肝胆湿热"],"a":3,"e":"白㾦为湿热病中出现的白色小水疱，因湿热内郁、汗出不彻、郁蒸肌表而成。晶莹饱满者为顺，枯白无液者为逆。"},{"q":"嗳气频作连续，无酸腐气味，兼见脘腹冷痛者，属于","o":["寒邪客胃","湿困脾胃","胃虚气逆","食积内停","肝气犯胃"],"a":0,"e":"嗳气频作连续、无酸腐气味，兼脘腹冷痛，为寒邪客胃、胃阳被遏、胃气上逆。食滞者嗳气酸腐，肝气犯胃者随情志而增减。"},{"q":"腹痛腹泻，泻后痛减，胁胀，食少乏力，苔白脉弦，宜诊断为","o":["食滞胃肠证","胃肠气滞证","寒湿困脾证","脾胃阳虚证","肝郁脾虚证"],"a":4,"e":"腹痛腹泻、泻后痛减、胁胀、脉弦为肝郁乘脾、气机不畅；食少乏力、苔白为脾虚失运。肝木横逆与脾虚并见，故属肝郁脾虚证。"},{"q":"患者，男，2岁。头颅狭小，颅缝迟闭，智力低下。最可能的原因是什么","o":["火邪上攻","吐泻伤津","气血不足","肾精不足","痰饮内停"],"a":3,"e":"小儿头颅狭小、颅缝迟闭、智力低下，为先天肾精不足、髓海空虚、骨骼失养。肾主骨生髓，精亏则生长发育迟缓、脑髓不充。"},{"q":"病人恶寒身蜷而下利，手足逆冷，其证属","o":["太阴病证","厥阴病证","阳明病证","少阳病证","少阴病证"],"a":4,"e":"恶寒身蜷、下利、手足逆冷、脉微细但欲寐，为少阴心肾阳气虚衰、阴寒内盛、神失所养之少阴病证。阳虚失于温煦，故蜷卧而肢冷。"},{"q":"患者，女，60岁。有哮喘病史15年，近日因感冒而复发。咳喘无力，咯痰清稀，少气懒言，神疲乏力，动则尤甚，舌淡苔白，脉弱。其辨证为","o":["肺气虚证","风寒犯肺证","风寒表证","脾气虚证","肺肾气虚证"],"a":0,"e":"久病哮喘，咳喘无力、咯痰清稀、少气懒言、神疲乏力、动则尤甚、舌淡苔白、脉弱，为肺气亏虚、宣降无力。无恶寒发热表证及寒热之象。"},{"q":"患者，女，44岁。因外伤而出现面色苍白，大汗淋漓，手足厥冷，脉微。故辨证为","o":["气血亏虚证","气滞血瘀证","气不摄血证","气随血脱证","血随气脱证"],"a":3,"e":"外伤后大量失血，继而面色苍白、大汗淋漓、手足厥冷、脉微，为血脱而气无所附、随之暴脱之气随血脱证。先血脱后气脱是其演变特点。"},{"q":"患者，男，56岁。主诉头痛而晕，伴有烦躁易怒，失眠，耳鸣如潮，面红口干，大便秘结，小便短黄，舌红苔黄，脉弦数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","寒滞肝脉证"],"a":1,"e":"头痛而晕、烦躁易怒、耳鸣如潮、面红口干、便秘溲黄、舌红苔黄、脉弦数，为肝火上炎、循经上扰清窍。耳鸣如潮、脉弦数示实火而非阴虚。"},{"q":"患者头项强痛、恶寒发热，四肢关节微痛，口渴，下利黄色粪水，肛门灼热，其证属","o":["少阴兼阳明病证","少阳兼太阳病证","太阳兼阳明病证","太阳病证","阳明病证"],"a":2,"e":"头项强痛、恶寒发热、关节微痛为太阳表证未解；口渴、下利黄水、肛门灼热为阳明里热已盛。表里同病而以里热下利为著，属太阳兼阳明病证。"},{"q":"患者反复咽中不适，微痛，有干痒灼热感，异物感，常伴咽痒咳嗽，易受刺激而引起恶心干呕，腰酸，舌红少津，脉细数。检查，咽部微红，肿痛不显，有散在颗粒。上述症状宜诊断为","o":["肺胃热盛","痰湿凝聚","肺肾阴虚","风热袭肺","心脾热盛"],"a":2,"e":"咽中干痒灼热、异物感、干咳恶心，伴腰酸、舌红少津、脉细数，为肺肾阴虚、虚火上灼咽喉、咽失濡养。咽部微红而肿痛不显，属虚证。"},{"q":"患者因胸胁刺痛数月就诊，症见面色晦滞，神疲乏力，少气懒言，胸胁疼痛固定，可触及肿块，质硬，舌淡紫，有瘀斑，最有可能的脉象是","o":["沉迟无力","弦数有力","细涩无力","脉弱","脉细数"],"a":2,"e":"胸胁刺痛固定、可触及质硬肿块、面色晦滞、舌淡紫有瘀斑，为瘀血内结；神疲乏力、少气懒言为气虚。气虚推动无力、瘀阻脉道，故脉细涩无力。"},{"q":"患者，男，45岁。体胖，平素喜食油腻，5日前出现咳嗽，痰黄稠量多，发热，口渴喜冷饮，小便短赤，大便秘结，舌红苔黄腻，脉滑数。辨证为","o":["痰热壅肺证","风热犯肺证","肺热炽盛证","肝火犯肺证","湿热蕴脾证"],"a":0,"e":"咳嗽痰黄稠量多、发热口渴、溲赤便秘、舌红苔黄腻、脉滑数，为痰热壅阻肺气、肺失清肃。苔黄腻、脉滑数示痰与热结，非单纯风热表证。"},{"q":"患者3天前受凉，恶寒发热，现症见体温38、5℃，时冷时热，心烦喜呕，舌红，属于","o":["表热里寒证","表寒里热证","表里俱热证","表里俱寒证","半表半里证"],"a":4,"e":"寒热往来、时冷时热、心烦喜呕、舌红，为邪犯少阳、枢机不利、正邪分争之半表半里证。邪不在表故无恶寒无汗，未入里故无潮热腹满。"},{"q":"病人恶寒发热1天，脉浮紧，无汗而喘，舌苔薄白，其证属","o":["太阳中风证","太阳伤寒证","太阳蓄水证","太阳蓄血证","少阳病证"],"a":1,"e":"恶寒发热、无汗而喘、脉浮紧、苔薄白，为寒邪束表、卫阳被遏、营阴凝滞之太阳伤寒证。无汗而脉浮紧是与太阳中风鉴别的要点。"},{"q":"患者，男，25岁。3天前因打篮球出汗后，未及时穿外套，受凉而发病。现咳嗽，痰稀色白，伴见恶寒发热，鼻塞流清涕，头身疼痛，舌淡红，苔薄白，脉浮紧。其辨证为","o":["风寒表证","风寒犯肺证","寒痰阻肺证","饮停胸胁证","肺气虚证"],"a":1,"e":"受凉后咳嗽、痰稀色白、鼻塞流清涕，兼恶寒发热、头身疼痛、苔薄白、脉浮紧，为风寒袭肺、肺气失宣。咳嗽为主症，病位在肺，故属风寒犯肺证。"},{"q":"颅内压力增高所致的呕吐特点是","o":["饭后即吐","吐利并作","朝食暮吐","吐物酸腐","呕吐如喷"],"a":4,"e":"颅内压增高时呕吐呈喷射状，与进食无关，多伴剧烈头痛、视乳头水肿。此因邪扰神明、胃气随之上逆而致。"},{"q":"患者，女，49岁。舌体疼痛衄血伴发热3天，平素时有心烦失眠，便秘，尿黄，舌尖红，苔黄，脉数有力。此属下列何证","o":["心阴虚证","心火亢盛证","肺热炽盛证","膀胱湿热证","脾胃湿热证"],"a":1,"e":"舌体疼痛衄血、心烦失眠、便秘尿黄、舌尖红、苔黄、脉数有力，为心火亢盛、火性上炎、迫血妄行。舌尖属心，故舌痛红赤最为著明。"},{"q":"暑天病人发热，猝然昏倒，汗出不止，口渴气急，考虑中暑，最可能的脉象是","o":["濡数脉","弦滑脉","细涩脉","浮紧脉","浮缓脉"],"a":0,"e":"暑为阳邪，性炎热升散，耗气伤津，故发热汗出、口渴气急而脉数；暑多夹湿，湿性濡软，故脉兼濡。濡数为暑证的典型脉象。"},{"q":"患者腹胀拒按，纳呆食少，神疲乏力，少气懒言，形体消瘦，多考虑","o":["食积于胃","食积于肠","脾虚食积","肝郁乘脾","心脾两虚"],"a":2,"e":"腹胀拒按、纳呆食少属食积内停，神疲乏力、少气懒言、形体消瘦属脾气虚弱，两者并见为脾虚食积。虚中夹实，治当消补兼施。"},{"q":"患者心烦，失眠，惊悸多梦，腰膝酸软，耳鸣遗精，潮热盗汗，舌红少苔，脉细数。宜诊断为","o":["心脾两虚证","肺肾阴虚证","心肾不交证","肝肾阴虚证","心肝血虚证"],"a":2,"e":"心烦失眠、惊悸多梦为心火偏亢、神不守舍；腰膝酸软、耳鸣遗精、潮热盗汗、舌红少苔、脉细数为肾阴亏虚。水火失济、心肾不交，故两脏证并见。"},{"q":"患者口中干渴，胸中烦热，频欲呕吐，腹部冷痛，大便溏泄，舌红苔黄白相间，脉濡数。证属","o":["上热下寒","上寒下热","表热里寒","表寒里热","真热假寒"],"a":0,"e":"口干渴、胸中烦热、频欲呕吐属上焦有热；腹部冷痛、大便溏泄属下焦有寒，舌苔黄白相间亦示寒热错杂。病位上下分属，故为上热下寒。"},{"q":"患者，女，38岁。症见心悸失眠，头晕健忘，面白，月经后期，舌淡，脉细，其心悸多属","o":["血虚失养","心胆气虚","阴虚火旺","心阳亏虚","水湿内停"],"a":0,"e":"心悸失眠、头晕健忘、面白、月经后期、舌淡脉细，为心血不足、心神及清窍失养。血虚不能上奉，故心悸而兼头晕。"},{"q":"患者，女，49岁。时值更年，近半年来自觉躁烦不安，眠浅梦多，时常发热出汗，口干饮水不多，大便不爽，小便短黄。舌质红尖红绛，苔黄腻，脉滑数。此属下列何证","o":["心阴虚证","心火亢盛证","肝火炽盛证","痰蒙心神证","痰火扰神证"],"a":4,"e":"烦躁不安、眠浅梦多、发热汗出、大便不爽、小便短黄、舌尖红绛、苔黄腻、脉滑数，为痰火内扰、心神不宁。苔黄腻、脉滑数是痰火互结之明证。"},{"q":"心烦失眠，腰酸梦遗，头晕，舌红无苔，宜诊断为","o":["心火亢盛证","肾阴虚证","肾精不足证","心肾不交证","心阴虚证"],"a":3,"e":"心烦失眠为心火不能下交，腰酸梦遗、头晕、舌红无苔为肾阴不能上济，水火不济、心肾不交。舌红无苔示阴液亏耗、虚热内生。"},{"q":"患者，女，35岁。患带下病5年。带下色白质稠量多，如豆腐渣样，气味腥臭，伴阴部瘙痒，饮食二便如常。查体：舌淡红，苔灰白而腻，脉象濡缓。此人带下病的病机是","o":["脾气下陷","脾肾阳虚","湿浊下注","肝经郁热","热毒蕴蒸"],"a":2,"e":"带下色白质稠量多、如豆腐渣样、气味腥臭、阴部瘙痒、苔灰白而腻、脉濡缓，为湿浊下注、带脉失约。无脾肾阳虚之寒象，故以湿浊为病机。"},{"q":"患者全目赤肿，伴见发热、微恶风寒，巅顶头痛，舌红，苔薄黄者，脉浮数，最宜诊断为","o":["肝胆湿热","肝经风热","肝郁气滞","肝火炽盛","心肝火旺"],"a":1,"e":"全目赤肿，兼发热微恶风寒、巅顶头痛、舌红苔薄黄、脉浮数，为风热之邪侵袭肝经、循经上攻目窍。巅顶为肝经所过，故病位在肝。"},{"q":"形寒肢冷，脘腹冷痛，纳呆呕恶，大便稀溏，肢体水肿，腰膝酸软，舌淡苔白滑，应辨证为","o":["脾气虚","脾阳虚","脾肾阳虚","寒湿困脾","寒滞胃肠"],"a":2,"e":"形寒肢冷、脘腹冷痛、纳呆呕恶、大便稀溏、肢体水肿为脾阳虚、运化失职、水湿泛溢；腰膝酸软属肾阳虚。两脏阳衰并见，故为脾肾阳虚。"},{"q":"患者脘腹胀满，嗳腐吞酸，恶心呕吐，多考虑","o":["食积于胃","食积于肠","脾虚食积","肝郁乘脾","心脾两虚"],"a":0,"e":"脘腹胀满、嗳腐吞酸、恶心呕吐，为饮食停滞胃脘、胃失和降、浊气上逆。嗳腐吞酸是食积于胃的特征性表现。"},{"q":"患者发热，其手背较手心热甚者，多为","o":["外感发热","内伤发热","气郁发热","虚证发热","瘀血发热"],"a":0,"e":"手背热甚于手心者为外感发热，因外邪袭表、阳热之气浮盛于肌表。内伤发热则多手心热甚于手背。"},{"q":"小儿高热3日，无鼻涕咳嗽，今晨见头面胸腹部疹出，随即热退，证属","o":["半表半里","表里同病","里邪出表","热毒内闭","热证转寒"],"a":2,"e":"高热3日后疹出而热退，为邪热从里透达肌表、由深出浅之里邪出表。疹毒外透、邪有出路，故热势随之而解。"},{"q":"患者，女，35岁。腹胀痛1个月余，腹痛喜温喜按，纳少，大便清稀，白带量多质稀，舌淡胖，苔白滑，脉沉迟无力。诊为","o":["肾气不固证","寒湿困脾证","脾阳虚证","脾气虚证","脾虚气陷证"],"a":2,"e":"腹痛喜温喜按、纳少、大便清稀、白带量多质稀、舌淡胖苔白滑、脉沉迟无力，为脾阳不足、温运失职、寒湿内生。病性属虚寒，非寒湿困脾之实证。"},{"q":"病人口燥咽干，腹胀硬满而痛，不大便或下利清水，其证属","o":["少阴兼阳明病证","少阴兼太阳病证","少阳兼太阳病证","少阳病证","少阴病证"],"a":0,"e":"口燥咽干为少阴阴液亏耗，腹胀硬满而痛、不大便或下利清水为阳明腑实燥结。下利清水系热结旁流，故属少阴兼阳明病证。"},{"q":"病人寒热往来，复见腹满痛，郁郁微烦，心以下急，大便不通，舌苔干黄等，其证属","o":["少阳兼阳明病证","阳明兼太阳病证","少阳兼太阳病证","少阳病证","阳明病证"],"a":0,"e":"寒热往来为邪在少阳、枢机不利；腹满痛、郁郁微烦、心下急、大便不通、苔干黄为阳明里实已成。少阳证未罢而兼阳明腑实，故属少阳兼阳明病证。"},{"q":"患者心脾有热，其舌态可见","o":["痿软舌","强硬舌","歪斜舌","颤动舌","吐弄舌"],"a":4,"e":"心脾有热，舌体吐出口外或时时舔弄口唇，称吐弄舌，多见于小儿。舌为心之苗、脾开窍于口，积热上冲则舌体躁动不安。"},{"q":"久流浊涕，质稠量多，气味腥臭属","o":["外感风邪","湿热蕴阻","痰热壅肺","外感风寒","燥邪犯肺"],"a":1,"e":"久流浊涕、质稠量多、气味腥臭，为湿热蕴阻鼻窍、气血壅滞腐败之鼻渊。清稀涕多属风寒，浊涕腥臭则示湿热为患。"},{"q":"患者畏冷肢凉，喜静蜷卧，口淡不渴，小便清长，夜尿多，面色淡白，恶心欲吐，脉沉迟无力。证属","o":["表实寒证","表实热证","里实寒证","里虚寒证","里虚热证"],"a":3,"e":"畏冷肢凉、喜静蜷卧、口淡不渴、小便清长、夜尿多、面色淡白、脉沉迟无力，为阳气虚衰、温煦不足之里虚寒证。脉沉迟无力是虚寒的要点。"},{"q":"患者，女，47岁。近半年来经常头晕耳鸣，两目干涩，五心烦热，夜寐多梦，口燥咽干，舌红少津，脉弦细数。其五心烦热的病机是","o":["阴虚内热","精血亏虚","津液亏虚","肾精亏虚","气血亏虚"],"a":0,"e":"头晕耳鸣、两目干涩、五心烦热、夜寐多梦、口燥咽干、舌红少津、脉弦细数，为肝肾阴虚、阴不制阳、虚热内生，故五心烦热。"},{"q":"选择与脘腹胀满，不思饮食，身重困倦，大便溏薄，小便短赤，脉濡数等证候相符合的舌象","o":["舌绛红苔腻","舌红苔黄腻","舌青紫苔白润","舌红苔黄燥","红舌苔黄"],"a":1,"e":"脘腹胀满、不思饮食、身重困倦、大便溏薄、小便短赤、脉濡数，为湿热中阻、脾运失职。湿盛则苔腻，热盛则舌红苔黄，合为舌红苔黄腻。"},{"q":"病人脉微细，但欲寐，其证属","o":["太阴病证","厥阴病证","少阴病证","阳明病证","太阳病证"],"a":2,"e":"脉微细、但欲寐，为少阴心肾阳气虚衰、神失所养之提纲证。阳气虚衰不能振奋精神，故昏沉但欲睡。"},{"q":"患者，女，45岁，教师。因工作繁忙于半年前开始出现心悸心烦，失眠多梦等症，伴五心烦热，盗汗，颧红，舌红少津，脉细数。其盗汗的病机是","o":["血虚失养","心脾两虚","阴虚火旺","痰火扰神","心胆气虚"],"a":2,"e":"心悸心烦、失眠多梦、五心烦热、盗汗颧红、舌红少津、脉细数，为心阴亏虚、虚火内扰。寐时阳入于阴，虚热迫津外泄，故见盗汗。"},{"q":"患者，男，31岁。多汗，烦躁口渴，但热不寒，咳嗽气喘，苔黄，脉数，其临床意义是","o":["邪热壅肺证","湿热阻肺证","邪犯肺卫证","邪陷心包证","湿蒙心包证"],"a":0,"e":"多汗、烦躁口渴、但热不寒、咳嗽气喘、苔黄、脉数，为邪热内壅于肺、肺失清肃、迫津外泄。但热不寒示邪已入里化热。"},{"q":"患者，男，20岁。5天前受凉后出现恶寒发热，无汗，咳嗽，夜间加剧，咳痰稀薄色白，舌苔薄白腻，脉浮紧。其证候是","o":["风寒束肺证","寒邪客肺证","痰湿阻肺证","燥邪犯肺证","饮停于肺证"],"a":0,"e":"受凉后恶寒发热、无汗、咳嗽夜甚、痰稀薄色白、苔薄白腻、脉浮紧，为风寒束肺、肺气失宣。脉浮紧、无汗是寒邪束表的要点。"},{"q":"患者心悸，失眠，多梦，健忘，头晕目眩，面色淡白，口唇淡白，舌淡白，脉沉细无力。应诊断为","o":["心阴虚证","心气虚证","心血虚证","心肾不交证","心脾两虚证"],"a":2,"e":"心悸失眠多梦、健忘、头晕目眩、面唇舌淡白、脉沉细无力，为心血亏虚、心神失养、血不上荣。无五心烦热、盗汗等阴虚之象。"},{"q":"患者咳嗽无痰，乏力咽燥，低热不退，舌红少苔，脉细数。此属","o":["阳虚证","阴虚证","阴阳两虚证","真实假虚证","真虚假实证"],"a":1,"e":"咳嗽无痰、乏力咽燥、低热不退、舌红少苔、脉细数，为阴液亏虚、虚热内生之阴虚证。无肢冷畏寒之阳虚象，亦无真实假虚之征。"},{"q":"患者，女，53岁。近来时感口咽干燥，但不欲饮水，伴见头身困重，身热不扬，脘闷不饥，舌红苔黄腻，脉濡数。其口渴的病机为","o":["燥邪袭表","湿遏热伏","痰火内扰","热盛阴伤","热入营分"],"a":1,"e":"口咽干燥而不欲饮水，兼头身困重、身热不扬、脘闷不饥、舌红苔黄腻、脉濡数，为湿热内蕴、湿遏热伏、津不上承。湿浊内阻，故虽干而不欲饮。"},{"q":"患者，女，48岁。手足蠕动，瘈疭，五心烦热，心中憺憺大动，舌绛苔少，脉虚，其临床意义是","o":["肝阴虚证","肾精耗损证","肾阴虚证","血虚动风证","虚风内动证"],"a":0,"e":"手足蠕动、瘈疭、五心烦热、心中憺憺大动、舌绛苔少、脉虚，为肝阴亏虚、筋脉失养、虚风内动。多见于热病后期阴液耗损。"},{"q":"Page-FrameX年X月X日X时 XX科别姓名 性别 年龄 职业主诉：患者就诊的主要症状（或体征）及持续时间。病史：主症发生的时间、病情的发展变化、诊治经过及重要的既往病史、个人史和过敏史等。体格检查：记录生命体征、中西医检查阳性体征及具有鉴别意义的阴性体征。特别要注意舌象、脉象。实验室检查：记录就诊时已获得的有关检查结果。诊断：中医诊断（包括疾病诊断与证的诊断）：西医诊断：处理：（1）中医论治：记录治则治法、方药、用法等。（2）西医治疗：记录具体用药、剂量、用法等。（3）进一步的检查项目。（4）饮食起居宜忌、随诊要求、注意事项。医师签名：以上病历书写格式是","o":["门诊病历的初诊记录","门诊病历的复诊记录","住院病历的初诊记录","住院病历的复诊记记录","住院病历的病程记录"],"a":0,"e":"该格式含主诉、病史、体格检查、实验室检查、诊断与处理，并要求医师签名，为门诊初诊病历的书写格式。住院病历尚需入院记录、病程记录等项。"},{"q":"陈某，男，20岁，学生。2011年3月9日初诊。因发热、咳嗽、气喘1天就诊。患者于昨日外出春游，忽遇大雨，全身淋湿，当夜即感恶寒，随之发热，一身疼痛……病案中的“陈某，男，20岁，学生。2011年3月9日初诊。”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":0,"e":"姓名、性别、年龄、职业及就诊日期属病历的一般情况项目。主诉为就诊主要症状及持续时间，现病史记述发病时间与病情演变。"},{"q":"患者恶风发热，口干，咽喉不利，干咳少痰，尿少边干，苔干燥，脉浮，宜诊断为","o":["风淫证","寒淫证","暑淫证","燥淫证","火淫证"],"a":3,"e":"恶风发热、口干、咽喉不利、干咳少痰、尿少、苔干燥、脉浮，为燥邪犯表、伤津耗液、肺卫失润之燥淫证。燥胜则干，故燥象突出。"},{"q":"霍乱的呕吐特点是","o":["饮后即吐","吐利并作","朝食暮吐","吐物酸腐","呕吐酸腐"],"a":1,"e":"霍乱以起病急骤、上吐下泻并作为特点，因秽浊疫邪伤及脾胃、清浊相干、升降失司。吐利交作而津液骤伤，易致转筋亡阳。"},{"q":"心悸，面白，肢体麻木，月经量少、色淡，舌淡脉细。宜诊断为","o":["心脾两虚证","心血虚证","肝血虚证","心肝血虚证","心阴虚证"],"a":3,"e":"心悸、面白为心血不足、心神失养，肢体麻木、月经量少色淡为肝血亏虚、筋脉及冲任失充，舌淡脉细皆血虚之征。心肝同病，故为心肝血虚证。"},{"q":"哮病的原因是","o":["肺肾亏虚，气失摄纳","水汽上凌心肺","寒邪、热邪袭肺","痰饮内伏，复感外邪","脾肺气虚，内生痰湿"],"a":3,"e":"哮病以喉中哮鸣有声、呼吸急促、甚则不能平卧为特征，病根为宿痰伏肺，每因外邪、饮食、情志等诱因而触发。痰随气升、气因痰阻，故哮鸣作响。"},{"q":"患者，女，35岁。主诉月经量多，每次月经持续10余日不止，现自觉眩晕，肢体不自主震颤，四肢麻木拘急，面白无华，舌质淡白，脉细无力。辨证属","o":["肝阴虚证","肝火炽盛证","肝血虚证","肝阳上亢证","血虚生风证"],"a":4,"e":"月经量多日久致血虚，见眩晕、肢体震颤、四肢麻木拘急、面白无华、舌淡白、脉细无力，为血虚不能养筋、虚风内动。病本在血虚，故属血虚生风证。"},{"q":"肖某，女，70岁。长期反复腹泻，肛门Ⅰ度脱垂，腹痛隐隐，喜温喜按，平素畏寒、神疲乏力、气短懒言，舌淡苔白滑，脉弱。最宜辨证为","o":["肺气虚证","肾阳虚证","肠虚滑泻证","肾气不固证","寒凝肠道证"],"a":2,"e":"久泻不止、肛门脱垂、腹痛隐隐喜温喜按、畏寒神疲、气短懒言、舌淡苔白滑、脉弱，为脾阳亏虚、肠道失固、中气下陷之肠虚滑泻证。"},{"q":"患者突然昏仆，经救治后口舌歪斜，语言謇涩，一侧上下肢痿废不用，舌淡红，脉弦细。多见于","o":["痿病","中风","截瘫","痹病","佝偻病"],"a":1,"e":"突然昏仆后遗留口舌歪斜、语言謇涩、一侧上下肢痿废不用，为中风之中经络表现，因风痰瘀血阻闭经络。痿病以肢体痿软无力为主，无昏仆病史。"},{"q":"患者腹痛腹泻，大便臭如败卵，多考虑","o":["食积于胃","食积于肠","脾虚食积","肝郁乘脾","心脾两虚"],"a":1,"e":"腹痛腹泻、大便臭如败卵，为宿食停滞肠道、传导失常、腐败下泄，属食积于肠。嗳腐吞酸而大便如常者，病位在胃。"},{"q":"患者，男，76岁。患有慢性支气管炎20余年，胸廓饱满，胁间胀闷，呼吸、咳嗽或转侧时牵引作痛，咯吐白色泡沫痰，舌苔白滑，脉沉弦。辨证为","o":["肺气虚证","痰热壅肺证","风寒犯肺证","寒痰阻肺证","饮停胸胁证"],"a":4,"e":"胸廓饱满、胁间胀闷、呼吸咳唾转侧时牵引作痛、咯吐白色泡沫痰、苔白滑、脉沉弦，为饮停胸胁、气机阻滞、络脉不和。脉沉弦是水饮内停之征。"},{"q":"患者心悸失眠，月经量少色淡，头晕目眩，舌质淡白，脉虚，辨证为","o":["气不摄血证","气血两虚证","气随血脱证","亡阳证","亡阴证"],"a":1,"e":"心悸失眠、月经量少色淡、头晕目眩、舌淡白、脉虚，为气血两虚、心神与清窍失养。气虚鼓动无力、血虚充盈不足，故脉虚而舌淡。"},{"q":"患者，男，68岁。近半月来自觉心慌怔忡，时有心胸憋闷疼痛。平素畏冷肢凉，动辄气短，汗出，随后发凉，神疲乏力。刻下：面色㿠白，口唇发紫，舌质淡胖或紫黯，苔白滑，脉结而无力。此属下列哪个证候","o":["心阴虚证","心血虚证","心气虚证","心阳虚证","心阳暴脱证"],"a":3,"e":"心悸怔忡、心胸憋闷疼痛，兼畏冷肢凉、气短汗出、面色㿠白、舌淡胖紫黯、脉结无力，为心阳亏虚、温运无力、血脉瘀滞。尚未至厥脱之暴脱。"},{"q":"患者，男。右少腹突发疼痛而拒按，且有反跳痛，多为","o":["虫积","肠痈","癥积","瘕聚","筋瘤"],"a":1,"e":"右少腹突发疼痛而拒按，兼有反跳痛，为肠痈瘀热内结、气血壅滞之典型体征。右少腹为阑门所在，湿热瘀阻则痛而拒按。"},{"q":"患者消渴，气上撞心，心中疼热，饥而不欲食，食则吐蛔，下之利不止，其证属","o":["太阴病证","厥阴病证","少阴病证","阳明病证","太阳病证"],"a":1,"e":"消渴、气上撞心、心中疼热、饥不欲食、食则吐蛔、下之利不止，为厥阴病上热下寒、寒热错杂之提纲证。蛔虫内扰、寒热并见是其特点。"},{"q":"患者，女，主诉痛经，月经不调，周期不定，伴有善太息，胸胁、少腹胀满疼痛，走窜不定，舌苔薄白，脉弦。辨证属","o":["肝阴虚证","肝火炽盛证","肝郁气滞证","肝风内动证","寒滞肝脉证"],"a":2,"e":"善太息、胸胁少腹胀满疼痛而走窜不定、脉弦，为肝失疏泄、气机郁滞。痛经与周期不定由气滞血行不畅、冲任失调所致。"},{"q":"患者发热，面红口渴，心烦失眠，小便黄赤，大便干结，舌红苔黄，脉数。证属","o":["表热证","里热证","表里俱热证","真寒假热证","真热假寒证"],"a":1,"e":"发热、面红口渴、心烦失眠、小便黄赤、大便干结、舌红苔黄、脉数，为热邪在里、蒸腾于外之里热证。无恶寒表证，故非表热。"},{"q":"呕吐呈喷射状，属于","o":["热扰神明","肝气犯胃","胃痛","反胃","胃热"],"a":0,"e":"呕吐呈喷射状而与进食无关，为邪热内扰神明、胃气随之上逆所致，多见于颅内病变。一般胃热呕吐多伴嗳腐吞酸、脘腹胀满。"},{"q":"鼻渊的主要特征是","o":["鼻翼扇动","鼻流脓涕","偶流清涕","久流浊涕而腥臭","鼻流黄涕"],"a":3,"e":"鼻渊以鼻流浊涕、量多不止、气味腥臭为特征，常伴鼻塞、头痛、嗅觉减退，因湿热蕴阻鼻窍。偶流清涕者属外感风寒。"},{"q":"咳声如犬吠样，伴声音嘶哑，吸气困难者，称为","o":["百日咳","白喉","燥咳","热咳","寒哮"],"a":1,"e":"咳声如犬吠、声音嘶哑、吸气困难，为白喉疫毒犯肺、咽喉伪膜梗阻气道所致。百日咳为阵发痉挛性咳嗽伴鸡鸣样回声。"},{"q":"患者，女，35岁。胃脘疼痛反复发作5年余，每因饮食不慎而发。1周前因进食冷面而诱发。现症见胃脘冷痛，喜温喜按，得食痛减，形体消瘦，神疲乏力，纳少，舌淡，脉沉无力。其脘痛的病机是","o":["胃气虚","胃阳虚","寒凝胃脘","气滞胃脘","饮停胃脘"],"a":1,"e":"胃脘冷痛、喜温喜按、得食痛减、纳少、神疲乏力、舌淡、脉沉无力，为胃阳不足、虚寒内生、胃失温养。遇冷诱发、得温则缓是虚寒之征。"},{"q":"患者，男，30岁。 高热3天，大渴喜饮，面赤，汗出，舌红苔黄燥，其发热的病机是","o":["气分热盛","阳明腑证","热陷心包","热入营分","湿热蕴结"],"a":0,"e":"高热、大渴喜饮、面赤汗出、舌红苔黄燥，为阳明气分热盛、邪热蒸腾、耗伤津液。未见腹满硬痛、大便不通，故非阳明腑实。"},{"q":"患者，女，23岁。痛经5年，平素急躁易怒，每至经期小腹疼痛难忍，脾气不能自控，舌质紫黯，脉弦，辨证为","o":["气血两虚证","气虚血瘀证","气不摄血证","气随血脱证","气滞血瘀证"],"a":4,"e":"经期小腹疼痛难忍、平素急躁易怒、舌质紫黯、脉弦，为肝气郁滞、血行瘀阻、不通则痛。气滞与血瘀并存，故属气滞血瘀证。"},{"q":"李某，女，31岁。昨日因家事不和，争吵怒骂，今晨突然耳鸣，声大如雷鸣，伴有口苦，左目内眦红赤，胁肋灼痛，胸闷心烦，舌红苔薄黄而干，脉象弦数。该病人突发耳鸣的病机是","o":["肝胆火盛","痰浊上蒙","瘀血阻滞","风邪上袭","肾气虚弱"],"a":0,"e":"争吵后突发耳鸣如雷鸣，伴口苦、目内眦红赤、胁肋灼痛、胸闷心烦、舌红苔黄、脉弦数，为肝胆火盛、循经上扰清窍。起病暴急，属实证之火。"},{"q":"患者，男。感受寒邪，出现少腹冷痛，阴囊收缩掣痛，遇寒加重，得温则减，呕吐清涎，形寒肢冷，舌苔白，最有可能的脉象是","o":["弦紧脉","弦数脉","细数脉","沉细脉","细弦脉"],"a":0,"e":"寒邪客于肝经，见少腹冷痛、阴囊收缩掣痛、遇寒加重、得温则减、呕吐清涎、形寒肢冷，为寒滞肝脉。寒主收引、脉道挛急，故脉弦紧。"},{"q":"患者，男，40岁。平时性情急躁易怒，近2周失眠多梦，头晕，口舌溃疡肿痛，尿黄，大便干结，舌红苔黄，脉滑数。其证候为","o":["肝火上炎证","心火亢盛证","胃火上冲证","脾胃湿热证","肾火上炎证"],"a":1,"e":"失眠多梦、头晕、口舌溃疡肿痛、尿黄、大便干结、舌尖红、苔黄、脉滑数，为心火亢盛、上炎口舌、下移小肠。口舌生疮是心火外现的要点。"},{"q":"患者，女，10岁。壮热烦躁，满面通红，目赤口渴，辨证为","o":["戴阳证","阳虚证","阴虚证","湿热证","实热证"],"a":4,"e":"壮热、满面通红、目赤口渴、烦躁，为邪热亢盛、正邪交争剧烈之实热证。病程短、热势壮、无神疲脉弱之虚象，故属实证。"},{"q":"患者咳血，心烦，身热，舌红绛，脉滑数，诊断为","o":["气虚证","气滞证","血虚证","血热证","血瘀证"],"a":3,"e":"咳血兼身热、心烦、舌红绛、脉滑数，为热入血分、灼伤血络之象。血热证以出血色鲜红、舌绛、脉数为辨证要点，热盛动血故血从上溢而咳血。"},{"q":"患者，男，37岁。1周前出现恶寒发热，倦怠乏力，脘闷不饥，厌油腻，经某医院按“感冒”治疗，恶寒发热减轻。现患者腹痛泄泻，便溏不爽，伴呕恶纳呆，厌食油腻，脘腹痞闷，肢体困重，身热不扬，口微渴，小便短黄，舌质红，苔黄腻，脉濡数。其病证机理为","o":["肝胆湿热","脾胃湿热","湿热感冒","食滞胃脘","肝火犯胃"],"a":1,"e":"湿热蕴结脾胃，气机壅滞，故腹痛泄泻、便溏不爽、脘痞纳呆；身热不扬、苔黄腻、脉濡数为湿热之征。病位在脾胃，无目黄胁痛，故不属肝胆湿热。"},{"q":"患者，女，50岁。两颧潮红，午后低热，心烦失眠，辨证为","o":["阳虚证","阴虚证","戴阳证","实热证","湿热证"],"a":1,"e":"午后低热、两颧潮红、心烦失眠，为阴液亏虚、虚热内生、心神失养之象。阴虚证以潮热盗汗、五心烦热、舌红少苔、脉细数为要点，实热则壮热面赤而脉洪。"},{"q":"患者，男，60岁。腹胀大如鼓，按之如囊裹水，有波动感。应首先考虑的是","o":["水饮","痞满","积聚","水臌","内痈"],"a":3,"e":"腹部膨隆如鼓，按之如囊裹水且有波动感，为水液停聚腹腔之臌胀，属水臌。气鼓按之空空然无波动，可与之鉴别。"},{"q":"患者头面部皮肤焮红灼热，色如涂丹，肿胀疼痛，甚至发生水疱，眼胞肿胀难睁；伴恶寒发热，头痛，舌红，苔薄黄，脉浮数。此病宜诊断为","o":["风热火毒上攻之抱头火丹","天行时疫，火毒上攻之大头瘟","血分火毒之丹毒","湿热毒蕴之流火","肝经郁火之赤游丹"],"a":0,"e":"头面皮肤焮红灼热、色如涂丹、肿胀疼痛，发于头面者称抱头火丹，由风热火毒上攻所致。大头瘟虽亦头面肿，但以腮部肿硬、无丹色为别。"},{"q":"患者潮热，盗汗2年，昨日起恶寒低热，头项强痛，舌红苔白，脉浮细，证属","o":["表实寒里虚热","表实热里虚寒","表实寒里虚寒","表实热里虚热","表实热里实寒"],"a":0,"e":"潮热盗汗日久属里虚热，新起恶寒、头项强痛、脉浮为外感风寒之表实证，两相兼夹故为表实寒里虚热。舌红为虚热内蕴之征。"},{"q":"患者，女，39岁。小便频数2日，一昼夜达20余次，尿时涩痛不爽，小腹胀闷，尿道灼热，小便黄赤短少，口干，舌红，苔根部黄腻，脉滑数。其尿频的病机为","o":["膀胱湿热","小肠实热","肾阴亏虚","肾阳不足","肾气不固"],"a":0,"e":"尿频尿急、尿道灼热、小便黄赤短少，伴舌红苔根黄腻、脉滑数，为湿热蕴结膀胱、气化失司。肾气不固之尿频必见腰膝酸软、尿清长。"},{"q":"患者，男，28岁。腹痛泄泻反复发作已2年余，常因情志不遂或精神紧张而发，曾在某西医院诊断为“肠易激综合征”，因服西药无显效而求治中医。患者腹痛即泻，泻后痛减，每日4～5次，伴胸胁胀闷，情志抑郁，善太息，腹胀纳呆，肠鸣矢气，舌苔白，脉弦。中医辨证为","o":["脾气虚弱","肝郁脾虚","大肠湿热","心脾两虚","脾肾阳虚"],"a":1,"e":"腹痛即泻、泻后痛减，随情志波动而发，兼胸胁胀闷、善太息、脉弦，为肝气郁结、木旺乘土；脾失健运故纳呆腹胀，属肝郁脾虚。"},{"q":"患者颈前结喉处有肿块突起，见于双侧，可随吞咽上下移动，伴有眼球突出，形体消瘦，为","o":["瘿瘤","瘰疬","痄腮","发颐","乳蛾"],"a":0,"e":"颈前结喉两侧肿块，随吞咽上下移动，伴目突、消瘦，为瘿瘤，因情志内伤、气滞痰凝结于颈部。瘰疬生于颈项，为串珠状结节，不随吞咽移动。"},{"q":"蔡某，女，42岁，3日前食生鱼片后自觉胃脘冷痛，遇寒加剧，得温则减，口淡不渴，口泛清水，舌苔白润，脉弦。诊为","o":["胃阳虚证","寒滞胃脘证","胃热炽盛证","饮停胃肠证","食滞胃脘证"],"a":1,"e":"胃脘冷痛、遇寒加剧、得温则减、口淡泛清水、苔白润，为寒邪凝滞胃脘、气机不通。胃阳虚者病程久、痛而喜按、脉沉迟无力。"},{"q":"患者，男，34岁。感冒痊愈后，遗留了咳痰的后遗症，刻下症见咳嗽痰多，痰质黏稠，恶心纳呆，头晕目眩，舌苔腻，脉滑。辨证为","o":["津液亏虚证","饮证","痰证","水停证","血热证"],"a":2,"e":"咳嗽痰多、痰质黏稠，兼恶心纳呆、头晕目眩、苔腻脉滑，为痰浊内蕴、阻滞气机、上蒙清阳。饮证痰涎清稀，水停证以水肿尿少为主。"},{"q":"患者，女，78岁。主诉手足震颤，肢体不自主抽动，伴有眩晕，口干，五心烦热，形体消瘦，舌红少津，脉弦细数。辨证属","o":["肝阴虚证","肝火炽盛证","阴虚动风正","肝阳上亢证","寒滞肝脉证"],"a":2,"e":"手足震颤、肢体抽动，兼眩晕、五心烦热、舌红少津、脉弦细数，为阴液亏虚、筋脉失养而虚风内动。肝阳上亢以头胀痛、面赤、脉弦劲为特点。"},{"q":"患者胸胁灼痛，急躁易怒，咳嗽阵作，有时痰中带血，痰色黄黏，面红目赤，舌红苔黄，脉弦数。应诊断为","o":["痰热壅肺证","肝火上炎证","肺热炽盛证","肝火犯肺证","肝胃不和证"],"a":3,"e":"胸胁灼痛、急躁易怒、面红目赤、脉弦数，为肝经火盛；咳嗽阵作、痰黄黏带血，为木火刑金。病本在肝而标在肺，故属肝火犯肺证。"},{"q":"患者小腿青筋怒张隆起，形似蚯蚓，多属","o":["肝风内动，筋脉拘急","寒湿内侵，络脉血瘀","寒湿久留，气血亏虚","脾肾失调，水湿停留","肾精亏损，发育不良"],"a":1,"e":"小腿青筋怒张如蚯蚓，因寒湿侵袭、阻滞脉络、血行瘀滞所致，多见于久立负重之人。脾肾失调、水湿停留当见水肿，非青筋显露。"},{"q":"患者肛门内生有紫红色柔软肿块，伴便血、疼痛、便秘等症状，为","o":["肛裂","痔疮","肛瘘","脱肛","肛痈"],"a":1,"e":"肛门内紫红色柔软肿块，伴便血、疼痛、便秘，为痔疮，因湿热下注、血脉瘀阻而成。脱肛为直肠黏膜脱出，肛裂为肛管裂伤而便时剧痛。"},{"q":"患者畏寒肢冷，尿少浮肿，心悸怔忡，口唇爪甲青紫，舌质淡胖，苔白滑，脉沉细。应诊断","o":["脾阳虚证","心阴虚证","肾阳虚证","心肾阳虚证","脾肾阳虚证"],"a":3,"e":"畏寒肢冷、尿少浮肿属肾阳虚水泛，心悸怔忡、唇甲青紫属心阳虚衰、血行瘀滞，两者并见为心肾阳虚。单纯肾阳虚无水气凌心之心悸。"},{"q":"患者，男，30岁。寒战后高热，反复发作，每2日1次，伴剧烈头痛，口渴多汗等症，其寒热类型属于","o":["恶寒发热","但寒不热","新病恶寒","寒热往来","但热不寒"],"a":3,"e":"寒战高热与汗出热退交替、定时而作，为邪在半表半里、正邪交争之寒热往来，常见于疟疾。恶寒与发热同时并见者属表证，与此不同。"},{"q":"患者经常刷牙时牙龈渗血，见牙龈萎缩，颜色淡白，牙根宣露，牙齿松动，咀嚼无力。症见面色淡白，倦怠乏力，头晕眼花，胃呆纳少，舌淡，苔薄白，脉沉细。此病最宜诊断为","o":["脾不统血","肾阴亏虚","胃阴不足","脾阳亏虚","胃火亢盛"],"a":0,"e":"牙龈渗血而色淡、龈肉萎缩、牙齿松动，兼面色淡白、倦怠乏力、舌淡脉细，为脾气虚弱、统血无权。胃火亢盛之齿衄必龈红肿痛、口臭、脉洪数。"},{"q":"患者怵惕不安，闭门独处，形体消瘦，甚则二便失禁，宜诊断为","o":["喜伤证","忧伤证","思伤证","惊伤证","恐伤证"],"a":4,"e":"怵惕不安、闭门独处、形体消瘦，甚则二便失禁，为恐惧伤肾、气机下陷、肾失封藏之象。惊伤证以惊悸怔忡、神志错乱为主。"},{"q":"听声音不包括下列哪项内容","o":["呼吸","肠鸣","耳鸣","语言","咳嗽"],"a":2,"e":"听声音包括语声、呼吸、咳嗽、呕吐、呃逆、嗳气、肠鸣等。耳鸣须由患者自述，属问诊所得症状，不属闻诊内容。"},{"q":"患者身热，口渴，面赤，烦躁不宁，月经先期量多，舌红绛，脉弦数，此证为","o":["阴虚证","瘀热互结证","血热证","湿热证","气虚发热证"],"a":2,"e":"身热口渴、面赤烦躁，兼月经先期量多、舌红绛、脉数，为热入血分、迫血妄行。血热证以出血、舌绛、脉数为要点，阴虚之热则脉细数而出血量少。"},{"q":"患儿，男，12岁，学生。2天前出现发热，恶寒，伴有咳嗽、口微渴、咽痛、小便黄，其舌象表现多为","o":["舌质淡红，苔薄白","舌质红、苔薄黄","舌质淡红，苔黄燥","舌质红，苔黄腻","舌质红绛，苔少"],"a":1,"e":"外感风热初起，邪在肺卫，故舌质红、苔薄黄、脉浮数。苔薄白主风寒表证，苔黄腻主湿热内蕴，苔少主阴液已伤。"},{"q":"患者腹痛灼热，拒按，按之痛甚，伴有腹部硬满者为","o":["鼓胀","气胀","内痈","阳明腑证","阳明经证"],"a":3,"e":"腹痛灼热拒按、按之痛甚而腹部硬满，为燥屎内结、腑气不通之阳明腑实证，必伴便秘、潮热、脉沉实。阳明经证以身大热、汗大出、脉洪大为特点。"},{"q":"患者，女，49岁。平素胸胁胀满疼痛，情志抑郁或烦躁，且出现脘腹胀满，呃逆食少，腹胀便溏等症状，望诊可能的面色为","o":["青黄","红色","白色","黄色","青色"],"a":0,"e":"胸胁胀满、情志抑郁属肝郁，脘腹胀满、便溏食少属脾虚，肝郁脾虚之色当见青黄。青主肝、黄主脾，二色并见正合肝脾同病。"},{"q":"患者反复鼻中出血，量不多，口燥咽干，鼻干，干咳无痰，五心烦热，潮热盗汗，舌红少苔，脉细数。诊为","o":["肺经风热","胃热炽盛","肝火上逆","阴虚肺燥","脾不统血"],"a":3,"e":"鼻衄量少，兼口燥咽干、干咳无痰、潮热盗汗、舌红少苔、脉细数，为肺阴亏虚、燥热伤络。胃热之鼻衄量多色鲜红，伴龈肿口臭、脉洪数。"},{"q":"患者平素易汗出，活动后更甚，伴气短，疲乏，舌淡嫩，脉虚。证属","o":["气虚证","气陷证","气不固证","气逆证","气滞证"],"a":2,"e":"平素易汗、动则益甚，伴气短疲乏、舌淡嫩、脉虚，为卫气虚弱、肌表不固之自汗，属气不固证。气陷证以脏器下垂、久泄脱肛为特征。"},{"q":"患者头晕目眩，乏力少气，自汗，面色萎黄，心悸多梦，唇甲淡白，舌淡瘦薄，脉细无力。其临床意义是","o":["气虚血瘀证","气滞血瘀证","气血两虚证","气虚证","血虚证"],"a":2,"e":"头晕乏力、自汗气短属气虚，面色萎黄、心悸多梦、唇甲淡白、舌淡瘦薄属血虚，气血俱亏故为气血两虚证，脉细无力为虚损之征。"},{"q":"张某，男，11岁，学生。1个月前出现咳嗽，未予重视。近半月来咳嗽加重，但不吐痰，夜间盗汗，午后低热，咽干微渴，食纳欠佳，大便稍干，其舌象可见","o":["舌质淡红，苔薄白","舌质红，苔黄腻","舌质淡红，苔白腻","舌质红，苔少","舌质红，苔黄燥"],"a":3,"e":"久咳不愈、夜间盗汗、午后低热、咽干，为肺阴耗伤、虚热内生，舌当红而苔少。苔白腻主痰湿，苔黄燥主实热伤津，均与阴虚不符。"},{"q":"神识昏迷而鼾声不绝者，多属","o":["慢性鼻病","睡姿不当","高热神昏","身体肥胖","老年之人"],"a":2,"e":"神识昏迷而鼾声不绝，为热陷心包、痰热蒙蔽清窍之候，多见于温病高热神昏。睡姿不当或体胖之鼾声见于熟睡，神志清楚、呼之能应。"},{"q":"患者，男，35岁。身热气粗，面红目赤，腹满便秘，口燥咽干，大便干结，小便短赤，苔黄燥，其临床意义是","o":["湿滞脾胃证","湿热积滞肠腑证","阳明燥结证","太阴湿热","热郁胆经"],"a":2,"e":"身热气粗、腹满便秘、口燥咽干、苔黄燥，为燥热与糟粕互结于阳明之腑，即阳明燥结证。湿热积滞肠腑者苔必黄腻、便溏不爽。"},{"q":"患者，女，42岁。主诉视力减退，伴有爪甲脆折，肢体麻木，关节屈伸不利，月经量少、色淡。面唇淡白，舌淡，脉细。辨证属","o":["肝阴虚证","肝火炽盛证","肝血虚证","肝风内动证","寒滞肝脉证"],"a":2,"e":"视力减退、爪甲脆折、肢体麻木、月经量少色淡，兼面唇淡白、舌淡脉细，为肝血不足、筋目失养。肝阴虚必兼五心烦热、舌红少津等虚热象。"},{"q":"患者神识痴呆，半身不遂，皮肤干燥如鱼鳞，舌有紫色斑点，脉弦细涩，为","o":["血虚证","液脱证","血瘀证","阴虚证","津亏证"],"a":2,"e":"神识痴呆、半身不遂，皮肤干燥如鱼鳞，舌有紫斑、脉细涩，为瘀血阻滞、新血不生、肌肤失养之象。血虚证肌肤枯糙而无紫斑及固定刺痛。"},{"q":"患者大渴喜冷饮，壮热，面赤，汗出，舌红苔黄燥，脉洪数，属","o":["阳明经证（气分热盛）","阳明腑证","消渴病","温病营分证","湿热证"],"a":0,"e":"大渴喜冷饮、壮热面赤、汗出、脉洪数，为热盛于阳明气分而未与糟粕相结，即阳明经证。阳明腑证必见腹满硬痛、便秘、苔黄燥。"},{"q":"患者，女，54岁。患者双足浮肿，时间长达1年，近期出现下肢浮肿3个月余，舌胖大，苔白，脉濡。辨证为","o":["痰证","饮证","阴水","阳水","支饮"],"a":2,"e":"阴水由脾肾阳虚、气化不行所致，其肿起病缓、病程长，多从下肢开始，按之凹陷，舌胖大苔白、脉濡。阳水起病急、多从头面先肿。"},{"q":"患者突然腹部绞痛，弯腰屈背，辗转不宁，冷汗淋漓，恶心呕吐，手足厥冷，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":2,"e":"突发腹部绞痛、辗转不安、冷汗、呕吐而手足厥冷，为蛔虫内扰、气机逆乱、阳气不达四末之蛔厥。肠道蛔虫以脐周隐痛、吐虫便虫为主。"},{"q":"患者面色淡白，神疲乏力，气短懒言，食少纳呆；面色晦滞、局部青紫、肿胀、刺痛不移而拒按，舌淡紫有紫斑，脉细涩，其临床意义是","o":["气滞血瘀证","气滞证","气虚血瘀证","血瘀证","血虚证"],"a":2,"e":"面色淡白、神疲气短、食少属气虚，局部青紫刺痛拒按、舌淡紫有紫斑、脉细涩属血瘀，气虚无力行血而致瘀，故为气虚血瘀证。"},{"q":"患者新病耳内流脓，脓液黄稠而量多，伴面红目赤，口苦咽干，大便干燥，小便黄赤，舌质红，苔黄腻，脉弦数。上述症状宜辨证为","o":["肝经火热，热伤血分","脾虚湿困，上犯耳窍","肾虚，虚火上炎","肝胆湿热上蒸","心火炽热，上侵脑髓"],"a":3,"e":"新病耳内流脓黄稠量多，伴面红目赤、口苦咽干、舌红苔黄腻、脉弦数，为肝胆湿热循经上蒸耳窍。肾虚虚火之脓液清稀、病程缠绵、伴腰膝酸软。"},{"q":"患者下肢痿软无力，不能站立，神疲乏力，食少，舌淡嫩，脉弱，属于","o":["气虚证","气陷证","气不固证","血虚证","气逆证"],"a":0,"e":"下肢痿软无力、神疲乏力、食少、舌淡嫩、脉弱，为脾胃气虚、气血生化不足、肌肉失养之痿证。气陷证以气坠、脏器下垂为特点。"},{"q":"患者，女，70岁。数年来常感神疲乏力，腹胀便溏。半个月前因劳累再发，现自觉阴道中有物突出，并有下坠感，神疲乏力，气短，头晕目眩，纳少便溏，舌淡苔白，脉缓弱，多属","o":["气虚证","气陷证","气不固证","血虚证","气血两虚证"],"a":1,"e":"阴中有物突出、下坠感，劳则加重，兼气短乏力、纳少便溏，为脾气升举无力、中气下陷，属气陷证。气虚证无脏器下垂之表现。"},{"q":"患者惊悸怔忡，健忘失眠，坐卧不安，甚则神志错乱，宜诊断为","o":["喜伤证","忧伤证","思伤证","惊伤证","恐伤证"],"a":3,"e":"惊悸怔忡、坐卧不安，甚则神志错乱，为卒受惊恐、气机逆乱、心神不宁之惊伤证。恐伤证以气怯、二便失禁为主，思伤证以纳呆消瘦为主。"},{"q":"患者，男，20岁。咳嗽2天。痰稠色黄，伴有发热微恶风寒，鼻塞流浊涕，舌尖红，苔薄黄，辨为风热犯肺证。其脉象最易表现为","o":["浮缓","浮紧","浮数","浮细","浮滑"],"a":2,"e":"风热犯肺属表热证，脉当浮而兼数，故见浮数。浮缓主太阳中风，浮紧主风寒表实，浮细见于表虚或湿邪，浮滑多见于痰饮。"},{"q":"患者胞睑肿胀，白睛红赤，痒痛兼作，羞明多泪。伴有头痛鼻塞，恶风发热，舌苔薄白或微黄，脉浮数等。此病宜诊断为","o":["肝火上炎","外感风热","脾胃湿热","肝经风热","肺热炽盛"],"a":1,"e":"胞睑肿胀、白睛红赤、痒痛羞明多泪，兼头痛鼻塞、恶风发热、脉浮数，为风热外袭目窍，属外感风热。肝火上炎无表证，而见口苦、脉弦数。"},{"q":"患者在临床上表现为肋间饱满，咳唾引痛，胸闷息促，应为","o":["痰饮","悬饮","溢饮","支饮","皮饮"],"a":1,"e":"饮停胸胁、络脉受阻，故肋间饱满、咳唾引痛、胸闷息促，为四饮中的悬饮。支饮停于胸膈，见咳逆倚息不得卧；溢饮饮溢四肢而见肢肿。"},{"q":"患者，老年男性。体素弱，按诊虚里搏动迟弱，多为","o":["中气不足","心阴亏虚","心阳不足","心血亏虚","心肺气虚"],"a":2,"e":"虚里为心尖搏动处，其搏动迟弱提示心阳不振、鼓动无力。心阴亏虚者搏动细数，心血亏虚者搏动无力而不迟。"},{"q":"患者反复咳喘7年，叩诊肺下界下移，可见于","o":["肺痨","肺痿","肺痈","肺胀","肺热"],"a":3,"e":"久患咳喘，肺失宣降、气壅胸中，胸廓胀满而肺下界下移，为肺胀。肺痨以咳嗽咯血、潮热盗汗为主，肺痿以咳吐浊唾涎沫为主。"},{"q":"患者女，乳房有大小不一的肿块，边界不清，质地不硬，活动度好，每次月经前疼痛，多为","o":["乳痈","乳痨","乳癖","乳癌","乳疬"],"a":2,"e":"乳房肿块大小不一、边界不清、质地不硬、活动度好，经前胀痛，为乳癖，因肝郁气滞、痰凝血瘀而成。乳癌肿块坚硬固定、边界不整。"},{"q":"患者，男，19岁。患者今晨猝然昏倒，四肢抽搐，两目上视，口吐白沫，口中发出如猪羊叫声，3~5分钟后苏醒，醒后一如常人。属于","o":["中风","癫病","痫病","狂病","郁病"],"a":2,"e":"猝然昏倒、四肢抽搐、两目上视、口吐白沫、喉发畜叫，移时苏醒一如常人，为痫病发作。中风昏倒后多遗半身不遂、口眼歪斜。"},{"q":"患者寒热往来，口苦，咽干，目眩，舌淡红，脉弦细，诊断为少阳病，其中寒热往来，口苦，咽干，目眩，属于具备诊断的","o":["必要性资料","特征性资料","偶见性资料","一般性资料","否定性资料"],"a":1,"e":"寒热往来、口苦咽干、目眩为少阳病特有表现，是确立该病诊断的特征性资料。必要性资料指必备而无特异性的表现，一般性资料则常见而指向不明。"},{"q":"腹痛肠鸣，大便不调，矢气痛减，胁胀窜痛，苔白脉弦，宜诊断为","o":["胃肠气滞证","肝气郁结证","肝胃不和证","肝脾不和证","气机阻滞证"],"a":3,"e":"腹痛肠鸣、便溏不爽、矢气痛减、胁胀窜痛、脉弦，为肝气犯脾、脾失健运，属肝脾不和。肝气郁结仅见胸胁胀痛、情志抑郁而无肠鸣便溏。"},{"q":"患者，男，70岁。目无光彩，面色晦暗，两眼运动呆滞，皮肤枯槁，面色晦暗，见于","o":["失神","少神","得神","假神","神乱"],"a":0,"e":"目无光彩、面色晦暗、两眼呆滞、皮肤枯槁，为精气衰败、脏腑功能衰微之失神。少神仅见精神不振、倦怠乏力，目光尚明。"},{"q":"患者手足厥冷，烦渴喜冷，便干尿赤，舌红苔黄而干，脉洪数有力，证属","o":["阳虚外寒证","真热假寒证","阴虚内热证","表寒里热证","真寒假热证"],"a":1,"e":"手足厥冷而胸腹烦热、渴喜冷饮、便干尿赤、脉洪数有力，为热邪深伏、阳郁不达四末之真热假寒。真寒假热则身热反欲近衣、脉微细。"},{"q":"长期咳喘，气短乏力，呼多吸少，自汗耳鸣，舌淡脉弱，应辨证为","o":["脾肺气虚证","肺气虚证","肾气不固证","肺肾气虚证","肾阳虚证"],"a":3,"e":"久病咳喘、气短乏力、呼多吸少，为肺肾两虚、肾不纳气；自汗耳鸣、舌淡脉弱为气虚之征，故属肺肾气虚证。肾阳虚必兼畏寒肢冷、水肿。"},{"q":"患者，女，39岁。突发高热，神昏，肢厥，神昏谵语，舌质红绛，其临床意义是","o":["上焦病之逆传心包","中焦病之阳明燥结","中焦病之太阴泻热","下焦病之肾阴亏虚","下焦病之肝风内动"],"a":0,"e":"温病初起高热，旋即神昏谵语、肢厥、舌绛，为邪由上焦肺卫直陷心包，属逆传心包。顺传则见中焦阳明气分证。"},{"q":"患者，女，43岁。2天前因受凉而出现眼睑水肿，后迅速波及颜面、全身，以上半身水肿更甚，伴有小便短少，恶寒发热，无汗，舌淡红，苔薄白，脉浮紧。辨证为","o":["寒痰阻肺证","风水搏肺证","脾肾阳虚证","心阳不足证","肾虚水泛证"],"a":1,"e":"风邪袭肺、宣降失职、通调水道不利，故眼睑先肿而迅速遍及全身、上半身甚，伴恶寒发热无汗、脉浮紧，为风水搏肺证。肾虚水泛以下肢肿甚、腰膝酸软为主。"},{"q":"患者，男，52岁。面目一身俱黄，色黄晦暗如烟熏，为","o":["萎黄","黄胖","阴黄","阳黄","淡黄"],"a":2,"e":"阴黄由寒湿困脾、胆汁不循常道而外溢肌肤所致，其色晦暗如烟熏，伴畏寒、脘闷、苔白腻。阳黄则黄色鲜明如橘，属湿热熏蒸。"},{"q":"患者，女，30岁。恶寒发热3天，昨日伴轻微咳嗽，痰稀白，量不多，恶寒重发热轻，头痛，鼻塞流清涕，口不渴，舌淡红苔薄白，脉浮紧。其恶寒发热的临床意义是","o":["风热表证","风寒表证","伤风表证","里实寒证","寒邪客肺证"],"a":1,"e":"恶寒重发热轻、无汗、鼻塞流清涕、苔薄白、脉浮紧，为风寒束表、卫阳被遏之表寒实证。风热表证则发热重恶寒轻、咽痛、脉浮数。"},{"q":"患者，男，6岁。发热、微恶风寒、少汗或无汗，舌边尖红，脉浮数，其辨证为","o":["风热犯卫","暑湿犯卫","风寒犯肺","燥热犯肺","湿热犯卫"],"a":0,"e":"发热微恶风寒、少汗、舌边尖红、脉浮数，为风热之邪侵袭肺卫，属风热犯卫。暑湿犯卫当见身热不扬、胸闷、苔腻。"},{"q":"月经量少，面色萎黄，乏力身倦，食少腹胀，心悸失眠，舌淡。辨证应为","o":["气不摄血证","肝血虚证","脾不统血证","心脾两虚证","心血虚证"],"a":3,"e":"月经量少、面色萎黄、食少腹胀属脾虚失运，心悸失眠属心血不足，心脾两虚故见此证。脾不统血必有出血，肝血虚以爪甲不荣、肢麻为主。"},{"q":"患者，女，67岁。近期胸闷脘痞，呕吐清水，肋间饱满，头晕目眩，苔滑，脉弦，辨证为","o":["亡阳证","水停证","饮证","痰证","津液亏虚"],"a":2,"e":"胸闷脘痞、呕吐清水、肋间饱满、头晕目眩、苔滑脉弦，为水饮停聚胸胁胃肠、清阳不升，属饮证。痰证以痰多黏稠、苔腻为主。"},{"q":"患者，男，65岁。眩晕，耳鸣如蝉，健忘失眠，胁痛，腰膝酸痛，盗汗，舌红少苔，脉细数。其证候是","o":["肾精不足","肾阴虚","肝阴虚","肝肾阴虚","肝阳上亢"],"a":3,"e":"眩晕耳鸣、健忘失眠、胁痛为肝阴不足，腰膝酸痛、盗汗、舌红少苔、脉细数为肾阴亏虚，肝肾同病故为肝肾阴虚。肝阳上亢必见头胀痛、脉弦劲。"},{"q":"病人恶寒，脉微细，但欲寐，四肢厥冷，下利清谷，呕不能食，其证属","o":["太阴病证","厥阴病证","少阴热化证","少阴寒化证","阳明病证"],"a":3,"e":"恶寒、脉微细、但欲寐、四肢厥冷、下利清谷，为心肾阳气衰微、阴寒内盛之少阴寒化证。少阴热化证则见心烦不得卧、咽干、舌红。"},{"q":"患者表现为心悸怔忡，喘息不得平卧，心下痞坚，面色黧黑，小便短少，舌质淡苔白滑，脉沉紧是","o":["饮停胸胁证","饮停心包证","饮停胃肠证","寒饮停肺证","饮邪客肺证"],"a":1,"e":"心悸怔忡、喘不得卧、心下痞坚、面色黧黑、脉沉紧，为水饮凌心射肺、阻遏心阳之饮停心包证。饮停胸胁以咳唾引痛为主。"},{"q":"钱某，男，35岁。平素嗜酒，近半月脘腹胀闷，纳呆，恶心欲呕，口苦，便溏不爽，舌红苔黄腻，脉濡数。诊为","o":["胃热炽盛证","肠热腑实证","湿热蕴脾证","肝胆湿热证","食滞胃脘证"],"a":2,"e":"嗜酒酿生湿热，蕴结脾胃，升降失常，故脘腹胀闷、纳呆呕恶、便溏不爽；舌红苔黄腻、脉濡数为湿热之征。无身目发黄，故不属肝胆湿热。"},{"q":"胃脘冷痛喜按，吐清水，口淡不渴，舌淡嫩，脉沉迟无力，应辨证为","o":["寒湿困脾证","脾阳虚证","胃阳虚证","寒滞胃脘证","胃气虚证"],"a":2,"e":"胃脘冷痛喜按、吐清水、口淡不渴、舌淡嫩、脉沉迟无力，为胃阳不足、温煦腐熟失职。寒滞胃脘证多新病、痛剧拒按、脉弦紧。"},{"q":"哮与喘的鉴别要点为","o":["是否呼吸急迫","是否睡能平卧","是否张口抬肩","是否喉间痰鸣","是否发作急骤"],"a":3,"e":"哮以喉间痰鸣有声为特征，喘以呼吸困难、气息急迫为特征，故二者鉴别在于有无喉间痰鸣。哮必兼喘，喘未必兼哮。"},{"q":"患者，女，55岁。主诉失眠，伴有胆怯易惊，时有心悸，或烦躁不安，胸胁闷痛，自觉口苦，舌红，苔黄腻，脉弦滑数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","胆郁痰扰证","肝郁气滞证"],"a":3,"e":"失眠、胆怯易惊、心悸烦躁，兼胸胁闷痛、口苦、苔黄腻、脉弦滑数，为痰热内扰胆腑、胆气不宁之胆郁痰扰证。肝火炽盛以目赤头痛、脉弦数为主。"},{"q":"患者，男，72岁。素有心脏病，突觉心胸憋闷疼痛而晕倒，就医时冷汗淋漓，面色苍白，四肢冰凉。其脉象应为","o":["动脉","微脉","革脉","濡脉","弱脉"],"a":1,"e":"阳气暴脱、脉气欲绝，故见微脉，其象极细极软、似有似无、按之欲绝。弱脉沉细而软，主气血不足，尚非阳气暴脱之候。"},{"q":"下列除哪项以外，均是斑与疹的辨证要点","o":["色红或不红","形状的大小","摸之碍手与不碍手","平摊于皮肤下或稍隆起","点大成片与形小如粟"],"a":0,"e":"斑与疹的鉴别在于形态大小、平摊或隆起、摸之碍手与否，色红与否为二者共性，不属鉴别要点。斑平摊成片、摸之不碍手，疹形小如粟、高出皮肤。"},{"q":"患者鼻头及鼻翼部色红生有粉刺，常嗜酒，便秘，饮食不节，口干口渴，舌红，苔黄，脉滑。宜辨证为","o":["胃火亢盛","热毒壅盛","肺胃热盛","肺经风热","湿热蕴结"],"a":2,"e":"鼻头及鼻翼红赤生粉刺，兼嗜酒、便秘、口干，为肺胃积热上熏鼻窍之酒齄鼻。肺经风热多兼表证，热毒壅盛以红肿化脓为特征。"},{"q":"久病呃逆不止，声低气怯无力，多属","o":["胃气衰败","热邪客胃","寒邪犯胃","偶感风寒","宿食内停"],"a":0,"e":"久病呃逆、声低气怯无力，为脾胃气败、胃气上逆之危候。新病呃逆声响有力者，多属寒邪或食滞犯胃之实证。"},{"q":"Page-Frame吕某，男，51岁，军人。2016年7月9日初诊。胸闷，心悸，阵发性心前区刺痛1年，加重3天。1年来反复出现胸闷、心悸，偶有心前区刺痛。3天前因出差返家，旅途乘车劳累，到家用热水洗澡后，胸闷、心悸加重，伴心前区刺痛，经休息后稍缓解。此后因进餐胸闷、心悸复加重，并有阵发性心前区刺痛，向颈肩、左上肢放射，伴有下牙及腹部作痛，舌感麻木，急请医生到家查心电图，提示心肌缺血。平时患有高脂血症。急收入院。查：体胖高大，舌淡胖苔白厚，脉弦滑，血压14/8kPa（105/60mmHg），心律整，心率60次/min……病案中的“1年来反复出现胸闷、心悸……舌感麻木”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":2,"e":"患者就诊时的主要痛苦及其起病、演变过程属现病史，是病案的主体部分。主诉仅为最主要症状与持续时间的高度概括。"},{"q":"下列哪项不属于水痘的痘形特点","o":["椭圆形，肤浅易破","顶部无脐，偶有脐凹","痘粒成对，大小齐等，一起出现","浆薄如水，晶莹明亮","不结厚痂，不留痘痕"],"a":2,"e":"水痘痘形椭圆、肤浅易破、浆薄如水、晶莹明亮，顶部多无脐，脱痂后不留痘痕。痘粒成对、大小齐等、一齐出现为天花的特征。"},{"q":"患者腹部膨隆，腹壁青筋暴露，四肢消瘦，面色晦暗，舌青紫，脉涩，多为","o":["水肿","鼓胀","积聚","悬饮","支饮"],"a":1,"e":"腹部膨隆、青筋暴露而四肢消瘦，为肝脾失调、气滞血瘀水停之鼓胀。水肿多全身浮肿、按之凹陷，无腹壁青筋怒张。"},{"q":"患者，女，30岁。入秋后不慎感冒，症见干咳少痰，痰黏难咯，口干咽燥，伴发热恶风寒，舌红苔薄干，脉浮数。其辨证为","o":["肺阴虚证","风热表证","肺热炽盛证","痰热壅肺证","燥邪犯肺证"],"a":4,"e":"秋季燥邪犯肺，肺津受伤，故干咳少痰、痰黏难咯、口干咽燥，兼表证而苔薄干、脉浮数。肺阴虚属久病内伤，无恶寒发热之表证。"},{"q":"患者阳强易举，五心烦热，眩晕耳鸣，腰膝酸痛，舌红少苔，宜诊断为","o":["肾气不固证","肾阴虚证","肝肾阴虚证","心肾不交证","肾阳虚证"],"a":1,"e":"阳强易举、五心烦热、眩晕耳鸣、腰膝酸痛、舌红少苔，为肾阴亏虚、相火妄动。肾气不固以滑精早泄、尿后余沥为主而无虚热之象。"},{"q":"心悸怔忡与下列哪项并见，对诊断心肾阳虚证最有意义","o":["食少腹胀、肢肿","心胸憋闷、舌黯","肢体浮肿、形寒","畏寒肢冷","冷汗肢厥"],"a":2,"e":"心肾阳虚则水气不化、泛溢肌肤，故肢体浮肿；阳虚失于温煦故形寒，二者并见最能提示病已及肾。单纯畏寒肢冷亦可见于心阳虚。"},{"q":"患者斑疹布点稠密，色现深红或紫黑，并且斑疹先从四肢出现，然后内延胸腹，同时大热不退，神识昏迷，舌红绛，脉数。其属于","o":["斑疹顺症","风疹","湿疹","疔毒走黄","斑疹逆症"],"a":4,"e":"斑疹先四肢后胸腹、稠密而色深紫黑，兼壮热神昏、舌绛脉数，为热毒内陷、正不胜邪之逆证。顺证多先胸腹后四肢、疹色红活、神清。"},{"q":"患者素体阴虚火旺，复感风寒之邪，其舌象可表现为","o":["舌淡苔薄白","舌淡红苔薄白","舌淡苔薄黄","舌绛苔薄黄","舌绛苔薄白"],"a":4,"e":"素体阴虚火旺故舌绛，新感风寒在表故苔薄白，苔尚未化热。若苔薄黄则示表邪已化热入里，与初感风寒不符。"},{"q":"患者，女，29岁。患者平素喜食偏辣，日久引起口干、咽干、眼睛痒，因此患者除了有内热证以外，还兼有","o":["血瘀","血虚","津亏","血寒","气滞"],"a":2,"e":"辛燥偏嗜日久化热伤津，津液不足失于濡润，故口干、咽干、目涩。津亏证以口燥咽干、舌红少津、尿少便干为要点。"},{"q":"患者长期心悸怔忡，心胸憋闷，唇色青紫，气短自汗，畏寒肢冷，面色㿠白，舌淡胖，苔白滑，最不可能出现的脉象是","o":["弦紧","沉迟无力","细微","结代","脉弱"],"a":0,"e":"心阳虚衰、血行不畅，脉当沉迟无力、细微、结代或弱。弦紧主寒主痛，为实寒之脉，虚寒之证不应出现。"},{"q":"患者发热，其手心较手背热甚者，多为","o":["外感发热","内伤发热","实证发热","气郁发热","瘀血发热"],"a":1,"e":"手心属阴、手背属阳，内伤发热由阴虚阳亢或气郁化火，故手心热甚于手背；外感发热阳热盛于表，则手背热甚于手心。"},{"q":"患者，男，40岁。发热，咳嗽，胸闷，心烦口渴，肌肤外发红疹，舌红，苔薄黄，脉数，其病变阶段是","o":["气分","卫分","气营两燔","营分","血分"],"a":2,"e":"壮热口渴、咳嗽胸闷属气分热盛，肌肤红疹、舌红为热已波及营分，故为气营两燔。纯营分证以身热夜甚、神昏谵语、舌绛无苔为特征。"},{"q":"患者阴部湿疹日久，皮肤粗糙变厚，呈苔藓样变，瘙痒难忍，舌红少苔，脉细，多属","o":["阴虚血燥","肝经湿热","带脉失约","冲任虚损","中气下陷"],"a":0,"e":"湿疹日久，湿热化燥伤阴，肌肤失养而粗糙肥厚如苔藓，伴舌红少苔、脉细，属阴虚血燥。肝经湿热则见渗液糜烂、苔黄腻。"},{"q":"患者李某，平素大便干燥，状如羊屎，数日一行，伴见口干、口臭，舌红少津，苔黄燥，脉细涩。其辨证为","o":["肺阴虚证","阳明腑实证","肠燥津亏证","虫积肠道证","肺热炽盛证"],"a":2,"e":"大便干如羊屎、数日一行，兼口干口臭、舌红少津苔黄燥、脉细涩，为津液亏虚、肠道失润之肠燥津亏证。阳明腑实证必腹满硬痛、潮热谵语。"},{"q":"病人腹满而吐，食不下，自利，时腹自痛，脉缓弱，其证属","o":["太阴病证","阳明腑证","少阳病证","阳明经证","太阳腑证"],"a":0,"e":"腹满而吐、食不下、自利、时腹自痛、脉缓弱，为脾阳虚弱、寒湿内盛之太阴病证。阳明腑证为腹满硬痛、便秘、脉沉实。"},{"q":"患者，男，60岁。主诉眩晕，伴有头不自主摇动，言语謇涩，手足麻木，肢体震颤，步履不正，舌红，脉弦细。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","肝风内动证"],"a":4,"e":"头摇肢颤、言语謇涩、步履不正，为肝风内动之象；舌红脉弦细示阴血不足、筋脉失养。肝阳上亢以眩晕头胀、脉弦劲为主而无震颤。"},{"q":"男，25岁。感冒3天，今出现壮热，烦渴，咳嗽，痰黄稠量多，息促胸痛，小便短赤，舌红苔黄腻，脉滑数。属于","o":["热痰","燥痰","湿痰","风痰","寒痰"],"a":0,"e":"痰黄稠量多、面赤息促胸痛、舌红苔黄腻、脉滑数，为热邪煎熬津液成痰、痰热壅肺，属热痰。寒痰色白清稀，湿痰白滑易咯，燥痰少而黏难咯。"},{"q":"患者胸闷心悸，息促不得卧，身体、肢节疼重，咳吐清稀痰涎，喉间哮鸣有声，头目眩晕，舌苔白滑，脉弦。其临床意义是","o":["饮证","痰证","阴水证","阳水证","水停证"],"a":0,"e":"饮邪停聚、气机不利，故胸闷心悸、咳吐清稀痰涎、喉间哮鸣、苔白滑脉弦，属饮证。水停证以水肿尿少为主，痰证以痰稠苔腻为主。"},{"q":"汗出腥膻，不属于","o":["风温","风湿久蕴","汗后衣物不洁","瘟疫","湿温"],"a":3,"e":"汗气腥膻多见于风湿久蕴、湿温及汗后衣物不洁；瘟疫之汗气臭秽，故腥膻不属瘟疫。二者气味有别，不可混同。"},{"q":"患者出现舌质红绛，苔白滑腻，多属于","o":["邪热充斥，气营两燔","营分有热，气分有湿","热入营血，气阴俱伤","气阴两虚，痰湿内蕴","痰食停滞，郁久化热"],"a":1,"e":"舌绛主热入营血，苔白滑腻主气分痰湿未化，故为营分有热、气分有湿。若苔黄燥，则示气分热盛而津液已伤。"},{"q":"病人下午潮热、便秘、腹满而痛、脉沉实，其证属","o":["阳明腑证","阳明经证","太阳腑证","少阳腑证","少阳经证"],"a":0,"e":"下午潮热、便秘、腹满而痛、脉沉实，为燥屎内结、腑气不通之阳明腑证。阳明经证以身热汗出、烦渴、脉洪大为主而无便秘腹满。"},{"q":"患者腹痛，时作时止，多食易饥，面色萎黄而虚浮，下肢水肿，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":3,"e":"多食易饥而面色萎黄虚浮、下肢水肿，为钩虫吸食气血、脾虚湿盛之象。蛔虫以脐周痛、吐虫便虫为主，蛲虫以肛门瘙痒、夜间虫出为主。"},{"q":"久泄，畏寒肢冷，下腹冷痛，舌淡胖，苔白滑，脉沉细，宜诊断为","o":["寒湿困脾证","肾阳虚证","肾气不固证","脾肾阳虚证","脾阳虚证"],"a":3,"e":"久泄、畏寒肢冷、下腹冷痛、舌淡胖苔白滑、脉沉细，为脾肾阳气俱虚、温煦运化失职。单纯脾阳虚以食少腹胀、便溏为主而无腰膝冷痛。"},{"q":"患者出现恶寒发热，头痛，咳嗽，咽喉肿痛，大便溏泄，小便清长。证属","o":["上热下寒","真寒假热","表热里寒","表寒里热","真热假寒"],"a":2,"e":"恶寒发热、头痛咽痛为表热，大便溏泄、小便清长为里寒，故属表热里寒。真热假寒以胸腹灼热、脉沉实有力为特征。"},{"q":"患者早泄，耳鸣腰酸，烦热咽干，舌红少苔，宜诊断为","o":["肝肾阴虚证","心肾不交证","肾气不固证","肾精不足证","肾阴虚证"],"a":4,"e":"早泄、耳鸣腰酸、烦热咽干、舌红少苔，为肾阴不足、虚火扰动精室。肾气不固之早泄兼尿频遗尿、腰膝酸软而无虚热之象。"},{"q":"患者恶寒发热伴咳嗽3天，今起但发热不恶寒，咳嗽，痰多黄稠，面赤，舌红，脉滑数。从恶寒发热伴咳嗽3天，知其为新感，病在肺系；今发热不恶寒，面赤，舌红，脉滑数，知其表证已除，入里化热；同时痰多黄稠，脉滑数为痰热的表现，故本证为痰热壅肺。此例运用的中医诊断基本思维方法是","o":["类比法","分类法","归纳法","演绎法","反证法"],"a":3,"e":"由表证已除、邪入气分化热的一般原理，推出痰黄稠、脉滑数为痰热壅肺的具体结论，属从一般到个别的演绎法。归纳法为由个别事例概括一般结论。"},{"q":"患者，男，44岁。主诉睾丸冷痛，牵引少腹坠胀作痛，遇冷则阴器收缩引痛，得温痛减，平素畏寒喜暖，肢冷不温，舌淡苔白，脉弦紧。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","寒滞肝脉证"],"a":4,"e":"睾丸冷痛牵引少腹，遇冷加重、得温则减，兼畏寒肢冷、舌淡苔白、脉弦紧，为寒邪凝滞肝脉之寒滞肝脉证。肝胆湿热必阴囊潮湿、苔黄腻。"},{"q":"口出酸腐气，伴脘腹胀满者，多属","o":["龋齿","胃热","伤食","胃病","牙疳"],"a":2,"e":"口出酸腐臭气伴脘腹胀满，为宿食停滞、胃气上逆之伤食。胃热者口气臭秽兼口渴龈肿，龋齿与牙疳之口气多局限并伴齿病。"},{"q":"患者咽喉疼痛剧烈2日，伴有吞咽困难，检查见咽部及喉核红肿，压痛。伴见高热，口干喜饮，头痛，咳痰黄稠，大便秘结，小便黄，舌红苔黄，脉数有力。此病多辨证为","o":["肺肾阴虚","痰火壅结","肺胃热盛","痰湿凝聚","风热袭肺"],"a":2,"e":"咽喉红肿疼痛、吞咽困难，兼高热、口渴喜饮、便秘尿黄、舌红苔黄、脉数有力，为肺胃热盛、火毒上攻咽喉。风热袭肺多伴表证而热势较轻。"},{"q":"患者突发耳鸣耳痛，耳内流脓，脓出耳痛减缓。伴见口苦咽干，小便黄赤，大便秘结，舌红苔黄，脉弦数。多辨证为","o":["肝胆火旺","邪热外侵","脾虚湿困","肾精亏损","痰火壅结"],"a":0,"e":"突发耳鸣耳痛、耳内流脓而脓出痛减，兼口苦咽干、便结尿黄、脉弦数，为肝胆火旺循经上炎耳窍。脾虚湿困之脓液清稀、病程缠绵。"},{"q":"患者，女，7岁。因患感冒后突然症状加重，发热，头痛，神昏谵语，西医诊断为病毒性脑膜炎，指纹透关射甲，舌淡红，苔白，脉细则提示","o":["邪气入络","邪气入经","邪入脏腑，病情较重","病情凶险，预后不良","风寒表证"],"a":3,"e":"小儿指纹透关射甲，示邪气深入脏腑、病情危重，故提示病情凶险、预后不良。指纹仅透气关为邪入经，达命关则病深。"},{"q":"田某，女， 53岁，平素性情急躁易怒。自述近半个月来自觉口苦口干，烦躁失眠，胁痛灼热，小便短黄，大便干结，舌红苔黄，脉弦救。其口苦口干的病机为","o":["肝气郁结","肝胃不和","肝胆火旺","燥热伤津","肝胆湿热"],"a":2,"e":"平素急躁易怒，症见胁痛灼热、烦躁失眠、舌红苔黄、脉弦数，为肝郁化火、胆火内炽，灼伤津液故口苦口干。燥热伤津当见于燥邪或热病伤津。"},{"q":"病人咳嗽痰少，偶见痰中带血，腰膝酸软，遗精，五心烦热，盗汗颧红，舌红少苔，脉细数。宜辨证为","o":["肺阴亏虚证","肾阴虚证","肺肾气虚证","心阴虚证","肺肾阴虚证"],"a":4,"e":"咳嗽痰少带血属肺阴亏虚，腰膝酸软、遗精、盗汗颧红、舌红少苔、脉细数属肾阴亏虚，故为肺肾阴虚证。肺肾气虚以喘促气短、乏力为主。"},{"q":"患者，男，59岁。自述肠鸣腹泻2年。近1周来，站立行走或以手按抚，肠鸣辘辘下行，脘腹痞满，舌胖苔白腻，脉沉弦。属于","o":["胃肠虚寒","痰饮停胃","寒客胃肠","肝脾不调","肠道气滞"],"a":1,"e":"肠鸣辘辘、脘腹痞满、舌胖苔白腻、脉沉弦，为饮邪停聚胃中、气机不利之痰饮。胃肠虚寒以腹痛喜温喜按、便溏为主。"},{"q":"呵欠频频不止，多属","o":["肝气郁结","体虚阳衰","风寒外束","阳气回复","宗气大虚"],"a":1,"e":"呵欠频频不止而无外感他因，为阳气虚衰、气血不足之征。若病程中忽见呵欠，多为阳气渐复之佳兆。"},{"q":"患者素体痰盛，近来因情志不遂，出现头晕胀痛，面红目赤，口苦，耳内流脓，小便黄，大便不调，考虑为肝火夹痰，最可能出现的脉象是","o":["弦细涩脉","弦长细脉","弦滑数脉","弦紧实脉","弦细数脉"],"a":2,"e":"肝火夹痰，脉当弦以应肝、滑以主痰、数以主热，故为弦滑数脉。弦细涩主瘀血，弦紧主寒主痛，弦细数主阴虚火旺。"},{"q":"患者脘腹疼痛，肠鸣腹泻，呕吐，舌淡苔白，脉沉紧，宜诊断为","o":["风淫证","寒淫证","暑淫证","燥淫证","湿淫证"],"a":1,"e":"脘腹疼痛、肠鸣腹泻、呕吐、舌淡苔白、脉沉紧，为寒邪侵袭胃肠、阳气被遏、升降失常之寒淫证。湿淫以困重、苔腻为主。"},{"q":"患者胸胁胀闷疼痛，胸廓饱满，两肋叩击音实而浊，多为","o":["悬饮","支饮","痰饮","溢饮","水湿"],"a":0,"e":"饮停胸胁，故胸胁胀闷疼痛、胸廓饱满、叩之实浊，属悬饮。支饮在胸膈以咳逆倚息不得卧为主，痰饮在胃肠以肠鸣辘辘为主。"},{"q":"患者，女，32岁。外出旅游途中突发腹痛泄泻，大便呈水样，日泻5～6次，泻前肠鸣辘辘，伴见形寒肢冷，口淡不渴，脘腹痞闷，纳呆，四肢酸困重。经补液及抗菌治疗，未见明显改善，舌体胖，苔白腻，脉沉细。其泄泻的病机为","o":["食滞胃肠","脾肾阳虚","寒湿困脾","脾胃虚寒","寒邪犯胃"],"a":2,"e":"水样泻、肠鸣、形寒肢冷、口淡不渴、苔白腻、脉沉细，为寒湿内盛、困阻脾阳、运化失司。脾肾阳虚者当见腰膝冷痛、久泄不止。"},{"q":"语言粗鲁，狂妄叫骂，哭笑无常者属","o":["心气不足","心神大伤","痰浊闭窍","痰火扰心","痰蒙心神"],"a":3,"e":"语言粗鲁、狂妄叫骂、哭笑无常，为痰火扰乱心神、神志错乱之狂证，属痰火扰心。痰蒙心神以神识痴呆、表情淡漠为主。"},{"q":"若患者舌质红绛而有裂纹，舌苔焦黄干燥，其病多主","o":["痰热内蕴","热极津伤","阴虚内热","湿浊化热","痰湿内停"],"a":1,"e":"舌绛而有裂纹、苔焦黄干燥，为热邪亢盛、灼伤津液之象，主热极津伤。阴虚内热者舌红少苔或无苔，热势不如此炽盛。"},{"q":"突然昏倒，口眼歪斜，半身不遂，语言不利，面赤，脉弦劲有力，应辨证为","o":["肝阳上亢证","热极生风证","肝阳化风证","阴虚动风证","痰热扰心证"],"a":2,"e":"素体肝阳偏亢，阳亢化风，风阳上扰清窍，故猝然昏倒、口眼歪斜、半身不遂，脉弦劲有力。热极生风多见于高热抽搐。"},{"q":"患者突感左胸前区刺痛，痛引左上臂内侧，面色略黯，脉弦涩。证属","o":["气滞证","气逆证","气闭证","血瘀证","血热证"],"a":3,"e":"刺痛定处、痛引肩臂、面色黯、脉弦涩，为瘀血阻滞心脉、不通则痛。气滞以胀痛走窜为主，脉多弦而不涩。"},{"q":"患者鼻涕黄浊黏稠如脓样，量多，有臭味。兼见头痛，发热，口苦咽干，急躁易怒，舌红苔黄，脉弦数。多辨证为","o":["肺经风热","胆腑郁热","脾胃湿热","肺气虚弱","脾气虚弱"],"a":1,"e":"鼻涕黄浊如脓、量多臭秽，兼头痛发热、口苦咽干、急躁易怒、脉弦数，为胆腑郁热循经上蒸鼻窍之鼻渊。肺经风热多伴表证而涕清稀转黄。"},{"q":"干咳无痰或痰少而黏证属","o":["风热犯肺","燥邪犯肺","热邪犯肺","痰湿阻肺","肺气亏虚"],"a":1,"e":"干咳无痰或痰少而黏，为燥邪伤肺、肺津受灼、宣降失司。风热犯肺痰多黄稠，痰湿阻肺痰多易咯而苔腻。"},{"q":"患者头目胀痛，面红目赤，自觉气冲胸满，甚则呕逆吐血，宜诊断为","o":["喜伤证","怒伤证","思伤证","惊伤证","恐伤证"],"a":1,"e":"头目胀痛、面红目赤、气冲胸满，甚则呕逆吐血，为大怒伤肝、肝气上逆、血随气升之怒伤证。思伤证以纳呆消瘦、心悸健忘为主。"},{"q":"张某，女，63岁。两年来常感两目干涩不适，时痛时止，伴有口干夜甚，手足心热。查体：形体消瘦、两颧潮红，舌红少津，脉弦细数。该病人目涩的病机是","o":["肝经风热","肝血虚亏","肝阳上亢","肝火上炎","肝肾阴亏"],"a":4,"e":"两目干涩、口干夜甚、手足心热、颧红、舌红少津、脉弦细数，为肝肾阴液亏虚、目失濡养。肝火上炎必目赤肿痛、口苦、脉弦数。"},{"q":"患者因过服温燥药物所致火热耗津，舌象多为","o":["淡红舌","腻苔","腐苔","燥苔","润苔"],"a":3,"e":"过服温燥致热盛耗津，舌面津液亏乏，故苔干燥粗糙，即燥苔。腻苔主湿浊，腐苔主食积痰浊，润苔属津液未伤。"},{"q":"患者，女，36岁。因工作压力过大，不思饮食，胸脘痞闷，水声辘辘，纳呆，恶心，辨证为","o":["阴虚火旺证","水停证","痰证","饮证","血瘀证"],"a":3,"e":"胸脘痞闷、水声辘辘、纳呆恶心，为水饮停于胃肠、气机不利，属饮证。水停证以水肿、尿少、按之凹陷为主。"},{"q":"患者，女，35岁。症见恶寒，身热不扬，头重如裹，肢体困重，胸闷脘痞，口黏不渴，舌苔白腻，脉濡数，其辨证为","o":["湿热犯卫","暑湿犯卫","燥热犯肺","热郁胆经","风热犯卫"],"a":0,"e":"恶寒、身热不扬、头重如裹、肢体困重、口黏不渴、苔白腻、脉濡，为湿邪困阻卫表之湿热犯卫。暑湿犯卫多发于夏季，伴汗多、心烦。"},{"q":"患者，女，51岁。持续低热，暮热早凉，五心烦热，口干咽燥，舌干少苔，脉虚细，偶有手足蠕动，其辨证为","o":["血分虚热","血分实热","营阴受损","热入心包","热郁胆经"],"a":0,"e":"低热暮甚早凉、五心烦热、口干咽燥、舌干少苔、脉虚细，为热邪深入血分、耗伤阴血之血分虚热；手足蠕动为血虚生风之象。"},{"q":"患者手足疼痛发凉、肤色紫黯，得温痛减，喜暖恶寒，月经愆期，经色紫黯，脉沉迟而涩，诊断为","o":["血瘀证","血寒证","气滞血瘀证","血虚证","气虚证"],"a":1,"e":"手足疼痛发凉、肤色紫黯、得温痛减、经色紫黯、脉沉迟而涩，为寒客血脉、凝滞不通之血寒证。血瘀证以刺痛固定、舌紫斑为主而无明显寒象。"},{"q":"患者，女，70岁。精神萎靡，意识模糊，目暗睛迷，面色晦暗无华，表情淡漠，可判断病人为","o":["得神","少神","失神","假神","神乱"],"a":2,"e":"精神萎靡、意识模糊、目暗睛迷、面色晦暗、表情淡漠，为精气衰败之失神。假神则是久病重病忽见精神转佳，为阴阳离决之兆。"},{"q":"病人发热恶寒无汗、足冷、脉反沉，其证属","o":["少阴兼阳明病证","少阴兼太阳病证","少阳兼太阳病证","少阳病证","少阴病证"],"a":1,"e":"发热恶寒无汗、足冷、脉反沉，为太阳表证未解而少阴阳气已虚，属太少两感之少阴兼太阳病证。纯少阴病以身热不恶寒、脉微细但欲寐为主。"},{"q":"患者，女，49岁。壮热烦渴，头痛如劈，烦躁不安，肌肤发斑，吐血衄血，舌绛苔黄，其病变属于","o":["气分证","营分证","血分证","气血两燔","气营血同病"],"a":4,"e":"壮热烦渴属气分，肌肤发斑、吐衄属血分，舌绛属营血，三层同病故为气营血同病。气血两燔仅涉及气分与血分。"},{"q":"患者，女，40岁。1周前因情志不遂而出现胸胁胀痛，胃脘痞满，时欲太息，呃逆嗳气，纳食减少，舌苔薄白，脉弦。其脘痞的病机是","o":["肝气郁滞","肝火犯胃","寒凝胃脘","气滞胃脘","饮停胃脘"],"a":3,"e":"情志不遂致肝失疏泄，胃气壅滞、和降失职，故胃脘痞满、嗳气纳少、脉弦，其病机为气滞胃脘。寒凝胃脘当见冷痛喜温、苔白滑。"},{"q":"久病体虚之人出现嗳气的特点是","o":["嗳气频作兼见脘痛","嗳气频作声音响亮","嗳气低沉断续兼纳呆","嗳气酸腐兼脘胀","饱食之后偶尔嗳气"],"a":2,"e":"久病体虚之嗳气，因脾胃虚弱、气机上逆无力，故声低断续而兼纳呆。嗳气酸腐者属食滞，声响亮者多实热。"},{"q":"患者，女，79岁。卧床多年，本不能食，突然食欲大增，精神好转，想见亲人，病机为","o":["气血不足","阴阳失调","虚阳外越","脏腑虚弱","阳气亏虚"],"a":2,"e":"久病卧床之人本不能食，忽而食欲大增、精神转佳、欲见亲人，为精气衰竭、虚阳浮越外散之假神，属病情危重之兆。"},{"q":"患者突发颜面、眼睑浮肿，继而全身出现水肿，宜诊断为","o":["伤风","风疹","风中经络","风痹","风水"],"a":4,"e":"风邪袭表、肺失宣降、通调水道失职，水气泛溢肌肤，故起病急、先见面睑浮肿而后遍及全身，为风水。风疹以皮肤瘙痒、疹块为主而无水肿。"},{"q":"患者膝部关节肿大疼痛，股胫肌肉消瘦，步履艰难，舌淡苔白，脉沉称为","o":["“O”形腿","“X”形腿","膝内翻","膝外翻","鹤膝风"],"a":4,"e":"膝关节肿大疼痛而股胫肌肉消瘦，形如鹤膝，为鹤膝风，多因寒湿痰瘀痹阻、气血亏虚。膝内翻、膝外翻仅指下肢力线异常，无关节肿大。"},{"q":"患者，男，68岁。患者在外出时突然昏倒，不省人事，喉中痰鸣，口眼歪斜，半身不遂，舌红苔腻，脉弦有力。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","肝风内动证"],"a":4,"e":"猝然昏倒、不省人事、喉中痰鸣、口眼歪斜、半身不遂、脉弦有力，为肝阳化风、风痰上扰清窍之肝风内动证。肝阳上亢尚无神志昏愦、半身不遂。"},{"q":"患者情志抑郁，胸闷善太息，近来少腹及乳房胀痛，苔薄白，脉弦。证属","o":["气滞证","气逆证","气闭证","血瘀证","血热证"],"a":0,"e":"情志抑郁、善太息、少腹及乳房胀痛、脉弦，为肝失疏泄、气机郁滞，属气滞证。气逆证以咳喘、呕恶、头痛为主。"},{"q":"患者月经量少色淡，头晕眼花，夜寐不安，面色淡白无华，舌淡，脉弦细。证属","o":["气虚证","血虚证","血瘀证","阴虚证","血寒证"],"a":1,"e":"月经量少色淡、头晕眼花、夜寐不安、面色淡白无华、舌淡、脉细，为血液亏虚、机体失养之血虚证。气虚证以神疲乏力、气短自汗为主。"},{"q":"患者一侧面肌弛缓、额纹消失、眼不闭合、鼻唇沟平坦、口角下垂，四肢活动自如，多见于","o":["面瘫","中风病","痿病","截瘫","痉病"],"a":0,"e":"一侧面肌弛缓、额纹消失、眼睑不合、鼻唇沟平坦、口角下垂，而四肢活动自如，为风邪中络之面瘫。中风病多伴半身不遂、神志改变。"},{"q":"患者近3个月来因工作压力过大，出现心悸怔忡，心烦失眠，多梦，五心烦热，潮热盗汗，颧红，咽干，舌红苔少，最有可能出现的脉象是","o":["细数脉","浮数脉","细弱脉","沉紧脉","滑数脉"],"a":0,"e":"心悸失眠、五心烦热、潮热盗汗、颧红咽干、舌红苔少，为心阴亏虚、虚热内扰，脉当细而数。滑数主痰热，沉紧主寒主痛。"},{"q":"患者，男，80岁。胸胁饱满，胀痛，随呼吸、咳嗽、转身而疼痛加剧，辨证应属","o":["饮停胸胁","饮停于胃","饮停于肠","水饮凌心","痰湿阻肺"],"a":0,"e":"饮停胸胁、气机阻滞，故胸胁饱满胀痛，随呼吸、咳嗽、转侧牵引作痛，属悬饮。饮停于胃以脘痞、呕吐清水为主。"},{"q":"患者昨日眼睑边缘局部微有红肿痒痛，伴有头痛，发热，全身不适，舌苔薄白，脉浮数，宜诊断为","o":["风热外袭之针眼","风热邪毒之眼丹","热毒上攻之针眼","脾胃蕴热之眼丹","脾胃虚弱之针眼"],"a":0,"e":"眼睑边缘红肿痒痛初起，兼头痛发热、苔薄白、脉浮数，为风热外袭、客于胞睑之针眼初起。热毒上攻者硬结已成脓、全身热象更著。"},{"q":"患者，女，60岁。心前区疼痛10年余，每逢秋冬季节加重，今年入冬后感心前区刺痛，放射至左肩背部，伴心悸、胸闷，舌质紫黯，脉沉涩。其证候是","o":["痰阻心脉证","气滞血瘀证","气郁心脉证","瘀阻心脉证","寒凝心脉证"],"a":3,"e":"心前区刺痛、痛引肩背、舌质紫黯、脉沉涩，为瘀血阻滞心脉之瘀阻心脉证；遇寒加重示兼寒凝，然以瘀血征象为主。气滞血瘀当兼胀痛走窜。"},{"q":"患者，男，56岁。浮肿、腰痛2年。初为面肿，后下肢亦肿，近3个月来，水肿向全身发展，伴食少腹胀，腰膝酸软，畏寒肢冷，小便短少，神疲乏力，舌质淡白，苔黑而滑，脉沉细无力。其腰痛的病机是","o":["寒湿痹病","肾阳亏虚","瘀血阻络","经络阻滞","带脉损伤"],"a":1,"e":"水肿日久、腰膝酸软、畏寒肢冷、小便短少、神疲乏力、苔黑而滑、脉沉细无力，为肾阳亏虚、气化不行、腰府失养。寒湿痹病以关节冷痛为主。"},{"q":"患者脐周腹痛，时作时止，腹部可触及条索状虫团，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":0,"e":"脐周腹痛、时作时止，腹部可扪及条索状虫团，为蛔虫结聚肠道之肠道蛔虫病。蛔厥以剧痛肢厥为主，胆道蛔虫痛在右上腹呈钻顶样。"},{"q":"患者左少腹作痛，按之累累有硬块者，应考虑","o":["肠痈","虫积","宿粪","疝气","瘕聚"],"a":2,"e":"左少腹按之累累有硬块，推之可移而痛不显，为燥屎内结之宿粪。肠痈以右下腹压痛、反跳痛为主，瘕聚则包块聚散无常。"},{"q":"患者，女，27岁。平素嗜食生冷食物，反复脘腹痞闷半月余，食少便溏，口腻纳呆，头身困重，舌淡胖苔白腻，脉濡缓。诊为","o":["湿热蕴脾证","寒湿困脾证","脾气虚证","寒滞胃脘证","脾阳虚证"],"a":1,"e":"嗜食生冷，寒湿内生，困阻脾阳，运化失司，故脘腹痞闷、食少便溏、口腻、头身困重、苔白腻、脉濡缓。湿热蕴脾当见口苦、苔黄腻。"},{"q":"患者脘腹冷痛，泛吐清涎，小便短黄，舌质红苔薄黄，脉沉弦。证属","o":["上热下寒证","真热假寒证","真寒假热证","表里实寒证","上寒下热证"],"a":4,"e":"脘腹冷痛、泛吐清涎属上寒，小便短黄、舌红苔薄黄属下热，寒热分居上下，故为上寒下热证。真热假寒以胸腹灼热、脉沉实为特征。"},{"q":"泄泻半年余，伴有面白无华，形寒肢冷，腰膝及下腹冷痛，舌淡胖，苔白滑，脉沉细。应诊断为","o":["肾阳虚证","脾阳虚证","肾气不固证","脾肾阳虚证","寒湿困脾证"],"a":3,"e":"久泄不止，兼形寒肢冷、腰膝及下腹冷痛、舌淡胖苔白滑、脉沉细，为脾肾阳气俱衰、温运失职。单纯肾阳虚以腰膝冷痛、五更泻为主。"},{"q":"患者鼻塞清涕1日，鼻塞严重无法呼吸，喷嚏频作，流涕量多而清稀，头痛，恶寒，发热轻，舌淡，苔薄白，脉浮紧。最宜诊断为","o":["外感风寒","外感风热","肺气虚寒","肺胃郁热","寒痰阻肺"],"a":0,"e":"鼻塞、喷嚏、流清稀涕量多，兼头痛恶寒、发热轻、苔薄白、脉浮紧，为风寒袭表、肺窍不利之外感风寒。肺气虚寒者病程久、遇寒易发而无表证。"},{"q":"患者，女。近2个月来经常咳血，潮热骨蒸，盗汗音哑，喘息气短，形寒肢冷，恶风自汗，食少便溏，舌淡红有裂纹少津，脉沉细。证属","o":["阳虚证","阴虚证","阴阳两虚证","真实假虚证","真虚假实证"],"a":2,"e":"咳血潮热、盗汗音哑属阴虚，形寒肢冷、自汗便溏属阳虚，阴阳俱损故为阴阳两虚证。单纯阴虚无肢冷便溏，单纯阳虚无潮热盗汗。"},{"q":"患者身热不扬，倦怠懒言，便溏不爽，舌红苔黄腻，脉沉滑，证属","o":["真实假虚","虚实夹杂","真虚假实","表虚里实","表实里虚"],"a":1,"e":"身热不扬、便溏不爽、苔黄腻为湿热内蕴之实，倦怠懒言、脉沉滑示正气不足，虚实并见故属虚实夹杂。真实假虚者脉当沉实有力。"},{"q":"患者，女，68岁。素有头晕、头痛反复发作已历3年，刻下头部右侧后痛如锥刺，伴失眠，心悸，记忆力下降。此属下列何证","o":["心阳虚证","痰火扰心证","瘀阻脑络证","胆郁痰扰证","痰蒙心神证"],"a":2,"e":"头痛如锥刺、固定不移，为瘀血阻滞脑络之征；久病入络，瘀阻脑窍故失眠健忘、心悸。痰火扰心以烦躁、苔黄腻、脉滑数为主。"},{"q":"患者右胁下肿块，质地坚硬，按之表面凹凸不平，应考虑","o":["气滞","肝癌","血瘀","肝虚","肝痈"],"a":1,"e":"右胁下肿块坚硬、表面凹凸不平，为瘀毒互结、癥积已成，多见于肝癌。肝痈以右胁痛、发热、拒按为主，脓成则有波动感。"},{"q":"患者，女，45岁。胃脘嘈杂，时作腹痛2个月余，腹痛以脐周为甚，伴面黄体痩，面部出现白斑，大便排虫，舌淡苔薄白，脉弦细。辨证为","o":["胃气虚证","脾气虚证","肠热腑实证","大肠湿热证","虫积肠道证"],"a":4,"e":"腹痛绕脐、面黄体瘦、面部白斑、大便排虫，为虫寄肠道、耗伤气血之虫积肠道证。大肠湿热以腹痛下痢脓血、肛门灼热为主。"},{"q":"带下清稀，伴腥臭者，多属","o":["湿热","寒湿","癌病","湿毒","血瘀"],"a":1,"e":"带下色白清稀、气味腥臭属寒湿下注，因寒性收引、湿性趋下，津液不化而清冷；湿热则带下色黄黏稠、臭秽。"},{"q":"患者，女，22岁。发热恶寒，汗出，口渴头痛，舌红苔黄，尿赤，脉滑数，属于","o":["卫分证","卫气同病","气分证","气营同病","气营两燔"],"a":1,"e":"既有发热恶寒、头痛之卫分表证，又见汗出、口渴、尿赤、舌红苔黄、脉滑数之气分里热，表里俱热故为卫气同病。"},{"q":"患者，男，25岁。腹痛、腹泻2日，一日数次，泻下物色黄味臭，伴肛门灼热，小便黄，舌红苔黄腻，脉滑数。最宜辨证为","o":["大肠湿热证","肠热腑实证","下焦湿热证","虫积肠道证","食积肠道证"],"a":0,"e":"泻下色黄味臭、肛门灼热、小便黄、舌红苔黄腻、脉滑数，为湿热蕴结大肠、传导失职，故属大肠湿热证。"},{"q":"患者，女，21岁，学生。2005年7月14日初诊。胃脘胀痛5年，加重伴恶心3天。初诊：患者因住校就餐，饥饱不均，出现胃脘胀痛，在本地医院经胃镜检查诊断为慢性胃炎，用药不详，疗效不明显……病案中的“胃脘胀痛5年，加重3天，伴恶心”是","o":["主症","主诉","主证","主病","现在症状"],"a":1,"e":"主诉是患者就诊时最感痛苦的症状及其持续时间，须简明扼要、一语中的，胃脘胀痛5年、加重3天正合此要求。"},{"q":"患者，男，55岁。近半年来多食易饥，口渴多饮，小便量多，体重下降，日渐消瘦，伴见疲乏，动辄汗出，舌淡泛青，隐现瘀斑，苔薄白，脉虚细涩。中医诊断为","o":["燥热伤津","里热炽盛","痰火内扰","消渴病","瘀热互结"],"a":3,"e":"多食易饥、口渴多饮、尿多而消瘦为消渴病典型表现，由阴虚燥热、津液耗损所致；疲乏汗出、舌青瘀斑属气阴两伤兼瘀。"},{"q":"患者，男，63岁。病发时狂躁妄动，胡言乱语，少寐多梦，打骂他人，不避亲疏，见于","o":["癫病","狂病","痫病","中风","郁病"],"a":1,"e":"狂病以躁狂妄动、打骂毁物、不避亲疏、登高而歌为特征，因痰火扰神、神明逆乱所致；癫病则沉默痴呆、语无伦次。"},{"q":"顿咳最常见于","o":["小儿","老年人","青年人","男性","女性"],"a":0,"e":"顿咳即百日咳，以阵发性痉挛性咳嗽、咳后有鸡啼样回声为特征，为小儿常见传染病，多见于五岁以下小儿。"},{"q":"患者，女，15岁。2天前吃路边烧烤后出现腹痛腹泻，每日大便10余次，有黏冻脓血，伴发热，里急后重，口干饮水不多，腹软，左下腹压痛，舌红苔黄，脉濡数。其病证机理为","o":["食滞胃肠","脾胃虚弱","寒湿困脾","大肠湿热","寒滞胃肠"],"a":3,"e":"腹痛腹泻、黏冻脓血、里急后重、肛门灼热、舌红苔黄、脉濡数，为湿热蕴结大肠、气血壅滞，故机理属大肠湿热。"},{"q":"患者，男，10岁。3日前开始发热，体温持续38～39℃不退，就诊前突然出现四肢抽搐，颈项强直，角弓反张，神昏谵语，舌质红绛，苔黄燥，脉弦数。辨证属","o":["肝阳化风证","热极生风证","肝胆湿热证","肝阴虚证","阴虚动风正"],"a":1,"e":"高热不退继而四肢抽搐、颈项强直、角弓反张、神昏，为邪热炽盛、燔灼肝经、引动肝风，属热极生风证。"},{"q":"胸胁胀闷，善太息，脘部胀痛，苔薄白，脉弦。宜诊断为","o":["胃肠气滞证","肝气郁滞证","肝火犯胃证","饮停胸胁证","肝胃不和证"],"a":4,"e":"胸胁胀闷、善太息为肝气郁结，脘部胀痛、脉弦为肝气犯胃、胃失和降，肝胃同病故诊为肝胃不和证。"},{"q":"患者，女，40岁。近半年来经常腰膝酸痛，头晕耳鸣，月经量少，口燥咽干，潮热盗汗，舌红少津，脉细数。其腰痛的病机是","o":["寒湿阻滞","肾阳亏虚","肾精亏虚","肾阴亏虚","带脉损伤"],"a":3,"e":"腰膝酸痛兼头晕耳鸣、月经量少、口燥咽干、潮热盗汗、舌红少津、脉细数，为肾阴不足、腰府失养，病机属肾阴亏虚。"},{"q":"患者，男，55岁。头痛、眩晕2年余，未系统治疗，近2周症状加重，现症见眩晕耳鸣，头目胀痛，急躁易怒，腰膝酸软，头重脚轻，舌质红，脉弦细数。其头痛的病机是","o":["肝风内动","肝火上炎","肝肾阴亏","肝阳上亢","肝胆湿热"],"a":3,"e":"眩晕耳鸣、头目胀痛、急躁易怒、面红目赤属肝阳亢逆，腰膝酸软、头重脚轻、脉弦细数为下虚上实，故为肝阳上亢。"},{"q":"患者，女，56岁。头晕、头痛反复发作已历1年，痛发则如锥刺难忍、痛处多在左侧，近半年来易健忘，时有失眠、心悸。刻下：面色晦暗，舌质紫黯或有斑点，脉细涩。此属下列何证","o":["心脉痹阻证","痰火扰神证","心火亢盛证","瘀阻脑络证","肝阳化风证"],"a":3,"e":"头痛如锥刺、痛处固定、面色晦暗、舌紫黯有斑点、脉细涩，为瘀血阻滞脑络、不通则痛，故属瘀阻脑络证。"},{"q":"患者平素食少纳呆，腹胀便溏，近日心悸怔忡，头晕健忘，神疲乏力，月经淋漓不断，色淡量少，舌淡嫩，脉细弱。辨证为","o":["脾气虚证","心血虚证","脾不统血证","心脾两虚证","脾虚气陷证"],"a":3,"e":"食少纳呆、腹胀便溏为脾气虚，心悸怔忡、头晕健忘、失眠为心血虚，心脾两脏证候并见，故为心脾两虚证。"},{"q":"患者平素月经过多，面色无华，神疲乏力，心悸失眠，舌淡，脉弱无力","o":["气虚血瘀证","气滞血瘀证","气血两虚证","气不摄血证","气随血脱证"],"a":3,"e":"月经过多而色淡，兼面色无华、神疲乏力、心悸失眠、舌淡脉弱，为脾气虚损、统摄无权、血溢脉外，属气不摄血证。"},{"q":"患者，女，27岁，干部。2016年3月11日初诊。胃脘胀痛3年，加重4天，伴恶心、呕吐。初诊：患者因饮食不调，出现胃脘胀痛，在本地医院经胃镜检查诊断为慢性胃炎，用药不详，疗效不明显。近4天来胃脘胀痛，饥饿时明显，伴恶心、呃逆、呕吐，无反酸，腹胀，头晕，纳呆，二便调，睡眠佳。2007年做胃镜检查报告：慢性浅表性胃炎，反流性食管炎，Hp(-)。舌质淡红，苔薄白，脉平缓……病案中的“2007年做胃镜检查报告：慢性浅表性胃炎，反流性食管炎，Hp(-)”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":3,"e":"既往史指患者平素健康状况及过去所患疾病，包括既往检查结果，故2007年胃镜报告慢性浅表性胃炎、反流性食管炎属既往史。"},{"q":"男，36岁。患胃病10年，近1周来干呕时作，口渴心烦，胃脘隐痛，知饥而不欲饮食，便结溲黄，舌红少苔，脉弦细偏数。属于","o":["食滞胃脘","胃火炽盛","胃阴亏虚","肝气犯胃","脾胃虚弱"],"a":2,"e":"胃脘隐痛、知饥不欲食、干呕、口渴心烦、便结、舌红少苔、脉细数，为胃阴不足、胃失濡润和降，属胃阴亏虚。"},{"q":"患者，女，40岁。半年来时感入睡困难，心急易怒，伴头晕耳鸣，五心烦热，潮热盗汗，腰膝酸软，舌红少苔，脉细数。其失眠的病机为","o":["肝肾阴虚","心脾两虚","心肾不交","胆郁痰扰","肝火上炎"],"a":2,"e":"心烦失眠兼腰膝酸软、五心烦热、潮热盗汗、舌红少苔、脉细数，为肾阴亏虚、不能上济心火、心火偏亢，属心肾不交。"},{"q":"患者，男，28岁。身热不扬，头身重痛，胸脘痞闷，恶心欲吐，舌红苔黄腻，脉濡数，应属","o":["上焦病","太阴湿热证","燥热内结证","下焦病","大肠湿热证"],"a":1,"e":"身热不扬、头身重痛、胸脘痞闷、恶心欲吐、苔黄腻、脉濡数，为湿遏热伏、困阻中焦脾胃，属太阴湿热证。"},{"q":"患者，男，32岁。患肺结核多年，形体消瘦，2天前因受凉后感冒，咳嗽，痰少，恶寒，发热，脉浮数。证属阴虚火旺，复感风寒之邪。可见到的舌象是","o":["红绛舌，黄燥苔","红瘦舌，薄白苔","绛舌，黄白苔","红舌，苍老滑苔","淡白舌，黄裂苔"],"a":1,"e":"肺阴亏虚则舌体瘦薄而色红；新感风寒之邪尚在卫表，未及入里化热，苔仍薄白，故见红瘦舌、薄白苔。"},{"q":"患者前胸高突，叩之膨膨然有如鼓音，多为","o":["肺痨","肺痿","肺痈","肺胀","肺热"],"a":3,"e":"前胸高突、叩之膨膨然如鼓音，为胸廓胀满、肺气壅塞之征，因久病咳喘、痰浊壅肺而发为肺胀。"},{"q":"患者，男，48岁。患胃病若干年，近半月病情加重，出现胃脘胀痛，腹胀疼痛，部位走窜不定，按诊检查腹部较软，左侧腹部有一肿块，质地柔软，表面光滑，按之可移，舌淡红，苔白，脉弦，属于","o":["痰凝","血瘀","积饮","气滞","伤食"],"a":3,"e":"胀痛走窜不定、按之腹软、肿块质软光滑推之可移，为气机郁滞、聚散无常，故属气滞；血瘀则痛有定处、质硬不移。"},{"q":"患者，女，20岁，大学生。半年前正值经期第3天，参加院篮球比赛，之后月经量突然增多，且持续10余日方止。此后，每月月经均量多，时间长，经色淡红，并伴有神疲，倦怠乏力，食少便溏，面白无华，舌淡苔白，脉细无力。其月经过多的病机为","o":["气虚冲任不固","血热迫血妄行","瘀阻冲任，血不归经","肝郁脾虚失固","脾肾阳虚不固"],"a":0,"e":"经量多、经期长而色淡，伴神疲乏力、食少便溏、面白无华、舌淡苔白、脉细无力，为脾气虚衰、冲任不固、血失统摄。"},{"q":"病人身大热，汗大出，口大渴，面赤，气粗似喘，心烦躁扰，舌苔黄燥，脉洪大，其证属","o":["阳明腑证","阳明经证","太阳腑证","少阳腑证","少阳经证"],"a":1,"e":"大热、大汗、大渴、面赤气粗、心烦、脉洪大，为阳明气分热盛、邪热弥漫，属阳明经证；腑证当见腹满便秘。"},{"q":"患者近日来饮食不节，出现胃脘胀痛，嗳气，食滞胃脘，其脉多为","o":["弦脉","滑脉","数脉","缓脉","濡脉"],"a":1,"e":"食滞胃脘者宿食内停、胃气壅盛，脉气鼓动有力而血行流畅，故脉多滑；食积化热者可兼见数象。"},{"q":"患者，20岁。初起恶寒发热，咽喉疼痛，继之眼睑头面浮肿，小便量少的临床意义是","o":["痰饮","悬饮","支饮","阳水","阴水"],"a":3,"e":"外感风邪、肺失宣降，起病急而见眼睑头面先肿、小便量少，属阳水；阴水则病久缠绵、下肢先肿。"},{"q":"患者两眦赤脉粗大鲜红，痒涩刺痛，头痛烦热，口干咽燥，或口舌生疮，大便燥结，小便黄赤，舌尖红，舌苔黄，脉数。此病最宜诊断为","o":["肝火上炎","肺经风热","心火上炎","胃火炽盛","肝经风热"],"a":2,"e":"两眦属心，赤脉粗大鲜红、痒涩刺痛，兼口舌生疮、舌尖红、脉数，为心火亢盛、上炎于目眦。"},{"q":"患者牙龈红肿，出血，出脓，口臭，烦渴多饮，大便秘结，舌红，苔黄厚，脉滑数。此病最宜诊断为","o":["肺热炽盛","肾阴亏损","胃火亢盛","心脾积热","心火上炎"],"a":2,"e":"齿龈属胃，牙龈红肿出血出脓、口臭、烦渴多饮、大便秘结、苔黄厚、脉滑数，为胃火炽盛、循经上炎。"},{"q":"患者，男，50岁。大便3日未解，腹部硬满疼痛、拒按，舌红苔黄燥，脉沉数有力，辨为肠热腑实证。其可导致的神志异常为","o":["闷闷不乐","突然昏仆","哭笑无常","神昏谵语","神昏郑声"],"a":3,"e":"肠热腑实、燥屎内结，浊热上扰心神，故见神昏谵语；郑声为虚证气衰之言，与实证谵语不同。"},{"q":"患者，女，32岁。因1年前考公务员意外落选，一直郁郁寡欢，表情淡漠，神志痴呆，喃喃自语，哭笑无常，悲观失望，舌红，苔白，脉弦，其病机是","o":["气郁化火，痰火扰心","阳明热盛，扰乱神明","肝风夹痰，蒙蔽心神","痰迷心窍","温病邪热入于心包"],"a":3,"e":"情志抑郁日久，气机不畅、津凝为痰，痰浊蒙蔽心窍，故表情淡漠、神志痴呆、喃喃自语、哭笑无常。"},{"q":"患者胸闷脘痞，纳呆呕吐，肠鸣腹泻，舌淡胖苔白腻，脉濡缓，宜诊断为","o":["风淫证","寒淫证","暑淫证","湿淫证","火淫证"],"a":3,"e":"胸闷脘痞、纳呆呕吐、肠鸣腹泻、舌淡胖苔白腻、脉濡缓，为湿邪黏滞重浊、困阻中焦、脾失健运，属湿淫证。"},{"q":"患者发热，午后热甚，身热不扬，属于","o":["骨蒸劳热","湿温潮热","阴虚内热","阳明潮热","气虚发热"],"a":1,"e":"午后热甚而身热不扬，为湿遏热伏、热难透达之象，属湿温潮热；阴虚潮热则五心烦热、骨蒸盗汗。"},{"q":"患者，男，52岁。病人1年前在疲劳后出现心悸、胸闷气短，未经诊治，近两个月上症明显加重。现症见胸闷，心悸，气短，时有胸痛，畏寒肢冷，面色淡白，舌淡苔白滑，脉弱。其胸闷的病机是","o":["痰湿内阻","心阳亏虚","阳气暴脱","心血瘀阻","心气亏虚"],"a":1,"e":"胸闷心悸、气短，兼畏寒肢冷、面色淡白、舌淡苔白滑、脉弱，为心阳不足、温煦失职、胸阳不振。"},{"q":"患者，男，65岁。长期腰膝酸冷，泄泻日久，完谷不化，便质清冷，面色㿠白，舌淡胖，苔白滑，最有可能出现的脉象是","o":["细数无力","洪大","弦数","沉迟无力","浮大无根"],"a":3,"e":"腰膝酸冷、久泻完谷不化、便质清冷、面色淡白、舌淡胖苔白滑，为脾肾阳虚、阴寒内盛，脉当沉迟无力。"},{"q":"下列不属于实喘特征的是","o":["发作急骤","息粗声高","动则喘甚","呼吸深长","以呼出为快"],"a":2,"e":"实喘发作急骤、息粗声高、呼吸深长、以呼出为快；动则喘甚属虚喘，为肺肾气虚、摄纳无权。"},{"q":"患者，女，52岁。主诉咽部异物感，似有痰，咳之不出，咽之不下，伴有月经不调，痛经，舌苔薄白，脉弦，辨证属","o":["肝血虚证","肝郁气滞证","肝胆湿热证","热极生风证","胆郁痰扰证"],"a":1,"e":"咽中如有物梗、咯之不出咽之不下，即梅核气，由情志不遂、肝气郁结、气滞痰凝所致，兼月经不调、脉弦可征。"},{"q":"似喘不抬肩，喉中无痰鸣者称","o":["哮证","上气","短气","热咳","少气"],"a":2,"e":"短气指呼吸短促急迫、似喘而不抬肩、喉中无痰鸣，多因肺气不足或水饮停聚、气机升降不利所致。"},{"q":"患者，男，37岁。身体灼热，神昏谵语，四肢抽搐，角弓反张，其病变属于","o":["气分证","卫气同病","营分证","血分证","气血两燔"],"a":3,"e":"身灼热、神昏谵语、四肢抽搐、角弓反张、舌绛，为热入血分、动血动风、扰乱神明，属血分证。"},{"q":"患者下肢水肿，面白神疲，腰膝酸冷，舌淡苔白滑，脉沉迟无力，宜诊断为","o":["肾虚水泛证","肾阳虚证","肾不纳气证","肾阴虚证","心阳虚证"],"a":0,"e":"下肢水肿兼面白神疲、腰膝酸冷、舌淡苔白滑、脉沉迟无力，为肾阳衰微、气化不行、水湿泛滥，属肾虚水泛证。"},{"q":"患者，男，50岁。服用抗结核药1年余，现干咳，痰少带血丝，消瘦，五心烦热，盗汗，舌红少苔，脉细数。辨证为","o":["燥邪犯肺证","肝肾阴虚证","肺阴虚证","肺热炽盛证","风热犯肺证"],"a":2,"e":"干咳痰少带血丝、消瘦、五心烦热、盗汗、舌红少苔、脉细数，为肺阴亏虚、虚热内生、肺失清润。"},{"q":"患者身目发黄，黄色鲜明，腹部痞满，肢体困重，便溏尿黄，身热不扬，舌红苔黄腻，脉濡数。其证候是","o":["肝胆湿热","大肠湿热","肝火上炎","湿热蕴脾","寒湿困脾"],"a":3,"e":"身目鲜黄、腹部痞满、肢体困重、便溏尿黄、身热不扬、苔黄腻、脉濡数，为湿热内蕴脾胃、熏蒸肝胆。"},{"q":"患者，女，17岁。因高考将至，过度紧张，而致心情烦躁，入夜难眠，口干多饮，舌红苔黄干，脉数。其证候是","o":["心阴虚证","肝阴虚证","心血虚证","心火上亢证","肝火上炎证"],"a":3,"e":"心情烦躁、入夜难眠、口干多饮、舌红苔黄干、脉数，为心火偏亢、内扰心神、灼伤津液，属心火上亢证。"},{"q":"患者，男，42岁。小便混浊如米泔2个月余，自觉脘腹重坠作胀，食后尤甚，神疲乏力，肢体倦怠，声低懒言，头晕目眩，舌淡苔白，脉弱。诊为","o":["脾气虚证","脾阳虚证","脾虚气陷证","脾不统血证","寒湿困脾证"],"a":2,"e":"小便混浊如米泔兼脘腹重坠、食后尤甚、神疲气短、脉弱，为脾气亏虚、清阳不升、固摄无权，属脾虚气陷证。"},{"q":"患者腹痛腹泻，恶心呕吐，纳呆食少，夜间肛门瘙痒，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":4,"e":"夜间肛门瘙痒为蛲虫夜间爬出肛门外产卵所致，虫扰肠道气机则腹痛腹泻、纳呆食少，故考虑蛲虫病。"},{"q":"患者，女，58岁。近半月来记忆力下降明显，自觉夜间眠浅梦多，白天头晕眼花，时有心悸。刻下：面色淡白、饮食一般，大便偏干，小便正常，唇、舌色淡，脉细弱。此属下列何证","o":["心阴虚证","心血虚证","心气虚证","心阳虚证","瘀阻脑络证"],"a":1,"e":"面色淡白、唇舌色淡、脉细弱，兼心悸失眠、头晕眼花、健忘，为心血不足、心神失养，属心血虚证。"},{"q":"患者全身水肿，腰以下肿甚，腰膝酸冷，心悸气短，喉中痰鸣，小便短少，舌淡胖，苔白滑，脉沉涩无力，应诊断为","o":["肾阳虚","心阳虚","肺肾气虚证","肾虚水泛证","脾肾阳虚证"],"a":3,"e":"全身水肿以腰以下为甚、腰膝酸冷、小便短少、心悸气短、舌淡胖苔白滑、脉沉涩，为肾阳虚衰、水湿泛滥。"},{"q":"患者，男，48岁。反复泄泻1个月余，自觉便意频数，肛门重坠，脘腹重坠作胀，食后尤甚，少气懒言，面色萎黄，形体消瘦，舌淡苔白，脉弱。可诊断为","o":["湿热蕴脾证","脾虚气陷证","胃阴虚证","寒滞胃脘证","胃肠气滞证"],"a":1,"e":"便意频数、肛门重坠、脘腹坠胀、食后尤甚、少气懒言、脉弱，为脾气虚衰、升举无力、清阳不升。"},{"q":"患者，女，55岁。发热3周，午后及夜间热甚，伴见颧红盗汗，舌红少苔，脉细数，其发热类型属于","o":["湿温潮热","阴虚潮热","阳明潮热","气郁发热","气虚发热"],"a":1,"e":"午后及夜间热甚、颧红盗汗、五心烦热、舌红少苔、脉细数，为阴液亏虚、虚热内生，属阴虚潮热。"},{"q":"患者，男，35岁。平素喜冷饮，夏夜在家中空调下睡觉，入睡时腹部未盖衣被，第二天晨起时见：胃脘冷痛，痛势急剧，恶心，纳差，舌淡苔白润，脉弦紧。诊为","o":["胃气虚证","胃阳虚证","寒滞胃脘证","胃阴虚证","食滞胃脘证"],"a":2,"e":"胃脘冷痛、痛势急剧、遇寒而发、舌淡苔白润、脉弦紧，为寒邪直中胃脘、凝滞气机，属寒滞胃脘证。"},{"q":"患者，男，52岁。嗜食肥甘厚味，平素爱逸少动，形体肥胖，2周前出现头重眩晕，胸脘痞闷，食欲欠佳，其舌苔可见","o":["黄燥","黄滑","薄白","淡黄","白腻"],"a":4,"e":"嗜食肥甘、形体肥胖、头重眩晕、胸脘痞闷、食欲欠佳，为痰湿内蕴，苔当白腻；黄苔主热，与寒湿痰浊不符。"},{"q":"患者，男，74岁。由于邪气亢盛，热扰神明，邪陷心包而出现失神，最可能表现为","o":["反应迟钝","手撒遗尿","骨枯肉脱","形体瘦弱","牙关紧急"],"a":4,"e":"邪盛神乱之失神，见壮热烦躁、神昏谵语、循衣摸床、两手握固、牙关紧急，为邪陷心包、热扰神明。"},{"q":"本已神志不清、不得言语的患者突然神志清醒，语言不休者属","o":["神志异常","无神","假神","有神","神气不足"],"a":2,"e":"久病重病本已神昏不语，忽而神志清醒、言语不休、声高气粗，为精气衰竭、虚阳外越之假神，属危重之兆。"},{"q":"患者，女，32岁。平素嗜食辛辣，反复胃脘灼痛3个月余，渴喜冷饮，消谷善饥，大便秘结，小便短赤，舌红苔黄，脉滑数。诊为","o":["胃热炽盛证","寒滞胃脘证","肠燥津亏证","胃阴虚证","食滞胃脘证"],"a":0,"e":"胃脘灼痛、渴喜冷饮、消谷善饥、大便秘结、小便短赤、舌红苔黄、脉滑数，为胃火炽盛、腐熟太过、灼伤津液。"},{"q":"患者，男。1年前中风后左半身上下肢运动不便。现大便秘结，三日一行，临而努挣乏力，挣则汗出气短，便后疲乏，舌淡脉虚无力。证属","o":["表证","热证","亡阳证","虚证","寒证"],"a":3,"e":"临厕努挣乏力、挣则汗出气短、便后疲乏、舌淡脉虚无力，为气虚推动无力之便秘，属虚证而非实证。"},{"q":"患者2个月来时常发热，波动于37、3～38℃，午后发作，劳累后加重，少气懒言，常自汗出，易感冒，舌质淡白，苔薄白，脉弱。证属","o":["表证、热证、虚证","里证、热证、虚证","表证、寒证、虚证","里证、寒证、虚证","里证、热证、实证"],"a":1,"e":"发热午后为甚、劳累加重、自汗易感、少气懒言、舌淡脉弱，病位在里、性属热而正气亏虚，故为里证、热证、虚证。"},{"q":"患儿，男，2岁1个月。望诊眉间、鼻柱、唇周发青，辨证为","o":["阴虚","惊风","血瘀","肾虚","阳虚"],"a":1,"e":"眉间、鼻柱、唇周发青，为小儿惊风之先兆，因肝风内动、气血郁滞、筋脉拘急，青色见于风动之处。"},{"q":"患者，男，67岁。身热不甚，口干咽燥，神倦耳聋，手足心热甚于手足背，舌绛干燥，其病机为","o":["肺胃阴伤","阴虚火炽","热伤心肾","燥干清窍","肾阴耗损"],"a":4,"e":"温病后期身热不甚、口干咽燥、神倦耳聋、手足心热甚于手足背、舌绛干燥，为邪热久羁、真阴耗损，病在下焦肝肾。"},{"q":"患者发热，其手心热甚于额上，多为","o":["表热","里热","实热","虚热","郁热"],"a":1,"e":"手心热甚于额上者为里热，为热在脏腑、由内蒸腾于外之象；额上热甚于手心者则属表热。"},{"q":"患者平素性急易怒，时有胁胀，近日胁胀加重，伴食欲不振，食后腹胀，便溏，舌淡苔薄白，脉弦。其证候是","o":["脾气虚","脾阳虚","脾肾阳虚","肝脾不调","肝胃不和"],"a":3,"e":"胁胀、善怒、脉弦为肝气郁滞，纳呆腹胀、便溏为脾气虚弱，肝木乘脾、脾失健运，故为肝脾不调。"},{"q":"患者平素畏寒肢冷，腹痛喜温喜按，小便清长，今起恶寒重发热轻，头痛无汗，流清涕，舌淡胖，脉濡缓，是","o":["表实寒里虚热","表实热里虚寒","表实寒里虚寒","表实热里虚热","表实里实寒证"],"a":2,"e":"新起恶寒重发热轻、头痛无汗、流清涕，为表实寒证；平素畏寒肢冷、腹痛喜温喜按、小便清长，为里虚寒证。"},{"q":"患者，女，23岁。心烦失眠1个月。患者因最近与同事发生矛盾，心情烦躁，入夜难以入睡，自觉手足心发热，口干欲饮，但所饮不多，舌红苔薄而干，脉细数。其证候是","o":["心阴虚证","肝阴虚证","心火上炎证","肝火上炎证","肝气郁结证"],"a":0,"e":"心烦失眠、手足心热、口干欲饮而不多、舌红苔薄而干、脉细数，为心阴不足、虚热内扰、心神不宁。"},{"q":"患者，男，46岁。腹痛腹泻2天，日泻10余次水便，经治已缓，目前口渴心烦，皮肤干瘪，眼窝凹陷，舌淡白苔薄黄，脉细无力。其证候是","o":["津亏","阴虚","亡阳","外燥","实热"],"a":0,"e":"吐泻之后口渴心烦、皮肤干瘪、眼窝凹陷、尿少、舌淡白少津、脉细无力，为津液大量耗伤，属津亏证。"},{"q":"患者，男，45岁。突发耳鸣，声大如潮，按之不减，舌红苔黄，脉弦数，病机为","o":["阴虚火旺","肝胆火盛","肝肾阴虚","肾精亏损","心火亢盛"],"a":1,"e":"突发耳鸣、声大如潮、按之不减，属实证，兼舌红苔黄、脉弦数，为肝胆火盛、循经上扰清窍。"},{"q":"患者，男，65岁。突然昏倒，口吐涎沫，两目上视，四肢抽搐，醒后如常，辨证为","o":["癫证","狂证","痫证","中风","中暑"],"a":2,"e":"猝然昏倒、口吐涎沫、两目上视、四肢抽搐、醒后如常，为痫证发作，因痰浊蒙蔽心窍、肝风内动。"},{"q":"患者，女，38岁。近1个月来失眠反复发作，自觉眠浅、梦多，入睡尤难，时有心悸，甚则头晕眼花，自购“枣仁胶囊”服用，无明显好转。刻下：纳可，二便尚调，面色萎黄，唇、舌色淡，脉细无力。此属下列何证","o":["心阴虚证","心阳虚证","心气虚证","心血虚证","心火上炎证"],"a":3,"e":"失眠梦多、心悸头晕、面色萎黄、唇舌色淡、脉细无力，为心血亏虚、心失所养，属心血虚证。"},{"q":"最易导致太息的是","o":["肝风内动","肝气虚弱","肝气郁结","肝阳上亢","脾气虚弱"],"a":2,"e":"太息即叹息，为肝气郁结、气机不畅、欲以深长呼吸舒展气机之象，故最易由肝气郁结所致。"},{"q":"患者肢沉身困，关节酸胀重着，舌淡边有齿痕，脉濡，宜诊断为","o":["伤湿","冒湿","湿痹","湿温","湿疹"],"a":2,"e":"肢体重着、关节酸胀重着疼痛、舌淡边有齿痕、脉濡，为湿邪留着关节、阻遏气血、经气不利，属湿痹。"},{"q":"患者咯痰少而黏难出，口干舌燥，属","o":["热痰","燥痰","风痰","湿痰","寒痰"],"a":1,"e":"痰少黏稠难咯、口干舌燥，为燥邪伤肺、津液被灼，属燥痰；湿痰量多易咯，热痰则黄稠。"},{"q":"患者，男，45岁。突然四肢浮肿，按之凹陷，小便短少不利，周身困重，舌淡胖，苔白滑，脉缓，辨证为","o":["亡阳证","水停证","饮证","痰证","津液亏虚证"],"a":1,"e":"突然四肢浮肿、按之凹陷、小便短少不利、周身困重、舌淡胖苔白滑、脉缓，为水液停聚、泛溢肌肤。"},{"q":"心悸怔忡，面色萎黄，神疲乏力，纳少便溏，脉象细弱，辨证应为","o":["心气不足证","心血不足证","脾气血证","心肝血虚证","心脾两虚证"],"a":4,"e":"心悸怔忡、面色萎黄、神疲乏力、纳少便溏、脉细弱，为心血不足与脾气虚弱并见，属心脾两虚证。"},{"q":"患者恶寒发热，头身疼痛，无汗，鼻塞流涕，脉浮紧，其舌苔对应是","o":["白厚","薄白","黄腻","花剥","白腻"],"a":1,"e":"恶寒发热、头身疼痛、无汗、鼻塞流涕、脉浮紧，为风寒束表、邪未入里，舌苔多见薄白。"},{"q":"患者，女，55岁。身体灼热，烦躁不安，斑疹显露，甚或吐血、衄血，舌质红绛，脉弦数，其临床意义是","o":["血分实热","热扰心神","热郁胆经","热灼营阴","血分虚热"],"a":0,"e":"身体灼热、烦躁不安、斑疹显露、吐血衄血、舌质红绛、脉弦数，为热入血分、迫血妄行，属血分实热。"},{"q":"患者恶风，汗出，色淡苔白，脉浮缓，宜诊断为","o":["风淫证","暑淫证","燥淫证","火淫证","湿淫证"],"a":0,"e":"恶风、汗出、色淡苔白、脉浮缓，为风邪袭表、卫外不固、腠理开泄、营卫失和，属风淫证。"},{"q":"患者，男，25岁。咳喘，胸痛，痰黄黏稠，胸痛，舌红苔黄，脉数，其辨证为","o":["热扰心神","风热犯肺","热郁胆经","热邪壅肺","燥热犯肺"],"a":3,"e":"咳喘胸痛、痰黄黏稠、舌红苔黄、脉数，为邪热壅聚于肺、肺失清肃、灼津为痰，属热邪壅肺。"},{"q":"患者，女，31岁。3年来怀孕3次，均不足3个月而流产，听力减退，带下清稀，腰部酸痛，舌淡苔白，脉弱。其证候是","o":["肾气不固","肾精不足","肾阳虚","脾气下陷","脾肾阳虚"],"a":0,"e":"屡孕屡堕、听力减退、带下清稀、腰部酸痛、舌淡苔白、脉弱，为肾气亏虚、封藏固摄失职，属肾气不固。"},{"q":"患者咳嗽，咯痰黄稠，口干咽痛，发热微恶寒，舌红苔薄黄，脉数，应辨证为","o":["风热表证","风热犯肺证","肺热炽盛证","痰热壅肺证","燥邪犯肺"],"a":1,"e":"咳嗽痰黄稠、口干咽痛、发热微恶寒、舌红苔薄黄、脉数，为风热犯肺、卫表失和、肺失清肃。"},{"q":"患者咳嗽反复发作5年，气短胸闷，吐痰量多白黏，神疲食少，舌淡胖，苔白腻，脉弱，证属","o":["表邪入里","表里同病","虚实夹杂","实证转虚","虚证转实"],"a":2,"e":"咳喘日久、气短神疲食少为正气已虚，痰多白黏、苔白腻为痰湿内盛，正虚与邪实并存，故属虚实夹杂。"},{"q":"心悸怔忡，畏寒，尿少肢肿，唇甲青紫，舌淡紫，脉弱，宜诊断为","o":["瘀阻心脉证","肾阳虚证","心肾阳虚证","心脉痹阻证","心阳虚证"],"a":2,"e":"心悸怔忡、畏寒、尿少肢肿、唇甲青紫、舌淡紫、脉弱，为心阳不振与肾阳虚衰、水气凌心并见。"},{"q":"寒热往来，胸胁苦满，心烦喜呕，默默不欲饮食，口苦咽干，证属半表半里，最常见的脉象是","o":["浮脉","滑脉","弦脉","沉脉","涩脉"],"a":2,"e":"寒热往来、胸胁苦满、口苦咽干、心烦喜呕为少阳半表半里证，胆气不利、经气郁滞，脉多弦。"},{"q":"患者，男，65岁。自诉头胀头痛，伴有眩晕，自觉腰酸膝软，头重脚轻，步履不稳，面红目赤，平素性情急躁易怒，舌红少津，脉弦细而数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","肝风内动证"],"a":4,"e":"头胀痛眩晕、面红目赤、急躁易怒为肝阳亢逆，腰酸膝软、头重脚轻、步履不稳、脉弦细数，系阳亢无制而化风。"},{"q":"患者，女，20岁。发热恶寒，鼻塞，胸闷，咳嗽，头痛，舌边尖红，属","o":["上焦病变","中焦阳明燥热","下焦病变","上焦逆传心包","中焦太阴湿热"],"a":0,"e":"发热恶寒、鼻塞、胸闷、咳嗽、头痛、舌边尖红，为温邪初袭肺卫、病位在上焦，属上焦病变。"},{"q":"患者咳嗽气喘，胸闷痛，喉间痰鸣，痰黄稠量多，身热烦躁，口渴，尿黄便秘，舌红苔黄腻，考虑痰热壅肺，最可能的脉象是","o":["洪大脉","滑数脉","浮数脉","浮紧脉","沉数脉"],"a":1,"e":"痰黄稠量多、身热烦躁、口渴、苔黄腻，为痰热内盛，脉当滑而数；浮数主表热，与此里实热不符。"},{"q":"患儿，3岁。面黄肌瘦，肚腹膨胀，毛发稀疏，发结如穗，易烦躁激动，睡眠不宁，多食多便，舌淡，苔薄腻，脉沉细。宜诊断为","o":["疳气","疳积","干疳","慢脾风","佝偻病"],"a":1,"e":"面黄肌瘦、肚腹膨胀、毛发稀疏如穗、烦躁多食多便、苔薄腻，为积滞内停、脾胃受损之疳积。"},{"q":"患者，女，37岁。3年来经常疲乏无力，腹胀便溏，月经提前量多，每至10余日方止。近1年来经常心悸失眠，头晕健忘，面色萎黄，形体消瘦，舌淡苔白，脉弱。其心悸的病机是","o":["肝血亏虚","心肾不交","脾不统血","心血亏虚","心胆气虚"],"a":3,"e":"心悸失眠、头晕健忘、面色萎黄、舌淡脉弱，为心血亏虚、心失所养；腹胀便溏、月经量多另属脾气虚。"},{"q":"患者左侧乳房有形如鸡卵的硬结肿块，边界清楚，表面光滑，推之活动而不痛者，多为","o":["乳核","乳痨","乳癖","乳癌","乳疬"],"a":0,"e":"乳房硬结形如鸡卵、边界清楚、表面光滑、推之活动而不痛，为乳核，多因肝郁痰凝而成。"},{"q":"心悸健忘，失眠多梦，头晕目眩，两目干涩，肢体麻木，月经量少，色淡，甚则经闭，面白无华，爪甲不荣，舌淡脉细。宜诊断为","o":["心血虚证","肝血虚证","心肝血虚证","血虚证","心脾两虚证"],"a":2,"e":"心悸健忘、失眠多梦为心血不足，头晕目眩、两目干涩、肢麻、月经量少、爪甲不荣为肝血亏虚，故为心肝血虚证。"},{"q":"患者，男，31岁。几天前突发恶寒、寒战，继而又出现高热，每天下午3点左右反复发作，此症状多见于","o":["少阳病","湿温","疟疾","瘟疫","肺痈"],"a":2,"e":"寒战与高热交替、定时反复发作，为疟邪伏于半表半里、与正气相争所致，是疟疾的典型表现。"},{"q":"患者，女，20岁。发热恶风寒，头痛少汗，口干不渴，心烦谵语，舌红绛少苔，脉浮细数，其病变属于","o":["卫分证","气分证","营分证","气营同病","卫营同病"],"a":4,"e":"发热恶风寒、头痛少汗为邪在卫分，心烦谵语、舌红绛少苔、脉细数为热已入营，故为卫营同病。"},{"q":"患者，男，36岁。患胃病多年，今晚突然大量吐血，面唇俱白，冷汗淋漓，呼吸微弱，神志欠清，舌淡，脉浮大而散。临床诊断最可能是","o":["气不摄血证","气血两虚证","气随血脱证","亡阳证","亡阴证"],"a":2,"e":"大量吐血后旋即面唇苍白、冷汗淋漓、呼吸微弱、脉浮大而散，为血脱而气无所附、随血外脱，属气随血脱证。"},{"q":"患者，男，45岁。失眠反复发作3个月。平素时有心烦，口干，饮水较多；近来口舌糜烂，灼热疼痛，便秘，尿黄，舌尖红绛，苔黄，脉数有力。此属下列何证","o":["心阴虚证","胃阴虚证","心肾不交证","胃火炽盛证","心火亢盛证"],"a":4,"e":"口舌糜烂灼痛、心烦失眠、便秘尿黄、舌尖红绛、苔黄、脉数有力，为心火亢盛、上炎口舌、下移小肠。"},{"q":"患者，女，36岁，已婚，面色萎黄，神疲乏力，气短懒言，食少便溏，月经淋漓不断，经血色淡，舌淡无苔，脉沉细无力。其病机","o":["脾不统血","脾肾阳虚","气血两虚","脾肺气虚","肝血不足"],"a":0,"e":"月经淋漓不断、经血色淡，兼面色萎黄、神疲乏力、气短懒言、食少便溏、舌淡脉细，为脾气虚衰、统血无权。"},{"q":"患者右侧乳房触及无痛性肿块，质硬，形状不规则，边界不清，不易推动，腋窝多可扪及肿块，应考虑","o":["乳核","乳痨","乳癖","乳癌","乳疬"],"a":3,"e":"乳房肿块质硬、形状不规则、边界不清、推之不移，兼腋窝淋巴结肿大，为痰瘀毒结之乳癌。"},{"q":"患者眩晕耳鸣，头目胀痛，面红目赤，急躁易怒，腰膝酸软，头重足轻，舌红，脉弦细数。其证候是","o":["肝火上炎","肝阳上亢","肝阴不足","肝气郁结","肝阳化风"],"a":1,"e":"眩晕耳鸣、头目胀痛、面红目赤、急躁易怒为阳亢于上，腰膝酸软、头重足轻、脉弦细数为阴虚于下。"},{"q":"患者齿龈微肿出血，伴龈肉萎缩，牙根宣露，齿摇不坚，伴有头晕，耳鸣，手足心热，腰酸，舌质微红，少苔，脉细数，最宜辨证为","o":["胃火炽盛","脾虚失摄","痰湿凝聚","肝胆火旺","肾阴亏损"],"a":4,"e":"齿龈微肿出血而龈肉萎缩、牙根宣露、齿摇不坚，兼头晕耳鸣、手足心热、腰酸、舌红少苔、脉细数，为肾阴亏损、虚火上炎。"},{"q":"咳嗽痰少带血，体瘦，咽干，颧红，遗精，耳鸣，舌红少苔。宜诊断为","o":["肺燥津亏证","肺胃阴虚证","血热证","肝火犯肺证","肺肾阴虚证"],"a":4,"e":"咳嗽痰少带血、咽干颧红为肺阴虚，遗精耳鸣、舌红少苔为肾阴虚，金水相生、肺肾同病，故为肺肾阴虚证。"},{"q":"患者恶寒发热3日，今日起恶寒消失，高热恶热，口渴喜饮，舌红苔黄，脉洪数，证属","o":["表寒里热","风热犯肺","表热里寒","热证化寒","表邪入里"],"a":4,"e":"先见恶寒发热，继而恶寒消失而高热恶热、口渴喜饮、舌红苔黄、脉洪数，为表邪入里化热。"},{"q":"患者，男，48岁。症见身热，心烦，口苦，咽干，胸胁满痛，时有干呕，舌红，脉弦数，其临床意义是","o":["热结肠腑","热扰心神","热郁胆经","热扰胸膈","热邪壅肺"],"a":2,"e":"身热、心烦、口苦咽干、胸胁满痛、时有干呕、脉弦数，为热郁胆经、胆气不疏、横逆犯胃。"},{"q":"患者1周来泻下黄糜，排便不爽，气味臭秽，肛门灼热，病机为","o":["食滞肠胃","肝胆湿热","大肠湿热","脾胃虚弱","肾阳虚衰"],"a":2,"e":"泻下黄糜、排便不爽、气味臭秽、肛门灼热，为湿热蕴结大肠、气机阻滞、传导失常，属大肠湿热。"},{"q":"患者头项强痛、恶寒发热、四肢关节微痛、呕吐、胸胁苦闷，其证属","o":["少阴兼阳明病证","太阳兼少阳病证","太阳兼阳明病证","太阳病证","阳明病证"],"a":1,"e":"头项强痛、恶寒发热为太阳表证，呕吐、胸胁苦闷为少阳枢机不利，两经证候并见，故为太阳兼少阳病证。"},{"q":"患者，45岁。近1个月口渴多饮，小便量多，多食易饥，体渐消瘦，属","o":["阳明经证","痰饮内停","温病营分证","消渴病","里热炽盛"],"a":3,"e":"口渴多饮、小便量多、多食易饥、形体日渐消瘦，为消渴病三多一少之典型表现，由阴虚燥热所致。"},{"q":"患者语无伦次，举止失常，甚则精神狂乱，哭笑无常，宜诊断为","o":["喜伤证","忧伤证","思伤证","悲伤证","恐伤证"],"a":0,"e":"语无伦次、举止失常、精神狂乱、哭笑无常，为喜乐过极、心气涣散、神不守舍所致，属喜伤证。"},{"q":"患者昨夜起发热微恶寒，口干微渴，咳嗽，咽喉红肿疼痛，舌边尖红，脉浮数。证属","o":["表热证","表虚证","半表半里证","风寒束肺","表寒证"],"a":0,"e":"发热微恶寒、口干微渴、咽喉红肿疼痛、舌边尖红、脉浮数，为温邪袭表、卫分热盛，属表热证。"},{"q":"患者，女，35岁。反复胃脘隐痛10年，现症见：胃脘隐隐灼痛，饥不欲食，口燥咽干，大便干结，舌红少津，脉细数。诊为","o":["寒滞胃脘证","胃阴虚证","胃热炽盛证","肠燥津亏证","食滞胃脘证"],"a":1,"e":"胃脘隐隐灼痛、饥不欲食、口燥咽干、大便干结、舌红少津、脉细数，为胃阴不足、胃失濡养。"},{"q":"张某，女，41岁。近２个月来双目干涩不适，视物昏花，头晕，面白无华，月经量少，眼睑色淡，舌淡苔白，脉细弱。其目涩的病机为","o":["肝肾阴虚","肝血不足","肝阴不足","心血不足","肾精不足"],"a":1,"e":"双目干涩、视物昏花，兼面白无华、月经量少、眼睑色淡、舌淡苔白、脉细弱，为肝血不足、目失濡养。"},{"q":"患者恶热，汗出口渴，疲乏，尿黄，舌红苔白，脉虚，宜诊断为","o":["风淫证","暑淫证","燥淫证","火淫证","湿淫证"],"a":1,"e":"恶热、汗出、口渴、疲乏、尿黄、脉虚，为暑热伤气耗津之象；暑性升散，易致腠理开泄而气津两伤。"},{"q":"患者带下清稀量多，腰膝酸软，尿频，神疲乏力，舌淡脉弱，宜诊断为","o":["肾气不固证","脾肾阳虚证","肾阳虚证","寒湿困脾证","脾阳虚证"],"a":0,"e":"带下清稀量多、尿频、腰膝酸软、神疲乏力、舌淡脉弱，为肾气亏虚、封藏固摄失职，属肾气不固证。"},{"q":"患者，男，40岁。平素体壮，2日前出现咳嗽、气喘，咽喉红肿疼痛，口渴，小便短赤，大便秘结，舌红苔黄，脉数。辨证为","o":["燥邪犯肺证","痰热壅肺证","风热犯肺证","肺热炽盛证","肺阴虚证"],"a":3,"e":"咳嗽气喘、咽喉红肿疼痛、口渴、小便短赤、大便秘结、舌红苔黄、脉数，为邪热壅肺、肺失清肃。"},{"q":"患者神疲懒言，嗜睡体倦，气短乏力，多考虑","o":["劳力过度","劳神过度","房劳过度","过逸少动","情志损伤"],"a":0,"e":"神疲懒言、嗜睡体倦、气短乏力，为劳力过度、耗伤正气、脾肺气虚、脏腑功能减退所致。"},{"q":"患者反复咳喘10年，叩诊肺下界上移，应考虑","o":["肺痨","肺痿","肺痈","肺胀","肺热"],"a":1,"e":"久病咳喘致肺叶痿弱不用、体积缩小，故叩诊肺下界上移，属肺痿；肺胀则肺下界下移、叩呈过清音。"},{"q":"热扰神明引起的呕吐多表现为","o":["呕声微弱，吐势较徐缓","呕声壮厉，吐势较猛","呈喷射状呕吐","吐利，腹痛并作","朝食暮吐或暮食朝吐"],"a":2,"e":"热扰神明、颅内热盛则呕吐呈喷射状，伴头痛、神昏；吐势徐缓声低属虚寒，朝食暮吐属胃反。"},{"q":"患者项强，伴高热神昏，抽搐，舌红绛，脉弦数，多属","o":["风寒侵袭","热极生风","肾精亏损","阳亢化风","精气衰竭"],"a":1,"e":"项强伴高热、神昏、抽搐、舌红绛、脉弦数，为邪热炽盛、燔灼肝经、引动肝风，属热极生风。"},{"q":"患者，女，49岁。心悸，胸闷，气短3年，近日心前区刺痛，痛引左肩部、舌紫黯，脉涩。临床诊断最可能是","o":["气滞血瘀证","气虚血瘀证","气虚证","血瘀证","气血两虚证"],"a":1,"e":"心悸胸闷气短日久为气虚，心前区刺痛、痛引肩臂、舌紫黯、脉涩为血瘀，故属气虚血瘀证。"},{"q":"患者久病，面色苍白，却时而泛红如妆，属于","o":["心炎上炎","阳明经热","阴虚火旺","虚阳浮越","肝阳上亢"],"a":3,"e":"久病面色苍白而时泛红如妆、游移不定，为阴寒内盛、虚阳浮越于上之戴阳证，属真寒假热。"},{"q":"患者，女，57岁。患者平素眼睛干涩，口干，无其他不适症状，舌红少津，脉细无力，辨证为","o":["津液亏虚证","阴虚火旺证","津枯血燥证","津停气阻证","气阴两亏证"],"a":0,"e":"目干涩、口干、舌红少津、脉细无力，为津液亏耗、失于濡润，尚无潮热盗汗等虚火之象，故属津液亏虚证。"},{"q":"患者，男，28岁。3天前在外吃夜宵后，出现腹痛腹泻，下利黄糜味臭，肛门灼热，脉濡数，其所对应的舌象为","o":["舌红绛，苔黄燥","舌红瘦，苔薄白","舌淡白，苔黄裂","舌红，苔黄腻","舌淡白，苔白腻"],"a":3,"e":"下利黄糜臭秽、肛门灼热、脉濡数，为大肠湿热，舌当红、苔当黄腻；苔黄燥主燥热伤津，与此不符。"},{"q":"患者，男，30岁。昨日过食辛辣肥甘之品，今晨腹痛，泻下急迫不爽，粪色黄褐，气味臭秽，肛门灼热，小便短黄，舌红苔黄腻，脉濡数。属于","o":["肝胃不和","胃火炽盛","湿客胃肠","肝脾不调","大肠湿热"],"a":4,"e":"泻下急迫、粪色黄褐臭秽、肛门灼热、小便短黄、舌红苔黄腻、脉濡数，为湿热蕴结大肠、传导失常。"},{"q":"小便黄赤浑浊，伴臊臭味者，证属","o":["消渴病","膀胱虚寒","膀胱湿热","肾气不固","胃肠郁热"],"a":2,"e":"小便黄赤浑浊、臊臭明显，为湿热下注膀胱、气化不利，属膀胱湿热；膀胱虚寒则尿清而长。"},{"q":"咳痰带血，面红目赤，烦热，胁肋灼痛，脉弦数。宜诊断为","o":["肺热炽盛证","燥邪犯肺证","肺阴虚证","肝火犯肺证","肝火炽盛证"],"a":3,"e":"咳痰带血、面红目赤、烦热、胁肋灼痛、舌红、脉弦数，为肝火亢盛、木火刑金、灼伤肺络。"},{"q":"咳嗽，喘促，呼多吸少，动则尤甚，声低气怯，自汗遗尿，肢冷，面色、口唇青紫，舌淡，脉浮大无根。应诊断为","o":["肺气虚证","肺肾气虚证（肾不纳气证）","肾气虚证","心肺气虚证","肾阳虚证"],"a":1,"e":"咳喘呼多吸少、动则尤甚、声低气怯、自汗遗尿、肢冷、脉浮大无根，为肺肾气虚、摄纳无权。"},{"q":"患者右胁胀痛1个月，厌食油腻厚味，舌红苔黄腻，脉弦数，属","o":["脾胃湿热","肝胆湿热","痰湿内蕴","胃火炽盛","肝胃不和"],"a":1,"e":"右胁胀痛、厌食油腻厚味、舌红苔黄腻、脉弦数，为湿热蕴结肝胆、疏泄失职、胆汁不循常道。"},{"q":"患者，女，30岁。月经过多，甚则崩漏，面色无华，少气懒言，食少便溏，舌淡苔白，最有可能出现的脉象是","o":["弦滑脉","浮滑脉","洪数脉","沉涩脉","细弱脉"],"a":4,"e":"月经过多甚则崩漏而气血两伤，见面色无华、少气懒言、食少便溏、舌淡苔白，脉当细弱。"},{"q":"患者肌肤热，渴喜冷饮，汗出如油，热而味咸，烦躁不安，脉疾而无力，此属","o":["阴虚证","阳虚证","里实热证","亡阴证","亡阳证"],"a":3,"e":"肌肤热、汗出如油而味咸、渴喜冷饮、烦躁不安、脉疾而无力，为阴液耗竭、虚热内扰，属亡阴证。"},{"q":"患者胸闷气短，呕恶腹痛，甚则神志不清，猝然昏倒，脉伏，宜诊断为","o":["风淫证","寒淫证","暑淫证","湿淫证","火淫证"],"a":2,"e":"胸闷气短、呕恶腹痛，甚则神志不清、猝然昏倒、脉伏，为暑热卒中、蒙蔽清窍、耗伤气津。"},{"q":"下列属于湿疹表现的是","o":["疱疹色白，点细，形如粟粒","水疱破裂、渗液，出现红色湿润之糜烂","皮肤出现密集的红色尖粒，瘙痒刺痛，干燥后成细小鳞屑","水疱如针头至绿豆大小，伴瘙痒和烧灼感","皮肤灼热刺痛，出现成簇水疱，围以红晕"],"a":1,"e":"湿疹以水疱破裂、渗液流滋、出现红色湿润糜烂面为特征，多因湿热浸淫肌肤、蕴结不散。"},{"q":"下列何病多表现为咳声短促，咳后有鸡啼样回声","o":["顿咳","白喉","肺痨","肺痿","肺痈"],"a":0,"e":"咳声短促连声、咳后有鸡啼样回声，为顿咳即百日咳的特征性表现，因痰热恋肺、气道壅滞。"},{"q":"Page-FrameX年X月X日X时 XX科别记录以下内容：（1）前次诊疗后的病情变化，简要的辨证分析，补充诊断、更正诊断。（2）各种诊治措施的改变及其原因。（3）同一医师守方超过3次后要重新誊写处方。（4）3次没有确诊或疗效不佳者必须有上级医师的会诊意见。上级医师的诊疗意见应详细记录，并经上级医师签字负责。医师签名：以上病历书写格式是","o":["门诊病历的初诊记录","门诊病历的复诊记录","住院病历的初诊记录","住院病历的复诊记录","住院病历的病程记录"],"a":1,"e":"记录前次诊疗后病情变化、辨证分析、诊治措施改变及会诊意见，为门诊病历复诊记录的书写格式。"},{"q":"患者，男，43岁。干咳3年余。近1个月来，因过于劳累，咳嗽加剧，痰中带血丝，自觉手足心热，入睡后出汗，醒后汗止，尿少便干，两颧潮红，舌红苔少而干，脉细数。其证候是","o":["燥邪犯肺证","肝火犯肺证","邪热壅肺证","肺阴虚证","肺气虚证"],"a":3,"e":"干咳痰中带血、手足心热、盗汗、两颧潮红、尿少便干、舌红苔少而干、脉细数，为肺阴亏虚、虚火灼络。"},{"q":"病人发热1天，伴有恶寒，头痛，项强，脉浮，其证属","o":["太阳病证","阳明病证","少阳病证","少阴病证","太阴病证"],"a":0,"e":"发热恶寒、头痛项强、脉浮，为风寒袭表、太阳经气不利，属太阳病证，即伤寒初起之表证。"},{"q":"王某，男，40岁。3年来，每日早晨5时左右即感腹痛欲便，泻后痛减，便质清稀，夹杂有较多的不消化食物，并伴有怕冷，腰腿困痛，头晕耳鸣等症。查体：面色淡白，舌淡苔白而润，脉沉细而弱。此人所患病证是","o":["脾虚泄泻","肝郁泄泻","湿热泄泻","食积泄泻","脾肾阳虚泄泻"],"a":4,"e":"每日晨五更腹痛欲便、泻后痛减、完谷不化，兼怕冷、腰膝困痛、头晕耳鸣、脉沉细弱，为脾肾阳虚、命门火衰。"},{"q":"患者，女，49岁。失眠3个月。自觉眠浅梦多，入睡较难，平素自觉面红发热，心烦，口渴，时有胸闷气粗，偶有喉间痰鸣，咯吐黄痰，小便黄，大便干，舌质红苔黄腻，脉滑数。此属下列何证","o":["心阴虚证","痰火扰神证","胆郁痰扰证","肺热炽盛证","痰蒙心神证"],"a":1,"e":"失眠而面红心烦、胸闷气粗、喉间痰鸣、咯吐黄痰、舌红苔黄腻、脉滑数，为痰火内盛、上扰心神。"},{"q":"患者，男，68岁。近3个月来时感心悸心慌，左侧胸前区憋闷疼痛，肩背部及上臂内侧亦有不适感；平素体形肥胖，痰多色白，身重困倦，舌苔白腻，脉沉滑。此属下列何证","o":["寒痰阻肺证","痰阻心脉证","气滞心脉证","寒凝心脉证","瘀阻心脉证"],"a":1,"e":"心悸胸闷憋痛、痰多色白、身重困倦、形体肥胖、苔白腻、脉沉滑，为痰浊阻遏心脉、胸阳不展。"},{"q":"患者，女，60岁。近1年来经常心悸、胸闷气短、畏寒肢冷，未经系统诊治。半小时前因劳累过度突然心痛剧烈，胸闷持续不解，冷汗淋漓，呼吸微弱，四肢厥冷，唇色青紫，脉微欲绝。其胸痛的病机是","o":["心气亏虚","心阳亏虚","心血不足","心脉痹阻","痰蒙心神"],"a":3,"e":"心胸憋闷疼痛、痛引肩背、唇色青紫，为瘀血痰浊痹阻心脉、阳气不通；冷汗肢厥、脉微欲绝为阳气欲脱之危候。"},{"q":"患者，男，68岁。腹部膨隆，小便量少，周身困重，舌胖，苔白滑，脉缓，考虑为","o":["亡阴证","津液亏虚证","痰证","饮证","水停证"],"a":4,"e":"腹部膨隆、小便量少、周身困重、舌胖苔白滑、脉缓，为水液停聚腹腔、泛溢肌肤，属水停证。"},{"q":"患者，男，20岁。高考两度失利，情绪不佳，近1个月来逐渐躁动不宁，时常胡言乱语，乱摔书本，毁坏家具，父母阻之不得，甚则被其殴打。刻下：情绪躁急，面赤，舌质红，苔黄腻，脉滑数。此属下列何证","o":["肝阳上亢证","痰火扰神证","心火亢盛证","痰蒙心神证","胆郁痰扰证"],"a":1,"e":"情志不遂而躁动狂乱、打骂毁物、面赤、舌红苔黄腻、脉滑数，为痰火交炽、扰乱心神、神明逆乱。"},{"q":"患者小便频数清长，腰膝酸软，神疲乏力，形寒肢冷，舌淡脉弱，宜诊断为","o":["肾气不固证","脾肾阳虚证","肾阳虚证","脾虚气陷证","心肾阳虚证"],"a":2,"e":"小便频数清长、腰膝酸软、形寒肢冷、神疲乏力、舌淡脉弱，为肾阳不足、温煦失职、膀胱失约。"},{"q":"Page-Frame刘某，女，21岁，学生。2005年7月14日初诊。主诉：胃脘胀痛5年，加重3天，伴恶心。初诊：患者因住校就餐，饥饱不均，出现胃脘胀痛，在本地医院经胃镜检查诊断为慢性胃炎，用药不详，疗效不明显。近3天来胃脘胀痛，饥饿时明显，伴恶心、呃逆、呕吐，无反酸，腹胀，头晕，纳呆，二便调，睡眠佳。2002年做胃镜检查报告：慢性浅表性胃炎，反流性食管炎，Hp(-)。舌质淡红，苔薄白，脉平缓。诊为胃脘痛(慢性浅表性胃炎)：胃虚气滞证。治以补中和胃法。方拟香砂六君子汤加减。处方：党参10g，茯苓10g，炒白术10g，炙甘草6g，陈皮10g，法半夏6g，砂仁(后下)5g，焦曲6g，莱菔子5g，炒枳壳6g，淡干姜2g，大腹皮5g，干藿香5g，炒谷芽15g，大枣4g。4剂，水煎服，日1剂。嘱饮食宜软、烂、熟、温为佳。二诊：服药4剂后，胃脘胀痛好转，已不恶心，仍感腹胀，纳、便可；舌质淡红，苔薄白，脉平缓。前方奏效，效不更方。上方加佩兰6g，继服7剂。饮食宜忌同前。三诊：服药7剂后，胃脘胀痛消失，仍感腹胀，口干，纳少，便可。治以理气和胃。加郁金6g，香附6g，木香3g。7剂，水煎服，日1剂。饮食宜忌同前。按：患者长期饮食不节，造成脾胃虚弱，运化、受纳功能减退，气机不畅，则胃脘胀痛不适、腹胀、纳呆；胃气以降为顺，胃气不降反而上逆则恶心、呃逆、呕吐；清阳不升，则头晕。故病位在脾胃，病性为虚实夹杂。用香砂六君子汤健脾益气和胃，补后天之本，滋气血生化之源。本案在香砂六君子汤的基础上，加枳壳行气宽中除胀；莱菔子消食降气；炒谷芽、焦曲消食和中、健脾开胃；大腹皮下气宽中；干姜温胃止呕，藿香解暑化湿；大枣补脾和药。二诊时考虑到正值暑季，患者常有暑温夹湿的现象，因此加入佩兰以芳香化湿。三诊时胃痛已愈，仍腹胀、口干，说明气机仍然不畅，遂加郁金、香附疏肝理气；木香行气调中。香砂六君子汤出自《医方集解》，治疗脾胃气虚、寒湿滞于中焦之脘腹胀满疼痛等。本案准确运用经方，根据季节特点，灵活加减用药，而获此良效。以上案例记录属于","o":["中医医案","住院病历","病程记录","门诊病历复诊记录","住院病历复诊记录"],"a":0,"e":"该记录含主诉、现病史、舌脉、诊断、治法方药及按语，并有二诊三诊的随访经过，属中医医案。"},{"q":"患者时有左胸前区刺痛，常于夜间发作，面色略黯，舌尖有紫色斑点，脉弦涩。证属","o":["气滞证","气逆证","气闭证","血热证","血瘀证"],"a":4,"e":"左胸前区刺痛、常于夜间发作、面色黯、舌尖紫斑、脉弦涩，为瘀血阻滞心脉、痛有定处。"},{"q":"患者，男。腹中肿块时聚时散，按之无形，痛无定处，诊断为","o":["癥积","瘕聚","虫积","水鼓","痞证"],"a":1,"e":"腹中肿块时聚时散、按之无形、痛无定处，为气机聚散之瘕聚；癥积则固定不移、按之有形。"},{"q":"患者，女，23岁。右臀部溃疡5天，红肿高起，根盘紧束，灼热疼痛，舌淡红，苔黄，脉数，属","o":["痈","疽","疔","疖","丹毒"],"a":0,"e":"腹中肿块时聚时散、按之无形、痛无定处，为气机聚散无常之瘕聚；癥积则固定不移、按之有形。"},{"q":"若患者胃气不足，胃阴亏虚或气血两虚，则多见","o":["燥苔","腐苔","剥落苔","腻苔","滑苔"],"a":2,"e":"局部红肿高起、根盘紧束、灼热疼痛、易脓易溃，为痈的特征，因热毒壅聚、气血壅滞而成。"},{"q":"若患者感受寒湿之邪，或阳虚不能运化水液，则可出现","o":["燥苔","腻苔","滑苔","腐苔","剥落苔"],"a":2,"e":"剥落苔主胃气不足、胃阴亏虚或气血两虚，因胃之气阴亏乏不能上蒸生苔，苔失所养而剥落。"},{"q":"患者面部肌肉消瘦，两颧高耸，眼窝、面颊凹陷，伴全身骨瘦如柴，多见于","o":["气血亏虚","脏腑精血耗竭","吐泻伤津","肾精亏损","胃气衰败"],"a":1,"e":"滑苔主寒湿内盛，因感受寒湿之邪，或阳虚不能运化水液，水湿上泛而苔面水湿滑利、扪之湿冷。"},{"q":"患者项强，伴头痛，恶寒，脉浮，多属","o":["风寒侵袭","热极生风","肾精亏损","颈部肌肉劳损","精气衰竭"],"a":0,"e":"面部肌肉消瘦，两颧高耸，眼窝、面颊凹陷，全身骨瘦如柴，为久病脏腑精气耗竭、形体失于充养之征。"},{"q":"患者，女，65岁。体胖，平素怕冷。咳嗽10余天，痰多色白，气喘，形寒肢冷，舌淡，苔白滑，脉濡缓。辨证为","o":["饮停胸胁证","寒痰阻肺证","风寒犯肺证","风寒表证","风水搏肺证"],"a":1,"e":"项强伴头痛、恶寒发热、脉浮，为风寒袭表、太阳经气不利、筋脉拘急，属风寒侵袭之表实寒证。"},{"q":"病室有烂苹果气，可见于","o":["水肿病晚期","消渴病危重期","脱血夺气","脏腑败坏","瘟疫病"],"a":1,"e":"咳痰量多色白、气喘、形寒肢冷、舌淡胖苔白滑、脉濡缓，为寒痰内阻于肺、肺失宣降、气逆而喘。"},{"q":"患者新起恶寒重，微发热，无汗咳嗽气喘，舌红苔黄白相间，脉浮数。此属","o":["表热证","表寒证","表寒里热证","表热里寒证","里实热证"],"a":2,"e":"恶寒重、微发热、无汗、咳嗽气喘为表寒未解；舌红苔黄白相间、脉浮数，为里有郁热，故属表寒里热。"},{"q":"患者，男，45岁。心烦不寐，眩晕耳鸣健忘，腰酸梦遗，舌红少津，脉细数。其病变所在脏腑为","o":["心","肾","肝","心、肾","肝、胃"],"a":3,"e":"心烦不寐、眩晕耳鸣、健忘、腰酸梦遗、舌红少津、脉细数，为心火偏亢于上、肾阴亏虚于下，病位在心与肾。"},{"q":"患者腹泻反复发作2年，伴腹部坠胀，神疲乏力，头晕眼花，舌淡脉弱，证属","o":["气虚证","气血两虚证","气陷证","气不固证","血虚证"],"a":2,"e":"久泻而腹部坠胀、神疲乏力、头晕眼花、舌淡脉弱，为气虚日久、清阳不升、升举无力，属气陷证。"},{"q":"患者，女，47岁。反复胃脘隐痛3年，痛时喜按，胃脘痞满，纳少，嗳气，神疲乏力，少气懒言，舌淡苔薄白，脉弱。诊为","o":["胃气虚证","胃阳虚证","胃阴虚证","寒湿困脾证","食滞胃脘证"],"a":0,"e":"胃脘隐痛喜按、痞满纳少、嗳气、神疲乏力、少气懒言、舌淡苔薄白、脉弱，为胃气不足、受纳腐熟无力。"},{"q":"患者急躁冲动，眩晕耳鸣，纳呆食少，腹胀腹泻，泻后痛减，宜诊断为","o":["喜伤证","怒伤证","思伤证","惊伤证","恐伤证"],"a":1,"e":"急躁冲动、眩晕耳鸣、脉弦为肝气亢逆，纳呆腹胀、腹泻而泻后痛减为肝木乘脾，属怒伤证。"},{"q":"患者，女，61岁。症见身热夜甚，口干不欲饮，或斑疹隐隐，心烦，或时有谵语，舌绛，脉细数，其辨证为","o":["卫分证","气分证","营分证","血分证","气血两燔证"],"a":2,"e":"身热夜甚、口干不欲饮、斑疹隐隐、心烦谵语、舌绛、脉细数，为热灼营阴、内扰心神，属营分证。"},{"q":"患者，男，42岁。症见发热，恶寒，头痛，身重，胃脘部痞满，心烦，口渴，舌红苔白腻，脉濡数，其辨证为","o":["湿热犯卫","暑湿犯卫","热郁胆经","燥热犯肺","风热犯卫"],"a":1,"e":"暑湿之邪侵袭肌表，卫气被遏，故发热恶寒、头痛身重；湿阻中焦则脘腹痞满，暑热扰心则心烦口渴，舌红苔白腻、脉濡数为暑湿内盛之征。"},{"q":"患者胃脘冷痛，呕吐清涎，面色㿠白，舌苔白润，脉沉紧。证属","o":["表实寒证","表实热证","里实寒证","里虚寒证","里虚热证"],"a":2,"e":"寒邪直中胃腑，阳气被遏，故胃脘冷痛、呕吐清涎；脉沉紧主里实寒盛，面色㿠白、苔白润为寒凝津停之象，正气尚未大虚。"},{"q":"古人所称的“噫”是指","o":["呃逆","嗳气","少气","呵欠","矢气"],"a":1,"e":"噫即嗳气，指胃中浊气上逆出于咽喉而发出的沉长声响，为胃气上逆之轻证；《内经》所称“哕”才指呃逆，声短而频，二者当分。"},{"q":"患者，男，39岁。因丧失亲人而情志抑郁，胸胁满闷不舒，舌有紫斑紫点，脉弦。患者的病机是","o":["气血两虚","气虚血瘀","气滞血瘀","气随血脱","气滞血燥"],"a":2,"e":"情志不遂致肝失疏泄，气机郁滞，久则血行不畅而成瘀，故胸胁满闷而舌见紫斑紫点，脉弦为气滞之征。"},{"q":"患者，男，55岁。身热颧红，手足心热于手足背，口舌干燥，耳聋，舌红少苔，脉虚大，其临床意义是","o":["虚风内动证","肾阴亏虚证","肾气虚证","肝阴亏虚","肾阳虚证"],"a":1,"e":"手足心热甚于手足背、耳聋、口舌干燥、舌红少苔，为肾阴亏虚、虚热内扰之象；阴不敛阳故脉虚大。"},{"q":"患者，男，40岁。咳嗽半年，干咳少痰，痰中有血丝，口干咽燥，声音嘶哑，腰膝酸软，形瘦，骨蒸潮热，颧红，时有遗精，舌红少苔，最有可能出现的脉象是","o":["脉洪大","脉细数","脉弦数","脉缓弱","脉结代"],"a":1,"e":"久咳耗伤肺阴，病久及肾，肺肾阴虚、虚火内灼，故干咳少痰带血、骨蒸潮热、腰膝酸软，脉见细数。"},{"q":"患者鼻塞浊涕2日，鼻塞时轻时重，鼻痒气热，喷嚏，流黄稠浊涕，发热恶风，头痛，咽痛，口干喜饮。舌红，苔白，脉浮数。此病最宜辨证为","o":["外感风寒","外感风热","肺热壅盛","肺胃郁热","痰热壅肺"],"a":1,"e":"风热犯表，卫表失和，热邪上扰鼻窍，故鼻塞流黄稠涕、喷嚏咽痛、口干喜饮；发热恶风、脉浮数为风热在表之征。"},{"q":"患者，男，62岁。近半年来记忆力逐渐降低，时有举止失常，神情痴呆，甚则意识模糊。刻下：面色晦暗，时有胸闷，恶心欲呕，肢沉欲眠，舌苔白腻，脉滑。此属下列何证","o":["痰蒙心神证","痰火扰神证","胆郁痰扰证","瘀阻脑络证","肝阳化风证"],"a":0,"e":"痰浊上蒙心窍，神明失司，故神情痴呆、意识模糊；胸闷呕恶、肢沉欲眠、苔白腻、脉滑皆为痰湿内盛之象。"},{"q":"患者，女，29岁。经常手足心汗出量多，伴有午后自觉发热，舌红苔黄腻，其手足心汗出，属","o":["阳气内郁","阴虚内热","中焦湿热","阳明热盛","气虚不固"],"a":2,"e":"湿郁中焦，热蒸津泄，故手足心汗出量多而伴午后发热；舌红苔黄腻为湿热之征，阴虚内热当见舌红少苔而非黄腻。"},{"q":"患者自幼双睑下垂，无力抬举，伴疲乏无力，畏寒肢冷，小便清长，舌淡胖苔白，脉沉迟无力，多为","o":["命门火衰，脾阳不足","脾虚失运，中气不足","先天不足，肾精亏损","气血亏虚","脏腑精气衰竭"],"a":0,"e":"胞睑属脾，睑废无力为脾主肌肉失养；兼畏寒肢冷、小便清长、脉沉迟无力，是命门火衰不能温煦脾阳所致。"},{"q":"患者进食油腻食物后出现右胁下绞痛伴阵发性加剧，恶心欲吐，面色淡青，脉弦紧。证属","o":["气滞证","气逆证","血瘀证","气脱证","气闭证"],"a":4,"e":"结石阻滞胆腑，气机猝然闭塞不通，故胁下绞痛阵发加剧、面色淡青、脉弦紧；气闭属气机闭塞之实证。"},{"q":"患者，男，45岁。平日急躁易怒，今日因事与人争吵时突感头晕，站立不住，面赤如醉，舌体颤动，脉弦。其证候是","o":["肝火上炎","肝阳上亢","热极生风","肝阳化风","肝气郁结"],"a":3,"e":"肝阳亢逆无制而化风，风阳上扰清窍，故眩晕欲仆、面赤如醉；舌体颤动为风动之象，脉弦主肝病。"},{"q":"患者，女。主诉胸胁、少腹胀满疼痛，走窜不定，症状轻重与情绪变化有关，平素多情志抑郁不乐，善太息，舌苔薄白，脉弦。辨证属","o":["肝胆湿热证","肝郁气滞证","肝血虚证","肝风内动证","寒滞肝脉证"],"a":1,"e":"肝失疏泄，气机郁滞，故胸胁少腹胀痛走窜、善太息，症状随情志波动而增减，脉弦为肝郁之征。"},{"q":"患者，男，73岁。患者平素血脂较高，频繁早搏，平素性情抑郁，善太息。近3月来时有心悸，甚则心胸疼痛，痛引肩背内臂，时作时止。昨日因与邻居争执而诱发，舌淡红苔薄白，脉弦。此属下列何证","o":["肝郁气滞证","痰阻心脉证","气滞心脉证","寒凝心脉证","瘀阻心脉证"],"a":2,"e":"情志不遂致心气郁滞，心脉不畅，故心悸胸痛引肩背内臂、时作时止，脉弦为气滞之征；瘀阻心脉当见舌紫暗或有瘀斑。"},{"q":"太阳蓄血证，少腹急结，硬满，小便自利，人若发狂，大便色黑如漆，脉","o":["浮数","沉涩","浮缓","浮紧","洪大"],"a":1,"e":"太阳蓄血为瘀热互结下焦，气血阻滞，故少腹急结硬满、大便色黑如漆、其人如狂，脉沉涩主瘀血内停。"},{"q":"患者，男，34岁。身热，心烦懊憹，坐卧不安，舌苔微黄，脉数，其临床意义是","o":["热灼营阴","热扰心神","热郁胆经","热扰胸膈","热邪壅肺"],"a":3,"e":"热邪郁于胸膈，扰动心神，故身热、心烦懊憹、坐卧不安；舌苔微黄、脉数为里热之象，属栀子豉汤证。"},{"q":"患儿，2岁4个月大。口角流涎清稀，面色萎黄，消瘦乏力，纳差，大便稀薄，舌淡红，苔薄白，指纹淡红。宜诊断为","o":["气血亏虚","脾阳虚","肾阳虚","脾气亏虚","脾胃湿热"],"a":3,"e":"脾虚运化失健，水湿上溢则口角流涎清稀；纳差便溏、面色萎黄、消瘦乏力、指纹淡红均为脾气亏虚之征。"},{"q":"患者近日外感风邪，发热轻，恶风，头痛，自汗出，最可能的脉象是","o":["浮数","浮紧","浮缓","浮滑","弦数"],"a":2,"e":"风邪袭表，卫强营弱，营阴外泄故自汗出、发热而恶风；脉浮缓为太阳中风表虚证之典型脉象。"},{"q":"患者。男，56岁。头晕、头痛5年。前天头痛加重，并见口眼歪斜，语言不畅，时感四肢麻木，左半身不能活动，舌红，苔黄腻，脉弦滑。属于","o":["错语","言謇","谵语","郑声","狂言"],"a":1,"e":"风痰阻络，舌窍不利，故言语謇涩不畅而神志尚清；谵语、郑声皆属神识昏乱之言，与此不同。"},{"q":"患者，男，40岁。突见面色青灰，口唇青紫，肢凉脉微，辨证为","o":["心阳暴脱","阳虚水泛","阴虚火旺","脾虚湿蕴","气血不足"],"a":0,"e":"心阳骤脱，温运失职，故面色青灰、口唇青紫、四肢厥冷、脉微欲绝，属阳气暴脱之危候。"},{"q":"患者昨日因天气降温受凉，出现咳嗽，痰清稀色白，恶寒发热，无汗，鼻塞流涕，咽喉痒，舌苔薄白，最可能的脉象是","o":["浮滑脉","浮数脉","浮紧脉","沉细脉","浮缓脉"],"a":2,"e":"风寒束表，卫阳被遏，故恶寒发热、无汗、痰涕清稀而咽痒；脉浮紧为风寒表实证之典型脉象。"},{"q":"患者，男，73岁。2小时前突发心前区剧烈疼痛，急诊入院。刻下：面色发白，肢冷有汗出量多，神志模糊，呼之不应，唇舌青紫，脉微欲绝。此属下列何证","o":["痰蒙心神证","痰火扰神证","心阳虚脱证","瘀阻脑络证","心脉瘀阻证"],"a":2,"e":"心阳虚衰至极而阳气暴脱，故冷汗淋漓、肢冷脉微、神志模糊、唇舌青紫，属心阳虚脱之危候。"},{"q":"病人发热微恶寒，肢节烦痛，心下痞结，微呕，其证属","o":["少阳兼阳明病证","阳明兼太阳病证","少阳兼太阳病证","少阳病证","太阳病证"],"a":2,"e":"发热微恶寒、肢节烦痛为太阳表证未罢，心下痞结、微呕为少阳枢机不利，属太少兼病，即柴胡桂枝汤证。"},{"q":"患者，男，53岁。小便频数短赤、灼热涩痛3天。查尿常规，小便隐血（+++）。刻下：时有发热，面赤口渴，心烦失眠，舌尖有溃疡，灼热疼痛，舌红苔黄，脉数。此属下列何证","o":["肝火上炎证","痰火扰神证","肺热炽盛证","小肠实热证","膀胱湿热证"],"a":3,"e":"心火下移小肠，故小便频数短赤、灼热涩痛而尿血；心火上炎则舌尖溃疡、心烦失眠，为小肠实热之典型表现。"},{"q":"患者喘促声低，呼多吸少，动则益甚，腰膝酸软，舌淡，脉沉细。其证属于","o":["表证","寒证","虚证","热证","实证"],"a":2,"e":"喘促声低、呼多吸少、动则益甚，兼腰膝酸软、脉沉细，为肾不纳气、正气亏虚之候，当辨为虚证。"},{"q":"患者，女，33岁。近期出现崩漏，伴有面色淡白，心悸失眠，乏力，脉弱，辨证为","o":["气不摄血证","气血两虚证","气随血脱证","气滞血瘀证","气虚血瘀证"],"a":0,"e":"脾气虚弱，统摄无权，血溢脉外，故崩漏下血不止；面色淡白、心悸乏力、脉弱皆为气虚失摄之象。"},{"q":"患者，男，50岁。咳喘20余年，现咳嗽痰少，口燥咽干，形体消瘦，腰膝酸软，颧红盗汗，舌红少苔，脉细数。其病机是","o":["肺气虚损","肺阴虚亏","肺肾阴虚","肺肾气虚","肾气虚衰"],"a":2,"e":"久咳伤肺，病久及肾，肺肾阴虚而虚火内扰，故干咳少痰、腰膝酸软、颧红盗汗、舌红少苔、脉细数。"},{"q":"患者，女，30岁。因工作繁忙，近半年来出现白带绵绵不断，曾服清热除湿方药10余剂，未效。近1周连续加班劳累，带下量多，淋漓不断，色白质稀，无臭味，伴见面色萎黄，神倦乏力，少气懒言，纳呆食少，腰腹酸冷，手足不温，舌淡苔白，脉缓弱。该患者带下量多的病机为","o":["脾虚气陷","脾肾阳虚","湿浊下注","肝郁脾虚","寒湿下注"],"a":1,"e":"脾虚运化失职则湿浊下注，带下量多色白质稀；肾阳不足则腰腹酸冷、手足不温，故病机为脾肾阳虚。"},{"q":"患者，男，42岁。患精神分裂症多年，近半月来病情加重，出现狂躁妄动，胡言乱语，少寐多梦，打人毁物，不避亲疏，舌淡红，苔白，脉弦，属于","o":["狂病","癫病","痫病","惊风","脏躁"],"a":0,"e":"痰火扰心，神明逆乱，故狂躁妄动、胡言乱语、打人毁物、不避亲疏；癫病则以静默痴呆、语无伦次为特征。"},{"q":"患者，男。素嗜酒，咳嗽痰多。春节聚餐后，出现神志迷糊，满口痰涎粘连，两目瞪视，四肢厥冷，舌淡白，苔厚腻垢浊，脉沉迟有力。证属","o":["表寒证","里寒证","里热证","亡阳证","亡阴证"],"a":1,"e":"寒痰内闭，阳气被遏，故神志迷糊、四肢厥冷、苔厚腻垢浊；脉沉迟有力主里实寒盛，非阳气外脱。"},{"q":"患者，老年男性，体胖，有冠心病史。近半年来心胸部憋闷作痛，痛引肩背内臂，时作时止，身重困倦，舌苔白腻，最有可能出现的脉象是","o":["沉弦脉","弦细脉","细涩脉","沉滑脉","细数脉"],"a":3,"e":"痰浊盘踞胸中，痹阻心脉，故心胸憋闷作痛引肩背内臂、身重困倦、苔白腻；痰湿内盛则脉见沉滑。"},{"q":"以下何项不属于呃逆的常见原因","o":["偶感风寒","热邪客胃","胃气衰败","脾失健运","寒邪客胃"],"a":3,"e":"呃逆由胃气上逆动膈而成，寒邪、热邪客胃及胃气衰败均可致之；脾失健运多致腹胀便溏，非呃逆的直接成因。"},{"q":"患者今起头痛，恶寒重，发热，清涕，苔薄白而润，脉浮紧。证属","o":["里寒证","表寒证","实热证","虚热证","表热证"],"a":1,"e":"风寒袭表，卫阳被遏，故恶寒重、发热、流清涕；苔薄白而润、脉浮紧，皆为表寒实证之征。"},{"q":"吕某，男，51岁，军人。2016年7月9日初诊。胸闷，心悸，阵发性心前区刺痛1年，加重3天。1年来反复出现胸闷、心悸，偶有心前区刺痛。3天前因出差返家，旅途乘车劳累，到家用热水洗澡后，胸闷、心悸加重，伴心前区刺痛，经休息后稍缓解。此后因进餐胸闷、心悸复加重，并有阵发性心前区刺痛，向颈肩、左上肢放射，伴有下牙及腹部作痛，舌感麻木，急请医生到家查心电图，提示心肌缺血。平时患有高脂血症。急收入院。查：体胖高大，舌淡胖苔白厚，脉弦滑，血压14/8kPa（105/60mmHg），心律整，心率60次/min……病案中的“1年来反复出现胸闷、心悸……舌感麻木”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":2,"e":"现病史记述本次发病的主要症状特点、发展变化、伴随症状及诊治经过，该段内容正属此范畴。"},{"q":"患者脘部按之有形而胀痛，推之辘辘有声为","o":["气滞","血瘀","水饮","寒凝","气虚"],"a":2,"e":"水饮停聚胃脘，按之有形而胀痛，推之辘辘有声，即胃中有振水声，为饮停胃肠、气机阻滞之征。"},{"q":"患者男，65岁。渐发耳鸣，声小如闻蝉鸣，按之鸣减或暂止，病机为","o":["肝风内动","肝胆火盛","肝肾阴亏","气血亏损","肝经风火"],"a":2,"e":"肾开窍于耳，肝肾阴虚则耳窍失养，故耳鸣渐发、声细如蝉、按之减轻；暴鸣声大而拒按者多属实证。"},{"q":"患者，女，56岁。咳喘10年，伴见胸闷心悸，咯痰清稀，声低乏力，面白神疲，舌质淡白，脉弱。其证候是","o":["心肺气虚","肺气虚","寒邪客肺","脾肺气虚","肾不纳气"],"a":0,"e":"久咳伤肺，肺气虚则声低乏力、咯痰清稀；心气虚则胸闷心悸，舌淡白、脉弱为心肺气虚之征。"},{"q":"患者食少纳呆，腹胀便溏，久咳气短，声低懒言，舌淡苔白，脉缓弱。宜诊断为","o":["肺气虚证","心气虚证","心脾两虚证","心肺气虚证","肺脾气虚证"],"a":4,"e":"脾虚运化失职，故食少纳呆、腹胀便溏；肺虚则久咳气短、声低懒言，舌淡苔白、脉缓弱，两脏同病属肺脾气虚。"},{"q":"患者手足厥冷、喘促气粗、心烦谵语、舌红苔黄腻，其证属","o":["太阳经证","阳明腑证","少阳病证","阳明经证","太阳腑证"],"a":3,"e":"阳明经证为无形邪热亢盛，热郁于内不能外达则手足厥冷，热盛气逆则喘促气粗，热扰心神则心烦谵语。"},{"q":"患者出现身大热，大汗出，大渴引饮，面赤心烦，舌苔黄燥，最容易出现的脉象是","o":["濡细脉","滑数脉","洪大脉","沉迟脉","弦滑脉"],"a":2,"e":"阳明气分热盛，正邪剧烈相争，气血涌盛于脉道，故脉来洪大有力，为白虎汤证的典型脉象。"},{"q":"患者，男，35岁。2日前食自助餐后出现胃脘胀闷疼痛，嗳气吞酸，矢气便溏，泻下物酸腐臭秽，舌苔厚腻，脉滑。诊为","o":["湿热蕴脾证","肠热腑实证","肠燥津亏证","寒湿困脾证","食滞胃脘证"],"a":4,"e":"暴饮暴食，食积胃脘，胃失和降，故胃脘胀闷疼痛、嗳腐吞酸、泻下酸腐臭秽；苔厚腻、脉滑为食滞之征。"},{"q":"患者滑胎2次 ，腰酸腹坠，神疲乏力，舌淡苔白，宜诊断为","o":["脾虚气陷证","气血虚证","肾气不固证","肾精不足证","肾阳虚证"],"a":2,"e":"肾气亏虚，封藏失职，冲任不固，故屡孕屡堕、腰酸腹坠；神疲乏力、舌淡苔白为气虚之象。"},{"q":"姓名： 性别：年龄： 民族：婚况： 职业：发病节气： 出生地：常住地址： 单位：入院时间：X年X月X日X时 病史采集时间：X年X月X日X时病史陈述者： 可靠程度：主诉现病史（1）起病情况（2）主要症状特点及发展变化情况（3）伴随症状（4）发病以来诊治经过及结果（5）发病以来一般情况既往史个人史婚育史家族史中医望、闻、切诊体格检查专科情况辅助检查辨病辨证依据西医诊断依据初步诊断：中医诊断：病名（包括主要疾病和其他疾病）证名西医诊断：（包括主要疾病和其他疾病）实习医师（签名）住院医师（签名）以上病历书写格式是","o":["门诊病历","住院病历","病程记录","门诊病历复诊记录","住院病历复诊记录"],"a":1,"e":"该格式含主诉、现病史、既往史、中医望闻切诊、体格检查、辅助检查、辨病辨证依据及初步诊断等完整项目，为住院病历的书写格式。"}];
